/* src/ui/backglass.css */
.fd-reel {
  display: inline-flex;
  align-items: flex-end;
  gap: .1em;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
  --reel-h:1.4em;
  --reel-pad:.2em;
  --reel-tint:var(--bone);
  --reel-mix:4%;
}
.fd-reel-cell {
  position: relative;
  display: inline-block;
  height: var(--reel-h);
  overflow: hidden;
  padding: 0 var(--reel-pad);
  border-radius: .1em;
  background: color-mix(in srgb, var(--reel-tint) var(--reel-mix), var(--ink0));
  box-shadow: inset 0 0 0 .04em color-mix(in srgb, var(--ink0) 80%, transparent), 0 .04em 0 color-mix(in srgb, var(--bone) 10%, transparent);
}
.fd-reel-cell::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  border-radius: inherit;
  border-top: max(1px, .03em) solid color-mix(in srgb, var(--bone) 12%, transparent);
  box-shadow: inset 0 .28em .2em -.18em color-mix(in srgb, var(--ink0) 72%, transparent), inset 0 -.28em .2em -.18em color-mix(in srgb, var(--ink0) 72%, transparent);
}
.fd-reel-sizer {
  display: block;
  height: var(--reel-h);
  line-height: var(--reel-h);
  visibility: hidden;
}
.fd-reel-strip {
  position: absolute;
  left: var(--reel-pad);
  right: var(--reel-pad);
  top: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: translateY(calc(var(--d) * var(--reel-h) * -1));
  transition: transform var(--strip-ms, var(--motion-reel, 240ms)) var(--ease-drum, cubic-bezier(.3,1.35,.5,1));
}
.fd-reel-strip > span {
  display: block;
  height: var(--reel-h);
  line-height: var(--reel-h);
}
.fd-reel-sep {
  display: inline-block;
  height: var(--reel-h);
  line-height: var(--reel-h);
  margin: 0 .01em;
}
.fd-reel.is-you {
  color: var(--you);
  text-shadow: 0 0 12px rgba(255, 224, 74, .45);
  --reel-tint:var(--you);
  --reel-mix:9%;
}
.fd-reel.is-chip {
  color: var(--sun);
  --reel-tint:var(--sun);
  --reel-mix:8%;
}
.fd-reel.is-live {
  color: var(--lamp-live-text);
  --reel-tint:var(--lamp-live);
  --reel-mix:9%;
}
.fd-reel.is-won {
  color: var(--green);
  --reel-tint:var(--green);
  --reel-mix:8%;
}
.fd-reel.is-slim {
  --reel-h:1.3em;
  --reel-pad:.07em;
  gap: .05em;
}
.fd-reel.is-slim .fd-reel-sep {
  margin: 0 -.02em;
}
.fd-reel.is-landing .fd-reel-strip.is-rolling {
  animation: fd-reel-land var(--land-ms) linear calc(var(--land-at, 0ms) + var(--land-delay, 0ms)) backwards;
}
@keyframes fd-reel-land {
  0% {
    transform: translateY(calc(var(--s) * var(--reel-h) * -1));
    animation-timing-function: cubic-bezier(.16, .84, .3, 1);
  }
  86% {
    transform: translateY(calc((var(--e) + var(--ov)) * var(--reel-h) * -1));
    animation-timing-function: cubic-bezier(.45, 0, .4, 1);
  }
  100% {
    transform: translateY(calc(var(--e) * var(--reel-h) * -1));
  }
}
.fd-reel.is-drum .fd-reel-cell {
  perspective: 4.6em;
}
.fd-reel.is-drum .fd-reel-cell::after {
  box-shadow: inset 0 .36em .24em -.18em color-mix(in srgb, var(--ink0) 84%, transparent), inset 0 -.36em .24em -.18em color-mix(in srgb, var(--ink0) 84%, transparent);
}
.fd-drum {
  position: absolute;
  left: var(--reel-pad);
  right: var(--reel-pad);
  top: 0;
  height: var(--reel-h);
  transform-style: preserve-3d;
  --r:calc(var(--reel-h) * 1.5388);
  transform: translateZ(calc(var(--r) * -1)) rotateX(var(--a, 0deg));
  transition: transform var(--drum-ms, var(--motion-reel, 240ms)) var(--drum-ease, var(--ease-drum)) var(--drum-delay, 0ms);
}
.fd-drum-face {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--reel-h);
  line-height: var(--reel-h);
  text-align: center;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  transform: rotateX(calc(var(--i) * -36deg)) translateZ(var(--r));
}
.fd-reel.is-landing .fd-drum.is-rolling {
  animation: fd-drum-land var(--land-ms) var(--ease-drum-spin) calc(var(--land-at, 0ms) + var(--land-delay, 0ms)) backwards;
}
@keyframes fd-drum-land {
  from {
    transform: translateZ(calc(var(--r) * -1)) rotateX(var(--a0));
  }
}
.fd-reel.is-spinnable {
  touch-action: pan-x pinch-zoom;
  cursor: grab;
  -webkit-user-select: none;
  user-select: none;
}
@supports not (transform-style:preserve-3d) {
  .fd-drum {
    transform: none;
    transition: none;
    animation: none !important;
  }
  .fd-drum-face {
    transform: none;
    visibility: hidden;
  }
  .fd-drum-face.is-current {
    visibility: visible;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-reel-strip,
  .fd-drum {
    transition: none;
  }
  .fd-reel.is-landing .fd-reel-strip.is-rolling,
  .fd-reel.is-landing .fd-drum.is-rolling {
    animation: none;
  }
}
.fd-lamp {
  --lamp:var(--lamp-live);
}
.fd-lamp.is-chip {
  --lamp:var(--sun);
}
.fd-lamp.is-info {
  --lamp:var(--lamp-info);
}
.fd-lamp.is-you {
  --lamp:var(--you);
}
.fd-lamp.is-live,
.fd-lamp.is-pending {
  border-color: var(--lamp);
  box-shadow:
    0 0 0 1px var(--lamp),
    0 0 18px color-mix(in srgb, var(--lamp) 38%, transparent),
    var(--glass-edge);
}
.fd-lamp.is-pending {
  animation: fd-lamp-flash 1.2s steps(1, end) infinite;
}
.fd-lamp.is-done {
  box-shadow: var(--glass-edge);
  border-color: var(--line);
}
.fd-lamp.is-void {
  box-shadow: none;
  border-color: var(--line);
  opacity: .55;
  background-image:
    linear-gradient(
      to top right,
      transparent calc(50% - 1px),
      var(--muted) calc(50% - 1px),
      var(--muted) calc(50% + 1px),
      transparent calc(50% + 1px));
}
@keyframes fd-lamp-flash {
  0% {
    box-shadow:
      0 0 0 1px var(--lamp),
      0 0 18px color-mix(in srgb, var(--lamp) 38%, transparent),
      var(--glass-edge);
  }
  50% {
    box-shadow:
      0 0 0 1px color-mix(in srgb, var(--lamp) 55%, transparent),
      0 0 8px color-mix(in srgb, var(--lamp) 14%, transparent),
      var(--glass-edge);
  }
}
.fd-insert {
  position: relative;
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
  --lamp-on:var(--lamp, var(--lamp-live));
  --lens-lit:radial-gradient(
      circle at 50% 58%,
      color-mix(in srgb, var(--lamp-on) 45%, var(--bone)) 0 18%,
      var(--lamp-on) 48%,
      color-mix(in srgb, var(--lamp-on) 55%, var(--ink0)) 100%);
  --lens-off:radial-gradient(
      circle at 50% 58%,
      color-mix(in srgb, var(--lamp-on) 26%, var(--ink0)) 0 40%,
      color-mix(in srgb, var(--lamp-on) 10%, var(--ink0)) 100%);
  --lens-dim:radial-gradient(
      circle at 50% 58%,
      color-mix(in srgb, var(--lamp-on) 62%, var(--ink0)) 0 30%,
      color-mix(in srgb, var(--lamp-on) 30%, var(--ink0)) 100%);
  --lens-spent:radial-gradient(
      circle at 50% 58%,
      color-mix(in srgb, var(--muted) 34%, var(--ink0)) 0 40%,
      color-mix(in srgb, var(--muted) 14%, var(--ink0)) 100%);
  --lens-rim:0 0 0 1.5px rgba(0,0,0,.85), 0 0 0 2.5px color-mix(in srgb, var(--bone) 34%, transparent);
  background: var(--lens-lit);
  box-shadow: var(--lens-rim), 0 0 9px 1px color-mix(in srgb, var(--lamp-on) 60%, transparent);
}
.fd-insert::after {
  content: "";
  position: absolute;
  left: 20%;
  top: 13%;
  width: 36%;
  height: 27%;
  border-radius: 50%;
  background: color-mix(in srgb, var(--bone) 78%, transparent);
  transform: rotate(-24deg);
  pointer-events: none;
}
.fd-insert.is-pending {
  animation: fd-insert-flash 1.2s steps(1, end) infinite;
}
.fd-insert.is-done,
.fd-insert.is-void {
  background: var(--lens-spent);
  box-shadow: var(--lens-rim);
}
.fd-insert.is-done::after,
.fd-insert.is-void::after {
  opacity: .38;
}
.fd-insert.is-void::before {
  content: "";
  position: absolute;
  left: -3px;
  right: -3px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  z-index: 1;
  border-radius: 99px;
  background: var(--muted);
  transform: rotate(-38deg);
}
@keyframes fd-insert-flash {
  50% {
    background: var(--lens-dim);
    box-shadow: var(--lens-rim), 0 0 5px color-mix(in srgb, var(--lamp-on) 30%, transparent);
  }
}
.fd-you-lit {
  box-shadow: var(--you-bloom);
  border-color: var(--you) !important;
}
@media (prefers-reduced-motion: reduce) {
  .fd-lamp.is-pending,
  .fd-insert.is-pending {
    animation: none;
  }
}
.fd-chase {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  z-index: 1;
  --chase:var(--lamp-live);
}
.fd-chase.is-chip {
  --chase:var(--sun);
}
.fd-chase.is-you {
  --chase:var(--you);
}
.fd-chase rect {
  x: 4px;
  y: 4px;
  width: calc(100% - 8px);
  height: calc(100% - 8px);
  rx: 14px;
  ry: 14px;
  fill: none;
  stroke: var(--chase);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-dasharray: 0 9;
  filter: drop-shadow(0 0 4px var(--chase));
}
.fd-chase.is-running rect {
  animation: fd-chase 0.9s linear infinite;
}
@keyframes fd-chase {
  to {
    stroke-dashoffset: -9;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-chase.is-running rect {
    animation: none;
  }
}
.fd-show {
  font-family: var(--fd-show);
  font-weight: 900;
  letter-spacing: .01em;
  line-height: .95;
  text-transform: none;
}
.fd-show.is-marquee {
  font-family: var(--fd-marquee);
  font-weight: 900;
}
.fd-show.is-lit {
  color: var(--ink);
  text-shadow: 0 0 1px var(--lamp, var(--lamp-live)), 0 0 22px color-mix(in srgb, var(--lamp, var(--lamp-live)) 55%, transparent);
}
.fd-insert.fd-beat-dot {
  width: 12px;
  height: 12px;
  background: var(--lens-lit);
  animation-name: fd-beat-lamp;
}
.fd-one {
  position: relative;
  isolation: isolate;
  margin-left: .07em;
}
.fd-one::before {
  content: "-";
  position: absolute;
  z-index: -1;
  left: -.12em;
  top: -.285em;
  width: .23em;
  height: 1em;
  overflow: hidden;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
  text-transform: none;
  pointer-events: none;
  transform: rotate(-35deg);
  transform-origin: 100% .525em;
}
.fd-keep-case {
  text-transform: none;
}
.fd-glass-field {
  --field:var(--lamp-info);
  position: relative;
  isolation: isolate;
  border: 1px solid color-mix(in srgb, var(--field) 30%, transparent);
  border-radius: 14px;
  background:
    linear-gradient(
      112deg,
      transparent 0 64%,
      rgba(255, 255, 255, .03) 64% 71%,
      transparent 71%),
    color-mix(in srgb, var(--field) 8%, var(--bg));
  box-shadow: var(--glass-edge), 0 6px 16px -10px color-mix(in srgb, var(--ink0) 90%, transparent);
}
.fd-glass-field.fd-field-live {
  --field:var(--lamp-live);
}
.fd-glass-field.fd-field-chip {
  --field:var(--sun);
}
.fd-glass-field.fd-field-info {
  --field:var(--lamp-info);
}
.fd-glass-field::before {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 62%;
  height: 78%;
  z-index: -1;
  pointer-events: none;
  border-bottom-right-radius: inherit;
  background:
    radial-gradient(
      circle,
      color-mix(in srgb, var(--field) 34%, transparent) 0 1px,
      transparent 1.6px) 0 0 / 6px 6px;
  -webkit-mask-image:
    linear-gradient(
      to top left,
      #000,
      transparent 72%);
  mask-image:
    linear-gradient(
      to top left,
      #000,
      transparent 72%);
}
.fd-glass-field::after {
  content: "";
  position: absolute;
  inset: 4px;
  z-index: -1;
  pointer-events: none;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--field) 22%, transparent);
}
.fd-glass-field.fd-lamp.is-done {
  border-color: color-mix(in srgb, var(--field) 18%, transparent);
}
.fd-liquid {
  --liquid:color-mix(in srgb, var(--paper) 72%, var(--bg));
  background:
    var(--lg-bands),
    var(--lg-fall),
    var(--lg-caustic),
    var(--liquid);
  box-shadow:
    var(--lg-lip),
    var(--lg-fringe),
    var(--shadow-2);
}
.fd-liquid-sweep {
  position: relative;
  overflow: hidden;
  overflow: clip;
}
.fd-liquid-sweep::after {
  content: "";
  position: absolute;
  inset: -10% -60%;
  pointer-events: none;
  background: var(--lg-sweep);
  transform: translateX(-70%);
  animation: fd-liquid-sweep 1.4s var(--ease-out) .2s both;
}
@keyframes fd-liquid-sweep {
  to {
    transform: translateX(70%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-liquid-sweep::after {
    animation: none;
    opacity: 0;
  }
}
[data-glass-tilt] {
  touch-action: pan-y pinch-zoom;
}
[data-glass-tilt=on] {
  will-change: transform;
}
[data-glass-tilt=on] [data-glass-depth] {
  will-change: translate;
}
.fd-tilt-glare {
  position: absolute;
  inset: 0;
  z-index: 5;
  overflow: hidden;
  overflow: clip;
  border-radius: inherit;
  pointer-events: none;
  opacity: .5;
  transition: opacity .36s var(--ease-out);
}
.fd-tilt-glare > span {
  position: absolute;
  top: -15%;
  bottom: -15%;
  left: 0;
  width: 28%;
  background: color-mix(in srgb, var(--bone) 7%, transparent);
  box-shadow: inset 1px 0 0 color-mix(in srgb, var(--bone) 5%, transparent);
  transform: translateX(165%) skewX(-16deg);
}
@supports (animation-timeline:view()) {
  .fd-tilt-glare > span {
    animation: fd-glare-pass linear both;
    animation-timeline: view();
  }
}
@keyframes fd-glare-pass {
  from {
    transform: translateX(330%) skewX(-16deg);
  }
  to {
    transform: translateX(-70%) skewX(-16deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-tilt-glare > span {
    animation: none;
    transform: translateX(165%) skewX(-16deg);
  }
}
.fd-coin3d {
  position: relative;
  display: block;
  line-height: 0;
  transform-style: preserve-3d;
  --coin-color:var(--paper2);
  --coin-edge:color-mix(in srgb, var(--coin-color) 50%, var(--ink0));
}
.fd-coin3d.is-unlit {
  --coin-color:var(--ink0);
  --coin-edge:color-mix(in srgb, var(--muted) 28%, var(--ink0));
}
.fd-coin3d-face {
  position: relative;
  display: block;
}
.fd-coin3d-edge {
  position: absolute;
  inset: 2.5%;
  outline: 1px solid transparent;
  background:
    radial-gradient(
      circle closest-side,
      var(--coin-edge) calc(100% - 1px),
      transparent);
  transform: translateZ(calc(var(--z) * -.9px));
}
.fd-coin3d-edge:nth-child(5) {
  background:
    radial-gradient(
      circle closest-side,
      var(--coin-color) calc(100% - 3px),
      var(--coin-edge) calc(100% - 2px),
      var(--coin-edge) calc(100% - 1px),
      transparent);
}
.fd-coin3d-fly {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
}
@supports not (transform-style:preserve-3d) {
  .fd-coin3d-edge {
    display: none;
  }
}

/* src/ui/menu.css */
.fd-menu-section {
  margin: 0 0 18px;
}
.fd-menu-section:last-child {
  margin-bottom: 4px;
}
.fd-menu-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 2px 8px;
  color: var(--muted);
  font: 700 13px/1.15 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-menu-head-glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  color: var(--muted2);
}
.fd-menu-head-glyph > * {
  flex: 0 0 auto;
}
.fd-menu-list {
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper2);
  box-shadow: var(--glass-edge);
  overflow: hidden;
}
.fd-menu-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 52px;
  padding: 8px 12px 8px 14px;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.fd-menu-row.is-last {
  border-bottom: 0;
}
.fd-menu-row:not(:disabled):active {
  background: var(--ink-tint);
}
.fd-menu-row:disabled {
  cursor: default;
  opacity: .4;
}
.fd-menu-row[aria-busy=true] {
  opacity: .6;
}
.fd-menu-row:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: -3px;
}
.fd-menu-glyph {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  color: var(--muted2);
}
.fd-menu-name {
  flex: 1 1 auto;
  min-width: 0;
  font: 600 15px/1.3 var(--fd-body);
  overflow-wrap: anywhere;
}
.fd-menu-value {
  flex: 0 1 auto;
  max-width: 48%;
  color: var(--muted);
  font: 500 13px/1.3 var(--fd-body);
  text-align: right;
  overflow-wrap: anywhere;
}
.fd-menu-chevron {
  flex: 0 0 auto;
  display: inline-flex;
  color: var(--muted);
}
.fd-menu-row.is-destructive .fd-menu-name,
.fd-menu-row.is-destructive .fd-menu-glyph {
  color: var(--clay-text);
}
.fd-menu-section.is-danger .fd-menu-list {
  border-color: var(--danger-line);
}
.fd-menu-switch {
  position: relative;
  flex: 0 0 auto;
  width: 36px;
  height: 22px;
  border-radius: 99px;
  border: 1px solid var(--ghost-line);
  background: var(--bg);
}
.fd-menu-switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 99px;
  background: var(--muted);
  transition: transform .16s ease-out;
}
.fd-menu-switch.is-on {
  border-color: var(--lamp-info);
  background: var(--info-tint);
}
.fd-menu-switch.is-on::after {
  transform: translateX(14px);
  background: var(--lamp-info);
}
@media (prefers-reduced-motion: reduce) {
  .fd-menu-switch::after {
    transition: none;
  }
}

/* src/features/rules/rules.css */
.fd-rules {
  --rules-window:color-mix(in srgb, var(--ink0) 82%, transparent);
  color: var(--ink);
  min-width: 0;
}
.fd-rules-steps,
.fd-rules-notes {
  list-style: none;
  margin: 0;
  padding: 0;
}
.fd-rules-window {
  display: block;
  border-radius: 10px;
  color: var(--ink);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ink0) 92%, transparent),
      var(--rules-window) 38%);
  box-shadow:
    inset 0 2px 5px color-mix(in srgb, var(--ink0) 80%, transparent),
    inset 0 0 0 1px color-mix(in srgb, var(--ink0) 90%, transparent),
    0 1px 0 color-mix(in srgb, var(--bone) 12%, transparent);
}
.fd-rules-pic {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 64 / 40;
  overflow: visible;
}
.fd-rules-words {
  font: 800 15px/1.18 var(--fd-display);
  letter-spacing: .01em;
  color: var(--ink);
  overflow-wrap: normal;
}
.fd-rp-faint {
  opacity: .4;
}
.fd-rp-trail {
  stroke-dasharray: 0 3.1;
}
.fd-rp-lit {
  color: var(--sun);
}
.fd-rp-gone {
  opacity: .55;
  stroke-dasharray: 1.6 2.2;
}
.fd-rp-num {
  font-family: var(--fd-display);
  font-weight: 800;
  fill: currentColor;
  stroke: none;
}
.fd-rp-glass {
  fill: var(--ink0);
  stroke: none;
}
.fd-rp-glass-line {
  fill: none;
  stroke: var(--ink0);
}
.fd-rp-card,
.fd-rp-seat {
  fill: var(--ink0);
}
.fd-rp-wash {
  fill: currentColor;
  fill-opacity: .16;
  stroke: none;
}
.fd-rules.is-sheet .fd-rules-steps {
  display: grid;
  gap: 12px;
}
.fd-rules.is-sheet .fd-rules-step {
  position: relative;
  display: grid;
  grid-template-columns: minmax(120px, 44%) minmax(0, 1fr);
  align-items: center;
  gap: 16px;
}
.fd-rules.is-sheet .fd-rules-step + .fd-rules-step::before {
  content: "";
  position: absolute;
  top: -12px;
  height: 12px;
  width: 1px;
  left: calc(22% - .5px);
  background: var(--bone-line);
}
.fd-rules.is-sheet .fd-rules-words {
  font-size: 24px;
  line-height: 1.15;
}
.fd-rules.is-sheet .fd-rules-notes {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.fd-rules.is-card .fd-rules-steps {
  display: grid;
  grid-template-columns: repeat(var(--rules-cols, 3), minmax(0, 1fr));
  gap: 8px;
}
.fd-rules.is-card.is-4-up .fd-rules-steps {
  --rules-cols:4;
  gap: 6px;
}
.fd-rules.is-card.is-2-up .fd-rules-steps {
  --rules-cols:2;
}
.fd-rules.is-card.is-1-up .fd-rules-steps {
  --rules-cols:1;
}
.fd-rules.is-card .fd-rules-step {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.fd-rules.is-card .fd-rules-words {
  text-align: center;
  font-size: 15px;
}
.fd-rules.is-card.is-4-up .fd-rules-words {
  font-size: 14px;
}
.fd-rules.is-card .fd-rules-notes {
  margin-top: 12px;
}
.fd-rules-notes {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fd-rules-notes > li {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  font: 600 14px/1.25 var(--fd-body);
  color: var(--muted2);
}
.fd-rules-glyph {
  flex-shrink: 0;
  color: var(--ink);
}
.fd-rules.is-tv .fd-rules-steps {
  display: grid;
  grid-template-columns: repeat(var(--rules-cols, 4), minmax(0, 1fr));
  gap: 24px;
}
.fd-rules.is-tv .fd-rules-step {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
.fd-rules.is-tv .fd-rules-window {
  border-radius: 18px;
}
.fd-rules.is-tv .fd-rules-words {
  text-align: center;
  font-size: 34px;
  line-height: 1.15;
}
.fd-rules.is-tv .fd-rules-notes {
  margin-top: 24px;
  gap: 14px;
  align-items: center;
}
.fd-rules.is-tv .fd-rules-notes > li {
  gap: 12px;
  font-size: 28px;
  min-height: 40px;
}
@media (max-width: 359px) {
  .fd-rules.is-sheet .fd-rules-step {
    gap: 12px;
  }
  .fd-rules.is-sheet .fd-rules-words {
    font-size: 22px;
  }
  .fd-rules.is-card.is-4-up .fd-rules-steps {
    --rules-cols:2;
    gap: 10px 8px;
  }
}

/* src/features/weekend/weekend.css */
.fd-weekend {
  padding: 0 22px 30px;
  color: var(--ink);
  font-family: var(--fd-body);
  min-width: 0;
}
.fd-weekend *,
.fd-weekend *::before,
.fd-weekend *::after {
  box-sizing: border-box;
}
.fd-weekend button,
.fd-weekend a {
  -webkit-tap-highlight-color: transparent;
}
.fd-weekend button:focus-visible,
.fd-weekend a:focus-visible,
.fd-weekend summary:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-weekend-host-tools {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
}
.fd-weekend-host-tools button {
  min-height: 44px;
  padding: 9px 13px;
  font: 700 12px var(--fd-body);
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  cursor: pointer;
}
.fd-weekend-host-tools button:first-child {
  margin-right: auto;
}
.fd-weekend-host-tools button[aria-pressed=true] {
  background: var(--info-tint);
  color: var(--lamp-info);
  border-color: var(--lamp-info);
}
.fd-weekend-host-tools button:disabled,
.fd-weekend-reorder button:disabled {
  opacity: .3;
  cursor: default;
}
.fd-weekend-session {
  margin: 0 0 24px;
}
.fd-weekend-session-heading {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 0 0 10px;
}
.fd-weekend-session.is-live .fd-weekend-session-heading h2 {
  color: var(--ink);
}
.fd-weekend-session-heading > div {
  min-width: 0;
  flex: 1;
}
.fd-weekend-session-heading p {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
}
.fd-weekend-session-heading h2 {
  font-family: var(--fd-display);
  font-size: 24px;
  line-height: 1.1;
  letter-spacing: .04em;
  text-transform: uppercase;
  margin: 0;
  font-weight: 800;
}
.fd-weekend-session-number {
  align-self: stretch;
  display: flex;
  align-items: center;
  font-family: var(--fd-display);
  font-size: 40px;
  line-height: 1;
  font-weight: 500;
  color: var(--accent2);
}
.fd-weekend-session-value {
  color: var(--muted2);
  font-size: 12px;
  line-height: 1.4;
  font-weight: 650;
  white-space: nowrap;
}
.fd-weekend-session-fin .fd-weekend-session-value {
  background: var(--sun);
  color: var(--ink0);
  border-color: var(--sun);
}
.fd-weekend-event-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}
.fd-weekend-event {
  margin: 0;
  padding: 0;
  border-bottom: 1px solid var(--line);
  position: relative;
}
.fd-weekend-event-line {
  display: flex;
  align-items: center;
  gap: 4px;
}
.fd-weekend-event-open {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 60px;
  padding: 10px 0;
  border: 0;
  background: transparent;
  width: 100%;
  min-width: 0;
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform .15s ease;
}
.fd-weekend-event-open:active:not(:disabled) {
  transform: translateX(3px);
}
.fd-weekend-event-open:disabled {
  cursor: default;
  opacity: 1;
}
.fd-weekend-event-mark {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  color: var(--ink);
  font-family: var(--fd-display);
  font-size: 24px;
}
.fd-weekend-event-name {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 5px;
  flex: 1;
}
.fd-weekend-event-name > strong {
  font-size: 24px;
  line-height: 1.05;
  overflow-wrap: anywhere;
}
.fd-weekend-event-status {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted2);
  font: 800 14px/1.1 var(--fd-display);
  letter-spacing: .05em;
  text-transform: uppercase;
}
.fd-weekend-event-status.is-live {
  color: var(--ink);
}
.fd-weekend-event-arrow {
  display: flex;
  padding-left: 6px;
  color: var(--muted2);
}
.fd-weekend-event-arrow.is-done {
  color: var(--green);
}
.fd-weekend-event.is-done .fd-weekend-event-name > strong {
  color: var(--muted2);
}
.fd-weekend-event.is-void .fd-weekend-event-name > strong {
  color: var(--muted);
  text-decoration: line-through;
  text-decoration-thickness: 2px;
}
.fd-weekend-event.is-on-deck {
  background: var(--ink-tint);
  padding-inline: 12px;
  margin-inline: -12px;
  border-radius: 10px;
}
.fd-weekend-event.is-finale .fd-weekend-event-mark {
  background: var(--sun);
  color: var(--ink0);
}
.fd-weekend-winners {
  display: flex;
  flex-wrap: wrap;
  gap: 0 10px;
  align-items: center;
  padding: 0 0 6px 48px;
}
.fd-weekend-winner {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 650;
  min-height: 44px;
  border: 0;
  padding: 4px 0;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.fd-weekend-winner:disabled {
  cursor: default;
}
.fd-weekend-event-crew {
  padding: 0 0 12px 53px;
}
.fd-weekend-reorder {
  display: flex;
  flex-shrink: 0;
  gap: 4px;
}
.fd-weekend-reorder button {
  width: 44px;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: transparent;
  font: 600 22px var(--fd-body);
  color: var(--ink);
  cursor: pointer;
}
.fd-weekend-shelved .fd-weekend-event {
  opacity: .65;
}
.fd-weekend-session.is-folded {
  margin-bottom: 0;
  border-block: 1px solid var(--line);
}
.fd-weekend-session.is-folded + .fd-weekend-session.is-folded {
  border-top: 0;
}
.fd-weekend-session.is-folded + .fd-weekend-session:not(.is-folded) {
  margin-top: 24px;
}
.fd-weekend-session-fold {
  margin: 0;
  font: inherit;
}
.fd-weekend-session-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 52px;
  padding: 6px 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-weekend-session.is-done:not(.is-folded) .fd-weekend-session-toggle {
  margin-bottom: 4px;
}
.fd-weekend-session-name {
  flex: 1;
  min-width: 0;
  font: 800 21px/1.1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--muted2);
}
.fd-weekend-session-winners {
  flex-shrink: 0;
}
.fd-weekend-session-count {
  flex-shrink: 0;
  color: var(--muted2);
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}
.fd-weekend-session-toggle[aria-expanded=true] .fd-weekend-rule-toggle::after {
  transform: rotate(0);
}
.fd-weekend-error {
  font-size: 12px;
  line-height: 1.4;
  color: var(--accent2);
}
.fd-weekend-guide-section {
  margin: 0 0 22px;
  scroll-margin-top: 80px;
}
.fd-weekend-install {
  border-top: 1px solid var(--line);
}
.fd-weekend-install summary {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  color: var(--muted2);
  cursor: pointer;
  font-size: 15px;
  list-style: none;
}
.fd-weekend-install summary::-webkit-details-marker {
  display: none;
}
.fd-weekend-install summary > span {
  flex: 1;
}
.fd-weekend-install summary > svg:first-child {
  flex: none;
}
.fd-weekend-install-toggle {
  transition: transform var(--motion-base,260ms) var(--ease-out,ease-out);
}
.fd-weekend-install[open] .fd-weekend-install-toggle {
  transform: rotate(180deg);
}
.fd-weekend-install[open] {
  padding-bottom: 12px;
}
@media (min-width: 500px) {
  .fd-weekend-event-name > strong {
    font-size: 25px;
  }
  .fd-weekend-session-heading h2 {
    font-size: 24px;
  }
}
@media (max-width: 359px) {
  .fd-weekend {
    padding-inline: 18px;
  }
  .fd-weekend-session-heading {
    gap: 8px;
  }
  .fd-weekend-session-heading h2 {
    font-size: 22px;
  }
  .fd-weekend-session-number {
    font-size: 28px;
  }
  .fd-weekend-session-value {
    font-size: 12px;
  }
  .fd-weekend-event-open {
    gap: 9px;
  }
  .fd-weekend-event-mark {
    width: 35px;
  }
  .fd-weekend-event-name > strong {
    font-size: 22px;
  }
  .fd-weekend-winners,
  .fd-weekend-event-crew {
    padding-left: 44px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-weekend-event-open,
  .fd-weekend-rule-toggle::after {
    transition: none;
  }
}
.fd-weekend-howto {
  font-family: var(--fd-body);
  color: var(--ink);
  padding: 0 0 8px;
  min-width: 0;
}
.fd-weekend-howto * {
  box-sizing: border-box;
}
.fd-weekend-howto-objective {
  margin: 0;
  font: 600 16px/1.5 var(--fd-body);
  color: var(--ink);
}
.fd-weekend-howto-variants {
  display: flex;
  gap: 4px;
  background: var(--paper2);
  padding: 4px;
  border-radius: 8px;
  margin: 0 0 16px;
}
.fd-weekend-howto-variants button {
  flex: 1;
  min-width: 0;
  min-height: 44px;
  padding: 8px;
  border: 0;
  border-radius: 6px;
  color: var(--ink);
  background: transparent;
  font: 700 12px/1.2 var(--fd-body);
  cursor: pointer;
}
.fd-weekend-howto-variants button[aria-pressed=true] {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-weekend-install .fd-section-heading {
  margin-top: 0;
}
.fd-weekend-event-bracket {
  flex-shrink: 0;
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: transparent;
  color: var(--lamp-info);
  font: 600 13px/1 var(--fd-body);
  cursor: pointer;
}
.fd-weekend-event-bracket:hover {
  background: var(--info-tint);
}
.fd-weekend-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  margin: 0;
}
.fd-program-cue {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px;
  border-radius: 99px;
  background: color-mix(in srgb, var(--ink0) 70%, transparent);
  color: var(--ink);
  font: 800 13px/1 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}

/* src/features/weekend/competition-bracket.css */
.fd-competition-bracket {
  min-width: 0;
}
.fd-bracket-scroll {
  overflow-x: auto;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 4px;
  scroll-snap-type: x proximity;
}
.fd-competition-bracket:not(.is-compact) .fd-bracket-match {
  scroll-snap-align: start;
}
.fd-bracket-heads {
  position: relative;
  height: 22px;
  margin-bottom: 6px;
}
.fd-bracket-heads span {
  position: absolute;
  top: 0;
  color: var(--muted2);
  font: 800 13px/22px var(--fd-display);
  letter-spacing: .02em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-bracket-stage {
  position: relative;
}
.fd-bracket-line {
  position: absolute;
  overflow: visible;
  color: var(--ghost-line);
  pointer-events: none;
}
.fd-bracket-line path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5px;
}
.fd-bracket-line.is-advanced {
  color: var(--green);
}
.fd-bracket-match {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper2);
  overflow: hidden;
}
.fd-bracket-match.is-current {
  border-color: var(--lamp-live);
}
.fd-bracket-match-label {
  flex: 0 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  padding: 0 9px;
  color: var(--muted);
  font: 500 12px/22px var(--fd-body);
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
.fd-bracket-match-label strong {
  color: var(--ink);
  font-weight: 600;
}
.fd-bracket-lamp {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.fd-bracket-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  margin: 0;
}
.fd-bracket-team {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  min-width: 0;
}
.fd-bracket-team + .fd-bracket-team {
  border-top: 1px solid var(--line);
}
.fd-bracket-team.is-empty .fd-bracket-name {
  color: var(--disabled);
  font-weight: 400;
}
.fd-bracket-team.is-winner {
  background: var(--green-tint);
}
.fd-bracket-team.is-winner .fd-bracket-name,
.fd-bracket-outcome {
  color: var(--green);
}
.fd-bracket-team.is-loser .fd-bracket-name {
  color: var(--muted);
  font-weight: 400;
}
.fd-bracket-team.is-loser .fd-bracket-players {
  opacity: .55;
}
.fd-bracket-team.is-you {
  box-shadow: none;
  outline: 1.5px solid var(--you);
  outline-offset: -4px;
  border-radius: 10px;
}
.fd-bracket-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  line-height: 1.25;
  padding-bottom: 1px;
  overflow-wrap: break-word;
}
.fd-bracket-pick {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
  min-width: 0;
  height: 100%;
  min-height: 44px;
  padding: 0 9px 0 4px;
  border: 0;
  background: none;
  color: var(--ink);
  font: 600 12.5px/1.2 var(--fd-body);
  text-align: left;
}
.fd-bracket-pick:disabled {
  opacity: 1;
  cursor: default;
}
.fd-bracket-pick:not(:disabled) {
  cursor: pointer;
}
.fd-bracket-pick:not(:disabled):hover {
  background: var(--sun-tint);
}
.fd-bracket-pick-hint {
  flex-shrink: 0;
  padding: 3px 7px;
  border-radius: 99px;
  background: var(--sun);
  color: var(--ink0);
  font-size: 12px;
  font-weight: 700;
}
.fd-bracket-players {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding-left: 2px;
}
.fd-bracket-players button {
  display: grid;
  place-items: center;
  width: 36px;
  min-width: 36px;
  height: 44px;
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
  border-radius: 6px;
}
.fd-bracket-players button:first-child {
  width: 44px;
  min-width: 44px;
}
.fd-bracket-players button:disabled {
  cursor: default;
}
.fd-bracket-pick:focus-visible,
.fd-bracket-players button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: -3px;
}
.fd-competition-bracket.is-compact .fd-bracket-scroll {
  overflow: visible;
  padding: 0;
}
.fd-competition-bracket.is-compact .fd-bracket-heads {
  height: 16px;
  margin-bottom: 4px;
}
.fd-competition-bracket.is-compact .fd-bracket-heads span {
  font-size: 12px;
  line-height: 16px;
  letter-spacing: 0;
}
.fd-competition-bracket.is-compact .fd-bracket-match {
  border-radius: 8px;
  container-type: inline-size;
}
@container (max-width:129px) {
  .fd-competition-bracket.is-compact .fd-bracket-team:not(.is-empty) .fd-bracket-name {
    display: none;
  }
  .fd-competition-bracket.is-compact .fd-bracket-team {
    justify-content: space-between;
  }
}
.fd-competition-bracket.is-compact .fd-bracket-team {
  gap: 4px;
  padding: 0 5px;
  color: var(--ink);
  font: 600 12px/1.25 var(--fd-body);
}
.fd-bracket-faces {
  display: flex;
  flex-shrink: 0;
}
.fd-bracket-faces {
  gap: 3px;
}
.fd-competition-bracket.is-compact .fd-bracket-outcome {
  font-size: 12px;
}
.fd-competition-bracket.is-compact .fd-bracket-name {
  line-height: 1.15;
  padding-bottom: 0;
}
.fd-competition-bracket.is-compact .fd-bracket-faces {
  gap: 1px;
}
@media (prefers-reduced-motion: no-preference) {
  .fd-bracket-match,
  .fd-bracket-line {
    transition: border-color .2s ease, color .3s ease;
  }
}
.fd-bracket-peek {
  display: grid;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding: 12px 14px 14px;
  border: 0;
  border-top: 1px solid var(--line);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  font: inherit;
}
.fd-bracket-peek:hover {
  background: var(--ink-tint);
}
.fd-bracket-peek:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: -2px;
}
.fd-bracket-peek-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 20px;
}
.fd-bracket-peek-head > span:first-child {
  color: var(--muted2);
  font: 600 13px/1.2 var(--fd-body);
  letter-spacing: .08em;
  text-transform: uppercase;
  font-family: var(--fd-display);
  font-weight: 800;
  letter-spacing: .06em;
}
.fd-bracket-peek-head > span:last-child {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--lamp-info);
  font: 600 14px/1.2 var(--fd-body);
}
.fd-bracket-peek.is-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
}
.fd-bracket-line.is-bye {
  color: var(--lamp-info);
}
.fd-bracket-line.is-bye path {
  stroke-dasharray: 4 3;
}
.fd-bracket-bye {
  --lamp:var(--lamp-info);
  flex: none;
  width: 10px;
  height: 10px;
  margin: 0 6px 0 4px;
}
.fd-bracket-team.is-bye {
  background: color-mix(in srgb, var(--lamp-info) 7%, transparent);
}

/* src/features/results/place-picker.css */
.fd-pp {
  display: grid;
  gap: 18px;
}
.fd-pp .is-place-0 {
  --place:var(--sun);
}
.fd-pp .is-place-1 {
  --place:var(--silver);
}
.fd-pp .is-place-2 {
  --place:var(--bronze);
}
.fd-pp .is-place-crew {
  --place:var(--muted);
}
.fd-pp-podium {
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--pp-cols), minmax(0, 1fr));
  align-items: end;
  gap: 6px;
  width: 100%;
  max-width: calc(var(--pp-cols) * 138px);
  margin-inline: auto;
}
.fd-pp-podium::after {
  content: "";
  position: absolute;
  left: -8px;
  right: -8px;
  bottom: 0;
  height: 1px;
  background: var(--ghost-line);
}
.fd-pp-socket {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
}
.fd-pp-seat {
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  align-content: flex-end;
  align-items: flex-end;
  justify-content: center;
  gap: 4px 2px;
  min-height: 112px;
  padding: 0 2px 8px;
}
.fd-pp-socket.is-tieable.is-filled .fd-pp-seat {
  padding-top: 38px;
}
.fd-pp-podium.is-still .fd-pp-seat {
  min-height: 76px;
}
.fd-pp-step {
  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 6px;
  width: 100%;
  height: calc(72px * var(--rise));
  min-height: 44px;
  margin: 0;
  padding: 9px 4px 0;
  border-radius: 10px 10px 0 0;
  border: 1px solid var(--line);
  border-bottom: 0;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 9%, var(--paper2)) 0,
      var(--paper2) 22%,
      color-mix(in srgb, var(--ink0) 30%, var(--paper2)) 100%);
  box-shadow: var(--glass-edge);
  -webkit-tap-highlight-color: transparent;
  transition: border-color var(--motion-fast, 140ms) var(--ease-out, ease-out), box-shadow var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
div.fd-pp-step {
  cursor: default;
}
.fd-pp-socket.is-place-0 .fd-pp-step {
  border-color: color-mix(in srgb, var(--sun) 45%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--sun) 22%, var(--paper2)) 0,
      color-mix(in srgb, var(--sun) 9%, var(--paper2)) 24%,
      color-mix(in srgb, var(--ink0) 25%, var(--paper2)) 100%);
}
.fd-pp-socket.is-place-crew .fd-pp-step {
  background: transparent;
  border: 1px dashed var(--muted);
  border-bottom: 0;
  box-shadow: none;
}
.fd-pp-medal {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--place);
  color: var(--ink0);
  border: 2px solid var(--ink0);
  font: 800 13px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--ink0) 20%, transparent);
}
.fd-pp-amount {
  font: 800 19px/22px var(--fd-display);
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  letter-spacing: .01em;
}
.fd-pp-socket.is-place-0 .fd-pp-amount {
  color: var(--sun);
}
.fd-pp-crew {
  font: 700 12px/22px var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted2);
}
.fd-pp-socket.is-place-crew .fd-pp-amount {
  color: var(--muted2);
}
.fd-pp-lock {
  position: absolute;
  right: 7px;
  bottom: 7px;
  display: flex;
  color: var(--muted);
}
.fd-pp-step:active:not(:disabled) {
  transform: translateY(1px);
}
.fd-pp-step:focus-visible,
.fd-pp-tie:focus-visible,
.fd-pp-unit:focus-visible,
.fd-pp-tile:focus-visible,
.fd-pp-team:focus-visible,
.fd-pp-modes button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-pp-open {
  box-sizing: border-box;
  display: block;
  width: 46px;
  height: 46px;
  margin-bottom: 22px;
  border-radius: 50%;
  border: 1.5px dashed var(--ghost-line);
  cursor: pointer;
}
.fd-pp-open.is-tie {
  width: 30px;
  height: 30px;
  margin-bottom: 20px;
}
.fd-pp-socket.is-target .fd-pp-step {
  border-color: var(--lamp-info);
  animation: fd-pp-target 1.2s steps(1, end) infinite;
}
.fd-pp-socket.is-target .fd-pp-open {
  border: 2px solid var(--lamp-info);
  background: var(--info-tint);
  animation: fd-pp-seat 1.2s steps(1, end) infinite;
}
.fd-pp-socket.is-replacing .fd-pp-unit {
  opacity: .42;
}
@keyframes fd-pp-target {
  0% {
    box-shadow:
      0 0 0 1px var(--lamp-info),
      0 0 18px color-mix(in srgb, var(--lamp-info) 38%, transparent),
      var(--glass-edge);
  }
  50% {
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--lamp-info) 45%, transparent), var(--glass-edge);
  }
}
@keyframes fd-pp-seat {
  0% {
    box-shadow: 0 0 14px color-mix(in srgb, var(--lamp-info) 45%, transparent);
  }
  50% {
    box-shadow: none;
    border-color: color-mix(in srgb, var(--lamp-info) 55%, transparent);
  }
}
.fd-pp-socket.is-owed .fd-pp-step {
  border-color: var(--danger-line);
}
.fd-pp-socket.is-owed:not(.is-target) .fd-pp-open {
  border-color: var(--clay);
}
.fd-pp-tie {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border-radius: 50%;
  border: 1.5px dashed var(--ghost-line);
  background: var(--paper);
  color: var(--muted2);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.fd-pp-tie::before {
  content: "";
  position: absolute;
  inset: -7px;
  border-radius: 50%;
}
.fd-pp-tie span {
  display: flex;
}
.fd-pp-tie.is-lit {
  border: 2px solid var(--lamp-info);
  color: var(--lamp-info);
  background: color-mix(in srgb, var(--lamp-info) 14%, var(--paper));
}
.fd-pp-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 44px;
  max-width: 100%;
  min-height: 44px;
  margin: 0;
  padding: 0 1px;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
.fd-pp-unit.is-static {
  cursor: default;
}
.fd-pp-unit.is-arriving {
  opacity: 0;
  transition: none;
}
.fd-pp-unit:active:not(.is-static) .fd-pp-face {
  transform: scale(.92);
}
.fd-pp-unit .fd-pp-name {
  font: 600 12px/1.2 var(--fd-body);
}
.fd-pp-unit.is-team {
  flex-basis: 100%;
}
.fd-pp-face {
  position: relative;
  display: flex;
  justify-content: center;
  border-radius: 50%;
  transition: transform var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
.fd-pp-name {
  max-width: 100%;
  text-align: center;
  overflow-wrap: anywhere;
  hyphens: auto;
}
.fd-pp-socket.is-place-0 .fd-pp-unit .fd-pp-name {
  font-weight: 700;
}
.fd-pp-fieldset {
  display: grid;
  gap: 10px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.fd-pp-field {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
}
.fd-pp-tile {
  box-sizing: border-box;
  flex: 0 0 calc((100% - 12px) / 4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 92px;
  margin: 0;
  padding: 8px 2px 6px;
  border: 0;
  border-radius: 10px;
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity var(--motion-fast, 140ms) var(--ease-out, ease-out), background-color var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
.fd-pp-tile:active:not(:disabled) {
  background: var(--ink-tint);
}
.fd-pp-tile:active:not(:disabled) .fd-pp-face {
  transform: scale(.93);
}
.fd-pp-tile .fd-pp-name {
  font: 600 13px/1.2 var(--fd-body);
}
.fd-pp-tile.is-idle {
  opacity: .42;
}
.fd-pp-tile.is-placed .fd-pp-face {
  box-shadow: 0 0 0 2px var(--paper), 0 0 0 4.5px var(--place);
}
.fd-pp-tile.is-placed .fd-pp-name {
  color: var(--muted2);
}
.fd-pp-badge {
  box-sizing: border-box;
  position: absolute;
  right: -6px;
  bottom: -5px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--place);
  color: var(--ink0);
  border: 2px solid var(--paper);
  font: 800 13px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-pp-tile.is-crew:not(.is-placed) .fd-pp-face {
  outline: 1.5px dashed var(--bronze);
  outline-offset: 3px;
}
.fd-pp-field.is-teams {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.fd-pp-team {
  box-sizing: border-box;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  min-height: 84px;
  margin: 0;
  padding: 12px 12px 11px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--paper2);
  box-shadow: var(--glass-edge);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity var(--motion-fast, 140ms) var(--ease-out, ease-out), border-color var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
.fd-pp-team.is-wide {
  grid-column: 1 / -1;
}
.fd-pp-team:active:not(:disabled) {
  transform: scale(.98);
}
.fd-pp-team .fd-pp-face {
  border-radius: 0;
  flex: none;
}
.fd-pp-team-name {
  max-width: 100%;
  min-width: 0;
  font: 600 14px/1.25 var(--fd-body);
  overflow-wrap: break-word;
}
.fd-pp-team.is-idle {
  opacity: .42;
}
.fd-pp-team.is-placed {
  border-color: color-mix(in srgb, var(--place) 60%, transparent);
  background: color-mix(in srgb, var(--place) 11%, var(--paper2));
}
.fd-pp-team.is-big {
  gap: 10px;
  min-height: 100px;
  padding: 14px 12px 12px;
}
.fd-pp-team.is-big .fd-pp-team-name {
  font-size: 15px;
  font-weight: 700;
}
.fd-pp-badge.is-corner {
  top: 10px;
  right: 10px;
  bottom: auto;
  border-color: var(--ink0);
}
.fd-pp-modes {
  display: flex;
  justify-self: end;
  gap: 2px;
  padding: 2px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--bg);
}
.fd-pp-modes button {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--muted2);
  font: 600 13px/1 var(--fd-body);
  cursor: pointer;
}
.fd-pp-modes button[aria-pressed=true] {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-pp-modes button:disabled {
  opacity: .35;
  cursor: default;
}
.fd-pp-error {
  margin: 0;
  color: var(--clay-text);
  font: 600 13px/1.4 var(--fd-body);
}
.fd-pp-check {
  display: grid;
  gap: 10px;
  padding: 12px 13px;
  border-radius: 14px;
  border: 1px solid var(--danger-line);
  background: color-mix(in srgb, var(--clay) 7%, var(--paper2));
}
.fd-pp-check.is-correction {
  border-color: var(--line);
  background: var(--paper2);
}
.fd-pp-check p {
  margin: 0;
  color: var(--ink);
  font: 600 14px/1.4 var(--fd-body);
}
.fd-pp-actions {
  display: flex;
  gap: 8px;
}
.fd-pp-reason {
  display: grid;
  gap: 6px;
}
.fd-pp-reason span {
  color: var(--muted2);
  font: 700 12px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-pp-reason input {
  box-sizing: border-box;
  width: 100%;
  min-height: 48px;
  padding: 11px 12px;
  border-radius: 10px;
  border: 1px solid var(--ghost-line);
  background: var(--bg);
  color: var(--ink);
  font: 600 16px/1.2 var(--fd-body);
  box-shadow: inset 0 1px 3px color-mix(in srgb, var(--ink0) 60%, transparent);
  outline: none;
}
.fd-pp-reason input:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .fd-pp-socket.is-target .fd-pp-step {
    animation: none;
    box-shadow: 0 0 0 1px var(--lamp-info), var(--glass-edge);
  }
  .fd-pp-socket.is-target .fd-pp-open {
    animation: none;
  }
  .fd-pp-step,
  .fd-pp-unit,
  .fd-pp-face,
  .fd-pp-tile,
  .fd-pp-team {
    transition: none;
  }
}

/* src/features/weekend/contest.css */
.fd-contest {
  margin-bottom: 12px;
  min-width: 0;
}
.fd-contest-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0 12px;
}
.fd-contest-toolbar > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.fd-contest-toolbar strong {
  color: var(--ink);
  font: 800 18px/1.2 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.fd-contest-toolbar span {
  color: var(--muted2);
  font-size: 13px;
}
.fd-contest-toolbar span .fd-beat-dot {
  width: 7px;
  height: 7px;
  margin-right: 6px;
  vertical-align: 1px;
  color: var(--lamp-live);
}
.fd-contest-primary {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 9px 12px;
  border: 0;
  border-radius: 6px;
  background: var(--action-fill);
  color: var(--action-ink);
  font: 600 12px/1.3 var(--fd-body);
  cursor: pointer;
}
.fd-contest-primary:disabled {
  opacity: .45;
  cursor: default;
}
.fd-contest-toolbar .fd-contest-primary {
  flex-shrink: 0;
  max-width: 60%;
}
.fd-contest-entrants {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper2);
}
.fd-contest-entrant {
  display: flex;
  min-width: 0;
  align-items: stretch;
}
.fd-contest-entrant + .fd-contest-entrant {
  border-top: 1px solid var(--line);
}
.fd-contest-entrant-pick {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 48px;
  padding: 10px 12px;
  background: none;
  color: var(--ink);
  border: 0;
  font: 600 13px/1.4 var(--fd-body);
  text-align: left;
  cursor: pointer;
}
.fd-contest-entrant-pick > span {
  flex: 1;
  overflow-wrap: anywhere;
}
.fd-contest-entrant-pick small {
  color: var(--sun);
  font-size: 12px;
  font-weight: 600;
}
.fd-contest-entrant-pick:disabled {
  opacity: 1;
  cursor: default;
}
.fd-contest-entrant-pick:not(:disabled):hover {
  background: var(--sun-tint);
}
.fd-contest-entrant.is-you {
  box-shadow: inset 3px 0 0 var(--accent2);
}
.fd-contest-entrant.is-winner,
.fd-contest-entrant-pick[aria-checked=true] {
  background: var(--accent-tint);
}
.fd-contest-entrant.is-winner .fd-contest-entrant-pick {
  color: var(--accent2);
}
.fd-contest-entrant-players {
  display: flex;
  align-items: center;
  padding-right: 4px;
}
.fd-contest-entrant-players button {
  display: grid;
  place-items: center;
  padding: 0;
  width: 44px;
  min-height: 44px;
  border: 0;
  border-radius: 6px;
  background: none;
  cursor: pointer;
}
.fd-contest-entrant-players button:disabled {
  cursor: default;
}
.fd-contest-primary:focus-visible,
.fd-contest-secondary:focus-visible,
.fd-contest-entrant-pick:focus-visible,
.fd-contest-entrant-players button:focus-visible {
  outline: 2px solid var(--sun);
  outline-offset: -3px;
}
.fd-contest-qualifier-actions {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 8px;
  border-top: 1px solid var(--line);
}
.fd-contest-secondary {
  min-height: 44px;
  padding: 8px;
  border: 0;
  background: none;
  color: var(--muted2);
  font-size: 12px;
  text-decoration: underline;
  cursor: pointer;
}
.fd-contest-failure {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: space-between;
}
.fd-contest-error {
  font-size: 13px;
  line-height: 1.5;
  color: var(--clay-text);
  margin: 8px 0;
}
.fd-contest-saving {
  margin: 8px 0;
  color: var(--muted2);
  font-size: 12px;
}
.fd-contest-correction {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 18px;
  margin: 0 0 12px;
}
.fd-contest-correction > p,
.fd-contest-correction > .fd-contest-confirm {
  flex-basis: 100%;
}
.fd-contest-correction button {
  min-height: 44px;
  padding: 8px 0;
  border: 0;
  background: none;
  color: var(--muted2);
  font-size: 12px;
  text-decoration: underline;
  cursor: pointer;
}
.fd-contest-correction button:disabled {
  opacity: .5;
  cursor: default;
}
.fd-contest-correction p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}
.fd-event-context {
  margin-bottom: 14px;
}
.fd-event-context summary {
  min-height: 44px;
  padding: 12px 0;
  cursor: pointer;
  font: 600 18px/1.1 var(--fd-display);
  color: var(--ink);
}
.fd-contest-confirm {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.fd-contest-confirm p {
  flex-basis: 100%;
  color: var(--ink);
  font-size: 12px;
}
.fd-contest-reorder {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin: 8px 0 0;
}
.fd-contest-reorder p {
  flex-basis: 100%;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}
.fd-contest-confirm button:focus-visible {
  outline: 2px solid var(--sun);
  outline-offset: -3px;
}
.fd-contest-toolbar .fd-contest-you {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--ink);
  font: 600 14px/1.35 var(--fd-body);
}
.fd-contest-toolbar .fd-contest-you > span {
  color: var(--ink);
  font-size: 14px;
}
.fd-contest-toolbar .fd-contest-you b {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--sun);
  font: 800 18px/1.15 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-contest-chip {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--sun);
  box-shadow: inset 0 0 0 2px var(--ink0), inset 0 0 0 3.5px color-mix(in srgb, var(--bone) 70%, transparent);
}
.fd-contest-picker {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.fd-contest-picker.fd-pp {
  gap: 14px;
}
.fd-contest-picks {
  display: grid;
  grid-template-columns: repeat(var(--pick-cols, 2), minmax(0, 1fr));
  gap: 8px;
  align-items: stretch;
}
.fd-contest-picks.is-cols-3 {
  --pick-cols:3;
}
.fd-contest-picks.is-versus {
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 0;
}
.fd-contest-vs {
  align-self: center;
  width: 32px;
  padding-top: 44px;
  text-align: center;
  color: var(--muted2);
  font: 900 15px/1 var(--fd-show);
  letter-spacing: .04em;
  text-transform: uppercase;
  user-select: none;
  pointer-events: none;
}
.fd-contest-tile {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  min-width: 0;
  padding: 5px;
  border: 1px solid var(--night-line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--ink0) 40%, transparent);
  transition: border-color var(--motion-fast, 140ms) var(--ease-out, ease-out);
}
.fd-contest-tile-faces {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: center;
  min-height: 56px;
}
.fd-contest-tile-faces button {
  display: grid;
  place-items: center;
  min-width: 44px;
  min-height: 44px;
  padding: 2px;
  border: 0;
  border-radius: 50%;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.fd-contest-tile-faces button:disabled {
  cursor: default;
}
.fd-contest-tile-pick {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  min-height: 68px;
  padding: 9px 8px 8px;
  border: 1px solid var(--action-fill);
  border-radius: 10px;
  background: var(--action-fill);
  color: var(--action-ink);
  box-shadow: var(--glass-edge), var(--shadow-1);
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    transform .1s,
    opacity .15s,
    filter .15s,
    background-color .15s,
    border-color .15s;
}
.fd-contest-tile-name {
  max-width: 100%;
  font: 900 20px/1.12 var(--fd-show);
  letter-spacing: .01em;
  overflow-wrap: anywhere;
  hyphens: auto;
}
.fd-contest-picks.is-cols-3 .fd-contest-tile-name {
  font-size: 17px;
}
.fd-contest-tile-verb {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 18px;
  font: 800 12px/1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--action-ink) 78%, transparent);
}
.fd-contest-tile-pick:not(:disabled):active {
  transform: translateY(1px) scale(.985);
  filter: brightness(.92);
}
.fd-contest-tile-pick:disabled {
  cursor: default;
  opacity: .42;
}
.fd-contest-tile-pick:focus-visible,
.fd-contest-tile-faces button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-contest-tile.is-picking .fd-contest-tile-pick {
  opacity: 1;
  box-shadow: var(--glass-edge), var(--chip-bloom);
}
.fd-contest-tile.is-picking,
.fd-contest-tile:has(.fd-contest-tile-pick:not(:disabled):active) {
  border-color: color-mix(in srgb, var(--action-fill) 60%, transparent);
}
.fd-contest-tile.is-won {
  border-color: color-mix(in srgb, var(--action-fill) 60%, transparent);
}
.fd-contest-tile.is-won .fd-contest-tile-pick {
  box-shadow: var(--glass-edge), var(--chip-bloom);
}
.fd-contest-tile:is(.is-maybe, .is-through, .is-order, .is-idle) .fd-contest-tile-pick {
  border-color: var(--ghost-line);
  background: var(--paper2);
  color: var(--ink);
  box-shadow: var(--glass-edge);
}
.fd-contest-tile:is(.is-maybe, .is-order) .fd-contest-tile-verb {
  color: var(--muted2);
}
.fd-contest-tile.is-through .fd-contest-tile-pick {
  border-color: var(--action-fill);
  background: var(--sun-tint);
}
.fd-contest-tile.is-through .fd-contest-tile-verb {
  color: var(--sun);
}
.fd-contest-tile.is-placed {
  --place:var(--sun);
  border-color: color-mix(in srgb, var(--place) 55%, transparent);
}
.fd-contest-tile.is-place-1 {
  --place:var(--silver);
}
.fd-contest-tile.is-place-2 {
  --place:var(--bronze);
}
.fd-contest-tile.is-placed .fd-contest-tile-pick {
  border-color: var(--place);
  background: color-mix(in srgb, var(--place) 16%, var(--paper2));
  color: var(--ink);
  box-shadow: var(--glass-edge);
}
.fd-contest-tile-medal {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--place);
  color: var(--ink0);
  border: 2px solid var(--ink0);
  font: 800 13px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-contest-picker .fd-contest-qualifier-actions {
  padding: 0;
  border-top: 0;
  align-items: center;
}
.fd-contest-picker .fd-contest-qualifier-actions .fd-contest-primary {
  min-width: 44%;
  min-height: 48px;
  font-size: 15px;
}
.fd-contest-recent {
  position: relative;
  display: grid;
  gap: 6px;
  margin: 0 0 12px;
  padding: 8px 8px 11px 12px;
  overflow: hidden;
  border: 1px solid var(--bone-line);
  border-radius: 14px;
  background: var(--night);
  color: var(--bone);
  box-shadow: var(--glass-edge);
}
.fd-contest-recent-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
}
.fd-contest-recent-faces {
  display: flex;
  flex: 0 0 auto;
}
.fd-contest-recent-faces > * + * {
  margin-left: -8px;
}
.fd-contest-recent-name {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
  font: 900 19px/1.15 var(--fd-show);
}
.fd-contest-stamp {
  flex: 0 0 auto;
  padding: 3px 9px 2px;
  border: 3px solid var(--sun);
  border-radius: 8px;
  color: var(--sun);
  font: 900 22px/1 var(--fd-show);
  letter-spacing: .04em;
  text-transform: uppercase;
  transform: rotate(-6deg);
  animation: fd-contest-stamp var(--motion-stamp, 320ms) var(--ease-land, ease-out) both;
}
@keyframes fd-contest-stamp {
  0% {
    opacity: 0;
    transform: rotate(-6deg) scale(1.9);
  }
  70% {
    opacity: 1;
    transform: rotate(-6deg) scale(.94);
  }
  100% {
    opacity: 1;
    transform: rotate(-6deg) scale(1);
  }
}
.fd-contest-recent button {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  min-width: 64px;
  padding: 8px 14px;
  border: 1px solid var(--ghost-line);
  border-radius: 8px;
  background: var(--paper2);
  color: var(--bone);
  font: 700 14px/1.2 var(--fd-body);
  cursor: pointer;
}
.fd-contest-recent button:disabled {
  opacity: .5;
  cursor: default;
}
.fd-contest-recent button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-contest-recent-note {
  margin: 0;
  color: var(--muted2);
  font: 500 13px/1.4 var(--fd-body);
}
.fd-contest-recent .fd-contest-error {
  margin: 0;
}
.fd-contest-recent-drain {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: var(--lamp-info);
  transform-origin: left center;
  animation: fd-contest-drain var(--undo-total) linear var(--undo-elapsed) forwards;
  pointer-events: none;
}
@keyframes fd-contest-drain {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}
.fd-contest-recent.is-still .fd-contest-stamp {
  animation: none;
}
.fd-contest-recent.is-still .fd-contest-recent-drain {
  animation: none;
  transform: none;
}

/* src/features/wagers/bet-stacks.css */
.fd-stack {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  flex-shrink: 0;
  line-height: 0;
}
.fd-stack > svg {
  display: block;
  overflow: visible;
}
.fd-stack-rim {
  fill: color-mix(in srgb, var(--stack-color) 70%, var(--ink0));
  stroke: var(--ink0);
  stroke-width: .9px;
  stroke-linejoin: round;
}
.fd-stack-insert {
  fill: color-mix(in srgb, var(--bone) 82%, var(--stack-color));
}
.fd-stack.is-light .fd-stack-insert {
  fill: var(--ink0);
}
.fd-stack-seam {
  fill: none;
  stroke: var(--ink0);
  stroke-linecap: round;
}
.fd-stack-num {
  fill: var(--bone);
}
.fd-stack.is-light .fd-stack-num {
  fill: var(--ink0);
}
.fd-stack-break {
  fill: none;
  stroke: var(--bone);
  stroke-linecap: round;
}
.fd-stack-ring {
  fill: none;
  stroke: var(--sun);
}
.fd-stack-tag {
  position: absolute;
  left: 50%;
  top: 0;
  z-index: 1;
  transform: translate(-50%, -62%);
  padding: 2px 5px;
  border-radius: 99px;
  background: var(--ink0);
  color: var(--bone);
  border: 1px solid var(--stack-color);
  font: 700 12px/1 var(--fd-display);
  letter-spacing: .02em;
  white-space: nowrap;
}
.fd-stacks {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 6px 10px;
  min-width: 0;
}
.fd-stacks-slot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  min-width: 0;
}
.fd-stacks-body {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  line-height: 0;
}
.fd-stacks-name {
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-stacks-group .fd-stacks-name.fd-stacks-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.1em;
  height: 1.45em;
  padding: 0 .45em;
  border-radius: 99px;
  background: var(--silver);
  color: var(--ink0);
  box-shadow: inset 0 0 0 .14em color-mix(in srgb, var(--ink0) 22%, transparent);
  font-family: var(--fd-display);
  font-weight: 800;
  line-height: 1;
  letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  overflow: visible;
}
.fd-stacks-value {
  display: block;
  font: 700 12px/1 var(--fd-display, var(--fd-display));
  letter-spacing: .02em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--bone);
}
.fd-stacks.is-value-side .fd-stacks-value {
  padding-bottom: 2px;
}
.fd-fit {
  position: relative;
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}
.fd-fit-stacks {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  flex-wrap: wrap-reverse;
  align-content: flex-start;
  align-items: flex-start;
}
.fd-fit-stacks .fd-stack {
  width: auto !important;
}
.fd-fit-total {
  position: absolute;
  top: 0;
  right: 0;
  font-variant-numeric: tabular-nums;
}
@keyframes fd-stack-drop {
  0% {
    transform: translateY(-26px);
    opacity: 0;
  }
  55% {
    transform: translateY(2px);
    opacity: 1;
  }
  78% {
    transform: translateY(-1.5px);
  }
  100% {
    transform: none;
    opacity: 1;
  }
}
.fd-stack-chip.is-drop,
.fd-stack-face.is-drop {
  animation: fd-stack-drop .34s cubic-bezier(.3, .7, .35, 1) both;
}
@keyframes fd-stack-pay {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fd-stack-rise {
  from {
    transform: translateY(var(--stack-rise));
  }
  to {
    transform: none;
  }
}
.fd-stack-chip.is-paid {
  animation: fd-stack-pay .16s ease-out both;
}
.fd-stack-face.is-rising {
  animation-name: fd-stack-rise;
  animation-timing-function: linear;
  animation-fill-mode: both;
}
@keyframes fd-stack-bank {
  0% {
    transform: none;
    opacity: 1;
  }
  25% {
    transform: translate(-4px, -3px);
    opacity: 1;
  }
  100% {
    transform: translate(var(--bank-x, 90px), var(--bank-y, 36px)) rotate(10deg);
    opacity: 0;
  }
}
.fd-stack.is-lost,
.fd-stacks-slot.is-lost {
  animation: fd-stack-bank .8s cubic-bezier(.5, 0, .75, .4) both;
}
@media (prefers-reduced-motion: reduce) {
  .fd-stack-chip.is-drop,
  .fd-stack-face.is-drop,
  .fd-stack-chip.is-paid,
  .fd-stack-face.is-rising {
    animation: none;
  }
  .fd-stack.is-lost,
  .fd-stacks-slot.is-lost {
    animation: none;
    opacity: 0;
  }
}

/* src/ui/payout-ladder.css */
.fd-ladder {
  list-style: none;
  margin: 0;
  padding: 0;
}
.fd-ladder.is-podium {
  display: grid;
  grid-template-columns: repeat(var(--ladder-cols), minmax(0, 1fr));
  align-items: end;
  gap: 6px;
  width: 100%;
  max-width: calc(var(--ladder-cols) * 128px);
  margin-inline: auto;
}
.fd-ladder.is-podium .fd-ladder-step {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
}
.fd-ladder-stand {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}
.fd-ladder-stand .fd-stack {
  margin-bottom: -4px;
  position: relative;
  z-index: 1;
}
.fd-ladder-plinth {
  box-sizing: border-box;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  width: 100%;
  height: calc(var(--ladder-step) * var(--rise));
  padding-top: 8px;
  border-radius: 10px 10px 0 0;
  border: 1px solid var(--line);
  border-bottom: 0;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 9%, var(--paper2)) 0,
      var(--paper2) 22%,
      color-mix(in srgb, var(--ink0) 30%, var(--paper2)) 100%);
  box-shadow: var(--glass-edge);
}
.fd-ladder-step.is-place-1 .fd-ladder-plinth {
  border-color: color-mix(in srgb, var(--sun) 45%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--sun) 22%, var(--paper2)) 0,
      color-mix(in srgb, var(--sun) 9%, var(--paper2)) 24%,
      color-mix(in srgb, var(--ink0) 25%, var(--paper2)) 100%);
}
.fd-ladder-step.is-place-crew .fd-ladder-plinth {
  background: transparent;
  border: 1px dashed var(--muted);
  border-bottom: 0;
  box-shadow: none;
}
.fd-ladder-amount {
  font: 800 20px/1.15 var(--fd-display);
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  letter-spacing: .01em;
}
.fd-ladder-step.is-place-1 .fd-ladder-amount {
  color: var(--sun);
}
.fd-ladder-step.is-place-crew .fd-ladder-amount {
  color: var(--muted2);
}
.fd-ladder.is-podium {
  position: relative;
  padding-bottom: 1px;
}
.fd-ladder.is-podium::after {
  content: "";
  position: absolute;
  left: -6px;
  right: -6px;
  bottom: 0;
  height: 1px;
  background: var(--ghost-line);
}
.fd-ladder.is-filled::after {
  display: none;
}
.fd-ladder.is-filled .fd-ladder-stand {
  border-bottom: 1px solid var(--ghost-line);
}
.fd-ladder-winners {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  padding-top: 8px;
  min-width: 0;
  text-align: center;
}
.fd-ladder-faces {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0 2px;
  width: 100%;
}
.fd-ladder-who {
  max-width: 100%;
  color: var(--ink);
  font: 600 13px/1.25 var(--fd-body);
  overflow-wrap: break-word;
}
.fd-ladder-step.is-place-1 .fd-ladder-who {
  color: var(--ink);
  font-weight: 700;
}
.fd-ladder.is-podium.is-tv {
  gap: 14px;
  max-width: calc(var(--ladder-cols) * 230px);
}
.fd-ladder.is-tv .fd-ladder-plinth {
  padding-top: 16px;
  border-radius: 14px 14px 0 0;
}
.fd-ladder.is-tv .fd-ladder-amount {
  font-size: 56px;
}
.fd-ladder:is(.is-tv, .is-ticker) .fd-ladder-step:not(.is-place-crew) .fd-ladder-amount {
  color: var(--sun);
}
.fd-ladder.is-tv .fd-ladder-who {
  font-size: 28px;
}
.fd-ladder.is-tv .fd-ladder-stand .fd-stack {
  margin-bottom: -8px;
}
.fd-ladder:is(.is-ticker, .is-tiny) {
  display: flex;
  align-items: center;
}
.fd-ladder:is(.is-ticker, .is-tiny) .fd-ladder-step {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}
.fd-ladder-medal {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--bone);
  color: var(--ink0);
  border: 2px solid var(--ink0);
  font-family: var(--fd-display);
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--ink0) 20%, transparent);
}
.fd-ladder-step.is-place-1 .fd-ladder-medal {
  background: var(--sun);
}
.fd-ladder-step.is-place-2 .fd-ladder-medal {
  background: var(--silver);
}
.fd-ladder-step.is-place-3 .fd-ladder-medal {
  background: var(--bronze);
}
.fd-ladder-step.is-place-crew .fd-ladder-medal {
  background: transparent;
  border: 2px dashed var(--muted);
}
.fd-ladder.is-ticker {
  gap: 22px;
}
.fd-ladder.is-ticker .fd-ladder-amount {
  font-size: 34px;
}
.fd-ladder.is-tiny {
  gap: 6px;
}
.fd-ladder.is-tiny .fd-ladder-medal {
  border-width: 1.5px;
}
.fd-ladder.is-tiny .fd-ladder-amount {
  font-size: 16px;
  color: var(--sun);
}
.fd-ladder.is-filled .fd-ladder-step {
  display: contents;
}
.fd-ladder.is-filled .fd-ladder-stand {
