/* src/features/identity/chip-coin.css */
.fd-coin {
  position: relative;
  display: block;
  flex-shrink: 0;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  cursor: grab;
}
.fd-coin.is-static {
  cursor: inherit;
  touch-action: auto;
}
.fd-coin:active {
  cursor: grabbing;
}
.fd-coin-drop,
.fd-coin-spin {
  position: absolute;
  inset: 0;
  display: block;
  transform-style: preserve-3d;
}
.fd-coin-spin {
  transform: rotateY(0deg);
}
.fd-coin-face {
  position: absolute;
  inset: 0;
  display: block;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.fd-coin-face.is-front {
  transform: translateZ(calc(var(--coin-h) / 2));
}
.fd-coin-face.is-back {
  transform: rotateY(180deg) translateZ(calc(var(--coin-h) / 2));
}
.fd-coin-facet {
  position: absolute;
  display: block;
  width: var(--coin-chord);
  height: var(--coin-h);
  left: calc(50% - var(--coin-chord) / 2);
  top: calc(50% - var(--coin-h) / 2);
  transform: rotateZ(calc(var(--i) * var(--coin-step))) translateY(calc(var(--coin-apothem) * -1)) rotateX(90deg);
  background: color-mix(in srgb, var(--coin-color) 68%, var(--ink0));
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.fd-coin-facet.is-ink {
  background: color-mix(in srgb, var(--bone) 82%, var(--coin-color));
}
.fd-coin.is-light .fd-coin-facet.is-ink {
  background: var(--ink0);
}
@keyframes fd-coin-mint {
  0% {
    transform: translateY(-70%) rotateY(0deg);
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  68% {
    transform: translateY(0) rotateY(720deg);
  }
  80% {
    transform: translateY(-7%) rotateY(720deg);
  }
  100% {
    transform: translateY(0) rotateY(720deg);
    opacity: 1;
  }
}
.fd-coin-drop.is-minting {
  animation: fd-coin-mint 1000ms cubic-bezier(.3, .7, .35, 1) both;
}
@media (prefers-reduced-motion: reduce) {
  .fd-coin-drop.is-minting {
    animation: none;
  }
}

/* src/features/profile/player-pass.css */
.fd-pass-wrap {
  --pass-color:var(--paper);
  --pass-ink:var(--ink);
  --pass-deep:color-mix(in srgb, var(--pass-color) 58%, var(--ink0));
  --pass-rule:color-mix(in srgb, var(--pass-ink) 30%, transparent);
  width: 100%;
  max-width: 360px;
  margin: 0 auto 24px;
}
.fd-pass {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 4 / 5;
  padding: 0;
  border: 0;
  background: transparent;
  perspective: 1200px;
  text-align: left;
  cursor: pointer;
  font-family: var(--fd-body);
  border-radius: 14px;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.fd-pass:focus-visible {
  outline: 3px solid var(--lamp-info);
  outline-offset: 6px;
}
.fd-pass-shadow {
  position: absolute;
  inset: 0;
  display: block;
  border-radius: 14px;
  box-shadow: var(--shadow-3);
  transform: translate(calc(var(--tx,0) * -6px), calc(var(--ty,0) * -4px));
}
.fd-pass-tilt {
  display: block;
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transform: rotateX(calc(var(--ty,0) * -7deg)) rotateY(calc(var(--tx,0) * 9deg));
}
.fd-pass.is-tilting :is(.fd-pass-shadow, .fd-pass-tilt, .fd-pass-number, .fd-pass-orbit, .fd-pass-window, .fd-pass-chip) {
  will-change: transform;
}
.fd-pass.is-releasing :is(.fd-pass-shadow, .fd-pass-tilt, .fd-pass-number, .fd-pass-orbit, .fd-pass-window, .fd-pass-chip) {
  transition: transform var(--tilt-release,520ms) cubic-bezier(.16, 1, .3, 1), opacity var(--tilt-release,520ms) ease-out;
}
.fd-pass-inner {
  display: block;
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
}
.fd-pass-inner.is-flipped {
  transform: rotateY(180deg);
}
.fd-pass-face {
  display: flex;
  flex-direction: column;
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--pass-color);
  color: var(--pass-ink);
  border: 3px solid var(--ink0);
  border-radius: 14px;
  padding: 22px 22px 18px;
  box-shadow:
    inset 0 0 0 1px var(--pass-rule),
    inset 0 2px 0 color-mix(in srgb, var(--bone) 32%, transparent),
    inset 0 -18px 30px color-mix(in srgb, var(--ink0) 22%, transparent);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.fd-pass-bulbs {
  position: absolute;
  inset: 7px;
  border: 3px dotted color-mix(in srgb, var(--pass-ink) 42%, transparent);
  border-radius: 10px;
  pointer-events: none;
}
.fd-pass-top,
.fd-pass-foot {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font: 800 13px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-pass-top > span:last-child,
.fd-pass-foot > span:last-child {
  text-align: right;
}
.fd-pass-mark {
