/* src/features/weekend/announcement.css */
.fd-announcement-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin: -4px 0 14px;
  text-align: center;
}
.fd-announcement-name {
  margin: 0;
  max-width: 100%;
  font-size: clamp(40px, 12vw, 56px);
  line-height: 1.05;
  color: var(--bone);
  overflow-wrap: normal;
  text-wrap: balance;
}
.fd-announcement-state {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: 800 15px/1.15 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink);
}
.fd-announcement-detail {
  margin: 0 0 10px;
  text-align: center;
  color: var(--muted2);
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .05em;
  text-transform: uppercase;
}
.fd-announcement-pays {
  display: flex;
  justify-content: center;
  margin: 4px 0 14px;
}
.fd-announcement-pays > .fd-ladder {
  flex: 1;
}
.fd-announcement-steps {
  margin: 0 0 6px;
}
.fd-announcement-mark {
  flex-shrink: 0;
  transform-origin: 50% 80%;
  animation: fd-event-mark-in .65s cubic-bezier(.2, .8, .3, 1) both;
}
.fd-announcement-summary p {
  margin: 0 0 6px;
  font-size: 13px;
  line-height: 1.5;
}
.fd-announcement-summary small {
  color: var(--muted2);
  font-size: 12px;
}
.fd-announcement-actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
.fd-announcement-actions > button:first-child {
  flex: 1;
}
.fd-announcement-handoff {
  height: 3px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--line);
}
.fd-announcement-handoff > span {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--sun);
  transform-origin: left;
  animation: fd-event-handoff var(--intro-hold,2200ms) linear var(--intro-elapsed,0ms) both;
}
.fd-draw-playback {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  margin: 0 0 12px;
}
.fd-draw-playback.is-complete {
  min-height: 0;
  margin: 0;
}
.fd-draw-pips {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  min-width: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-draw-pips li {
  display: grid;
  place-items: center;
  width: 22px;
  height: 28px;
  box-sizing: border-box;
  border: 1px dashed var(--ghost-line);
  border-radius: 6px;
  background: var(--paper);
  color: var(--muted);
  font: 800 13px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  transition: background-color var(--motion-stamp,320ms) var(--ease-out,ease-out), border-color var(--motion-stamp,320ms) var(--ease-out,ease-out);
}
.fd-draw-pips li.is-on {
  border: 1px solid var(--bone-line);
  background: var(--paper2);
  color: var(--bone);
  box-shadow: var(--glass-edge);
}
.fd-draw-pips li.is-live {
  border: 1px solid var(--lamp-live);
  background: var(--live-tint);
  color: var(--bone);
  box-shadow: var(--live-bloom);
}
.fd-sheet-header-actions .fd-draw-playback-action {
  min-width: 7.4em;
  text-align: right;
}
.fd-draw-announcement {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.fd-draw-announcement section {
  position: relative;
  min-width: 0;
  min-height: 100px;
  perspective: 700px;
}
.fd-draw-card-front {
  height: 100%;
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper2);
  padding: 10px;
  backface-visibility: hidden;
}
.fd-draw-card.is-covered .fd-draw-card-front {
  visibility: hidden;
}
.fd-draw-card.is-revealed .fd-draw-card-front {
  animation: fd-draw-turn .5s cubic-bezier(.2, .8, .3, 1) both;
}
.fd-draw-card-back {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--ghost-line);
  border-radius: 10px;
  background:
    radial-gradient(
      80% 62% at 50% 42%,
      color-mix(in srgb, var(--bone) 8%, transparent),
      transparent 72%),
    var(--paper);
  color: var(--muted2);
  box-shadow: var(--glass-edge);
  backface-visibility: hidden;
}
.fd-draw-card-back::before {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid color-mix(in srgb, var(--bone) 12%, transparent);
  border-radius: 8px;
}
.fd-draw-card-back span {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 2px dashed color-mix(in srgb, var(--bone) 24%, transparent);
  border-radius: 50%;
  font: 800 22px/1 var(--fd-display);
}
.fd-draw-card.is-revealed .fd-draw-card-back {
  animation: fd-draw-back .5s cubic-bezier(.2, .8, .3, 1) both;
}
.fd-draw-announcement h3 {
  color: var(--muted2);
  font: 900 16px/1.15 var(--fd-show);
  letter-spacing: .01em;
  margin: 0 0 4px;
}
.fd-draw-team-name {
  display: block;
  font: 900 17px/1.15 var(--fd-show);
  letter-spacing: .01em;
  margin: 4px 0 1px;
  color: var(--bone);
}
.fd-draw-people {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.fd-draw-people button,
.fd-draw-crew button {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 44px;
  border: 0;
  border-radius: 6px;
  padding: 3px 0;
  background: none;
  color: var(--ink);
  cursor: pointer;
  text-align: left;
  font: 600 14px/1.25 var(--fd-body);
}
.fd-draw-people button span {
  overflow-wrap: anywhere;
}
.fd-draw-people button:disabled,
.fd-draw-crew button:disabled {
  cursor: default;
}
.fd-draw-versus {
  display: block;
  border-top: 1px solid var(--line);
  padding-top: 3px;
  margin-top: 3px;
  color: var(--muted2);
  font: 600 12px/1.3 var(--fd-body);
}
.fd-draw-announcement section.is-byes {
  grid-column: 1/-1;
}
.fd-draw-byes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
  gap: 6px;
}
.fd-draw-bye {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--paper);
  padding: 2px 8px;
}
.fd-draw-bye.is-mine {
  border: 2px solid var(--fd-you);
  padding: 1px 7px;
}
.fd-draw-card.is-revealed .fd-draw-bye {
  animation: fd-draw-bye-in .42s cubic-bezier(.2, .8, .3, 1) calc(.1s + var(--deal-index,0)*.09s) backwards;
}
.fd-draw-card.is-settled .fd-draw-bye,
.fd-draw-announcement.is-reduced .fd-draw-bye {
  animation: none;
}
@keyframes fd-draw-bye-in {
  from {
    transform: translateY(8px) scale(.96);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.fd-draw-crew {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 14px;
  color: var(--muted2);
  font-size: 12px;
  margin-top: 10px;
}
.fd-draw-crew > div {
  display: flex;
  align-items: center;
  gap: 8px;
}
.fd-draw-crew.is-covered {
  visibility: hidden;
}
.fd-draw-playback-action:focus-visible,
.fd-draw-people button:focus-visible,
.fd-draw-crew button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-draw-announcement.is-reduced .fd-draw-card-front,
.fd-draw-announcement.is-reduced .fd-draw-card-back,
.fd-draw-announcement.is-reduced .fd-draw-people button {
  animation: none;
}
.fd-draw-announcement.is-reduced .fd-draw-card.is-revealed .fd-draw-card-back {
  display: none;
}
.fd-draw-card.is-settled .fd-draw-card-front,
.fd-draw-card.is-settled .fd-draw-people button {
  animation: none;
}
.fd-draw-card.is-settled .fd-draw-card-back {
  display: none;
}
.fd-draw-card.is-mine .fd-draw-card-front {
  border: 2px solid var(--fd-you);
  padding: 9px;
}
.fd-draw-card.is-mine .fd-draw-card-front {
  position: relative;
}
.fd-draw-you {
  position: absolute;
  top: -10px;
  right: 10px;
  padding: 1px 7px;
  border-radius: 99px;
  background: var(--fd-you);
  color: var(--fd-you-ink);
  font: 700 12px/1.4 var(--fd-body);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-draw-card.is-ringing .fd-draw-you {
  animation: fd-draw-you-stamp var(--motion-stamp) var(--ease-land) .46s backwards;
}
.fd-draw-ring {
  position: absolute;
  inset: -5px;
  z-index: 1;
  border: 2px solid var(--fd-you);
  border-radius: 14px;
  pointer-events: none;
  opacity: 0;
  animation: fd-draw-ring .9s var(--ease-out) .4s both;
}
@keyframes fd-draw-ring {
  0% {
    opacity: 0;
    transform: scale(.97);
  }
  25% {
    opacity: 1;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(1.07);
  }
}
@keyframes fd-draw-you-stamp {
  from {
    opacity: 0;
    transform: scale(1.9) rotate(-8deg);
  }
  60% {
    opacity: 1;
    transform: scale(.9) rotate(1deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fd-event-mark-in {
  from {
    transform: translateY(12px) rotate(-12deg) scale(.7);
    opacity: 0;
  }
  70% {
    transform: translateY(-3px) rotate(3deg) scale(1.04);
    opacity: 1;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes fd-event-handoff {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}
@keyframes fd-draw-turn {
  from {
    transform: rotateY(-90deg);
  }
  to {
    transform: rotateY(0);
  }
}
@keyframes fd-draw-back {
  from {
    transform: rotateY(0);
  }
  to {
    transform: rotateY(90deg);
    visibility: hidden;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-draw-pips li {
    transition: none;
  }
  .fd-announcement-mark,
  .fd-announcement-handoff > span,
  .fd-draw-card-front,
  .fd-draw-card-back,
  .fd-draw-card .fd-draw-people button,
  .fd-draw-bye,
  .fd-draw-you {
    animation: none !important;
  }
  .fd-draw-ring {
    display: none;
  }
  .fd-draw-card.is-revealed .fd-draw-card-back {
    display: none;
  }
}
@media (max-width: 359px) {
  .fd-draw-announcement {
    grid-template-columns: 1fr;
  }
}
.fd-announcement-intro {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin: -4px 0 12px;
}
.fd-announcement-game {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 90px;
  padding: 0;
  overflow: hidden;
}
.fd-draw-pips li.is-named {
  width: auto;
  min-width: 22px;
  padding: 0 8px;
  font: 800 13px/1 var(--fd-show);
  letter-spacing: .01em;
  white-space: nowrap;
}

/* src/features/draft/draft.css */
.fd-draft {
  display: grid;
  gap: 16px;
  outline: none;
}
.fd-draft button {
  font-family: var(--fd-body);
}
.fd-draft button:focus-visible,
.fd-draft-entry:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-draft button:disabled {
  cursor: default;
}
.fd-draft-section-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}
.fd-draft-section-title h2,
.fd-draft-section-title h3 {
  margin: 0;
  font: 800 24px/1.1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.fd-draft-section-title > span {
  color: var(--muted2);
  font-size: 13px;
  text-align: right;
}
.fd-draft-note {
  margin: -6px 0 0;
  font-size: 13px;
  color: var(--muted2);
  line-height: 1.5;
}
.fd-draft-role {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.fd-draft-role strong {
  color: var(--ink);
  font-size: 15px;
}
.fd-draft-methods {
  display: flex;
  padding: 4px;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg);
}
.fd-draft-methods button {
  flex: 1;
  min-height: 44px;
  border: 0;
  border-radius: 6px;
  padding: 6px;
  background: none;
  color: var(--muted2);
  font-weight: 600;
  cursor: pointer;
}
.fd-draft-methods button[aria-pressed=true] {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-draft-captain-order {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-draft-captain-order li {
  min-height: 52px;
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 4px 8px;
  border: 1px dashed var(--line);
  border-radius: 8px;
  color: var(--muted);
}
.fd-draft-captain-order li.is-filled {
  border-style: solid;
  background: var(--bg);
}
.fd-draft-captain-order li.is-filled button {
  animation: fd-draft-land .35s ease-out both;
}
.fd-draft-captain-order li > small {
  font: 700 19px var(--fd-display);
}
.fd-draft-captain-order li > span {
  font-size: 12px;
}
.fd-draft-captain-order button {
  display: flex;
  flex: 1;
  gap: 5px;
  align-items: center;
  min-width: 0;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink);
  cursor: pointer;
  font-size: 12px;
}
.fd-draft-captain-order button span {
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-draft-captain-order button b {
  margin-left: auto;
  font-size: 16px;
  color: var(--muted);
}
.fd-draft-pool {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.fd-draft-candidate {
  display: flex;
  align-items: center;
  min-width: 0;
  border: 1px solid var(--line);
  background: var(--bg);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: var(--glass-edge);
  transition:
    border-color var(--motion-fast),
    transform var(--motion-fast) var(--ease-out),
    box-shadow var(--motion-fast);
}
.fd-draft-candidate:has(.fd-draft-pick:not(:disabled)):hover {
  border-color: var(--lamp-live);
  transform: translateY(-2px);
}
.fd-draft-candidate:has(.fd-draft-pick:not(:disabled):active) {
  transform: scale(.97);
}
.fd-draft-candidate.is-lifting {
  border-color: var(--lamp-live);
  transform: translateY(-3px) scale(1.03);
  box-shadow: var(--live-bloom), var(--shadow-2);
  position: relative;
  z-index: 1;
}
.fd-draft-select {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 64px;
  width: 100%;
  padding: 8px;
  border: 0;
  background: none;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-draft-select span {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
  font-weight: 600;
}
.fd-draft-select b {
  color: var(--muted);
  font-size: 15px;
}
.fd-draft-select[aria-pressed=true] {
  background: var(--info-tint);
  box-shadow: inset 0 0 0 1px var(--lamp-info);
}
.fd-draft-select[aria-pressed=true] b {
  color: var(--lamp-info);
}
.fd-draft-select:disabled:not([aria-pressed=true]) {
  opacity: .4;
}
.fd-draft-avatar-link {
  display: grid;
  place-items: center;
  width: 48px;
  min-width: 48px;
  min-height: 64px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}
.fd-draft-pick {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 64px;
  padding: 8px 8px 8px 0;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 5px;
  border: 0;
  background: none;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-draft-pick > span {
  font-size: 14px;
  font-weight: 650;
  overflow-wrap: anywhere;
}
.fd-draft-pick small {
  font: 800 13px/1.15 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted2);
}
.fd-draft-pick:disabled small {
  color: var(--muted);
}
.fd-draft-turn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 16px 22px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: var(--glass-edge);
  overflow: hidden;
}
.fd-draft-turn:not(.is-complete) {
  border-color: color-mix(in srgb, var(--lamp-live) 55%, transparent);
  background: color-mix(in srgb, var(--lamp-live) 5%, var(--paper));
}
.fd-draft-turn.is-mine {
  border-color: var(--lamp-live);
  background: color-mix(in srgb, var(--lamp-live) 9%, var(--paper));
  box-shadow: var(--live-bloom), var(--glass-edge);
}
.fd-draft-turn.is-complete {
  border-color: var(--green);
}
.fd-draft-turn-copy {
  min-width: 0;
}
.fd-draft.is-fresh .fd-draft-turn-copy {
  animation: fd-draft-turn .3s var(--ease-out) both;
}
.fd-draft-turn small {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 12px;
  margin: 0 0 6px;
  color: var(--muted2);
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-draft-turn small > span {
  white-space: nowrap;
}
.fd-draft-turn.is-complete small {
  color: var(--muted2);
}
.fd-draft-turn h2 {
  margin: 0 0 6px;
  font: 900 clamp(36px, 10vw, 50px)/1.04 var(--fd-show);
  letter-spacing: .01em;
  overflow-wrap: anywhere;
}
.fd-draft-turn.is-mine h2 {
  color: var(--ink);
  text-shadow: 0 0 1px var(--lamp-live), 0 0 22px color-mix(in srgb, var(--lamp-live) 55%, transparent);
}
.fd-draft-turn p {
  font-size: 13px;
  line-height: 1.5;
  margin: 0;
  color: var(--muted2);
}
.fd-draft-turn-chip {
  display: block;
  transform: rotate(-9deg);
}
.fd-draft.is-passing .fd-draft-turn-chip {
  animation: fd-draft-chip .45s var(--ease-land) .3s both;
}
.fd-draft-turn.is-mine::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid var(--lamp-live);
  border-radius: 14px;
  pointer-events: none;
  animation: fd-beat var(--motion-beat) ease-in-out infinite;
}
:root[data-fd-link=down] .fd-draft-turn.is-mine::after {
  animation: none;
}
.fd-draft-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--line);
}
.fd-draft-progress > span {
  display: block;
  height: 100%;
  background: var(--lamp-live);
  box-shadow: 0 0 8px var(--lamp-live);
}
.fd-draft-turn.is-complete .fd-draft-progress > span {
  background: var(--green);
  box-shadow: none;
}
.fd-draft-queue {
  display: flex;
  gap: 5px;
  padding: 0;
  margin: -6px 0 0;
  list-style: none;
  overflow-x: auto;
}
.fd-draft-queue li {
  flex: 1;
  min-width: 58px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg);
}
.fd-draft-queue li[aria-current] {
  border-color: var(--lamp-live);
  background: var(--live-tint);
  box-shadow: 0 0 10px color-mix(in srgb, var(--lamp-live) 30%, transparent);
}
.fd-draft-queue small {
  display: block;
  color: var(--muted2);
  font: 800 13px/1 var(--fd-display);
  letter-spacing: .06em;
  margin-bottom: 4px;
}
.fd-draft-queue span {
  display: block;
  font-size: 12px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.fd-draft-latest {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  border-block: 1px solid var(--line);
}
.fd-draft.is-fresh .fd-draft-latest {
  animation: fd-draft-land .4s var(--ease-out) .45s both;
}
.fd-draft-pick-stamp {
  display: grid;
  justify-items: center;
  flex: 0 0 auto;
  min-width: 44px;
  padding: 3px 6px 4px;
  border: 1px solid var(--bone-line);
  border-radius: 6px;
  background: var(--bg);
  box-shadow: var(--glass-edge);
}
.fd-draft-pick-stamp small {
  font: 800 12px/1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted2);
}
.fd-draft-pick-stamp b {
  font: 800 24px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
.fd-draft-latest .fd-draft-person {
  flex: 0 1 auto;
}
.fd-draft-latest .fd-draft-person > span {
  font-size: 14px;
}
.fd-draft-latest-to {
  display: inline-flex;
  flex: 0 0 auto;
  color: var(--muted2);
}
.fd-draft-latest-team {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  margin-left: auto;
  padding: 3px 10px 3px 3px;
  border: 1px solid color-mix(in srgb, var(--draft-color) 60%, var(--line));
  border-radius: 99px;
  background: var(--bg);
}
.fd-draft-latest-team > span {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
  font-weight: 650;
  color: var(--ink);
}
.fd-draft-person {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  min-height: 44px;
  max-width: 100%;
  padding: 2px 0;
  background: none;
  color: var(--ink);
  border: 0;
  text-align: left;
  cursor: pointer;
}
.fd-draft-person > span {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 12px;
  font-weight: 600;
}
.fd-draft-available {
  display: grid;
  gap: 10px;
}
.fd-draft-body {
  display: grid;
  gap: 16px;
  align-items: start;
}
.fd-draft-teams {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}
.fd-draft-team {
  min-width: 0;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--draft-color) 60%, var(--line));
  border-radius: 10px;
  box-shadow: var(--glass-edge);
  background: var(--bg);
}
.fd-draft-team.is-picking {
  border-color: var(--lamp-live);
  box-shadow: 0 0 0 1px var(--lamp-live), 0 0 14px color-mix(in srgb, var(--lamp-live) 30%, transparent);
}
.fd-draft.is-fresh .fd-draft-team {
  transition: border-color var(--motion-base) ease-out .5s;
}
.fd-draft-team header {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 5px;
}
.fd-draft-team.is-yours header small {
  color: var(--you);
}
.fd-draft-team.is-yours {
  border-color: var(--you);
  box-shadow: var(--you-bloom);
}
.fd-draft-team-name {
  display: block;
  margin: 0 0 4px;
  font: 900 23px/1.1 var(--fd-show);
  overflow-wrap: anywhere;
}
.fd-draft-team header small {
  font-size: 12px;
}
.fd-draft-captain-label {
  display: block;
  margin: -3px 0 10px 37px;
  font-size: 12px;
  color: var(--muted);
}
.fd-draft-team ol {
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-draft-team li {
  border-top: 1px solid var(--line);
  min-height: 46px;
}
.fd-draft-team .is-latest {
  background: var(--live-tint);
}
.fd-draft-team .is-arriving > * {
  opacity: 0;
}
.fd-draft-team .is-landed > * {
  animation: fd-draft-seat var(--motion-base) var(--ease-land) both;
}
.fd-draft-flyer {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border: 1px solid var(--lamp-live);
  border-radius: 10px;
  background: var(--bg);
  box-shadow: var(--live-bloom), var(--shadow-2);
  color: var(--ink);
  font: 650 13px/1.1 var(--fd-body);
  overflow: hidden;
  white-space: nowrap;
}
.fd-draft-team .is-empty {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--muted);
  font-size: 12px;
}
.fd-draft-empty-chip {
  width: 28px;
  height: 28px;
  border: 1px dashed var(--line);
  border-radius: 50%;
  flex-shrink: 0;
}
.fd-draft-footer {
  display: grid;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}
.fd-draft-secondary-actions {
  display: flex;
  gap: 8px;
}
.fd-draft-secondary-actions > * {
  flex: 1;
}
.fd-draft-cancel {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  border: 1px solid var(--danger-line);
  border-radius: 8px;
  padding: 12px;
}
.fd-draft-cancel p {
  flex-basis: 100%;
  font-size: 13px;
  margin: 0 0 4px;
}
.fd-draft-error {
  padding: 10px 12px;
  color: var(--clay-text);
  border: 1px solid var(--danger-line);
  border-radius: 10px;
  margin: 0;
  font-size: 13px;
}
.fd-draft-crew > small {
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted);
  font-size: 13px;
  font-family: var(--fd-display);
  font-weight: 800;
  letter-spacing: .06em;
}
.fd-draft-crew > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
.fd-draft-crew > div > span {
  font-size: 12px;
  color: var(--muted);
}
.fd-draft-entry {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 14px;
  min-height: 88px;
  margin-bottom: 12px;
  border: 1px solid color-mix(in srgb, var(--lamp-live) 55%, transparent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--lamp-live) 5%, var(--paper));
  box-shadow: var(--glass-edge);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.fd-draft-entry.is-mine {
  border-color: var(--lamp-live);
  background: color-mix(in srgb, var(--lamp-live) 9%, var(--paper));
  box-shadow: var(--live-bloom), var(--glass-edge);
}
.fd-draft-entry > span {
  flex: 1;
  min-width: 0;
}
.fd-draft-entry.is-done {
  border-color: var(--line);
  background: var(--paper);
}
.fd-draft-entry strong {
  display: flex;
  align-items: center;
  gap: 10px;
  font: 900 29px/1.15 var(--fd-show);
  margin: 0 0 4px;
  overflow-wrap: anywhere;
}
.fd-draft-entry strong > .fd-insert {
  flex-shrink: 0;
}
.fd-draft-entry > span > span {
  display: block;
  font-size: 14px;
  line-height: 1.35;
  color: var(--muted2);
}
.fd-draft-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  margin: 0;
}
@keyframes fd-draft-chip {
  from {
    opacity: 0;
    transform: translateY(-15px) rotate(-28deg) scale(.8);
  }
  to {
    opacity: 1;
    transform: translateY(0) rotate(-9deg) scale(1);
  }
}
@keyframes fd-draft-land {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(.96);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fd-draft-seat {
  0% {
    transform: translateY(0);
  }
  45% {
    transform: translateY(-3px);
  }
  100% {
    transform: none;
  }
}
@keyframes fd-draft-turn {
  from {
    opacity: .3;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (min-width: 700px) {
  .fd-draft-pool {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .fd-draft-captain-order {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .fd-draft-teams {
    grid-template-columns: repeat(var(--draft-columns,2), minmax(0, 1fr));
  }
  .fd-draft-turn {
    padding: 20px 22px 24px;
  }
  .fd-draft-body:not(.is-complete) {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 20px;
  }
  .fd-draft-body .fd-draft-pool {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fd-draft-body:not(.is-complete) .fd-draft-teams {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-draft *,
  .fd-draft *:before,
  .fd-draft *:after {
    animation: none !important;
    transition: none !important;
  }
}

/* src/features/poker/poker-motion.css */
.fd-roll {
  position: relative;
  display: inline-grid;
  overflow: hidden;
  vertical-align: bottom;
  padding-block: .04em;
}
.fd-roll > span {
  grid-area: 1 / 1;
}
.fd-roll-out {
  animation: fd-roll-out-up 280ms var(--ease-exit) both;
}
.fd-roll-in {
  animation: fd-roll-in-up 420ms var(--ease-land) 200ms both;
}
.fd-roll[data-dir=down] .fd-roll-out {
  animation-name: fd-roll-out-down;
}
.fd-roll[data-dir=down] .fd-roll-in {
  animation-name: fd-roll-in-down;
}
@keyframes fd-roll-out-up {
  from {
    transform: none;
    opacity: 1;
  }
  to {
    transform: translateY(-100%);
    opacity: 0;
  }
}
@keyframes fd-roll-in-up {
  from {
    transform: translateY(100%);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes fd-roll-out-down {
  from {
    transform: none;
    opacity: 1;
  }
  to {
    transform: translateY(100%);
    opacity: 0;
  }
}
@keyframes fd-roll-in-down {
  from {
    transform: translateY(-100%);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.fd-level-chip {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  perspective: 240px;
}
.fd-level-face {
  position: absolute;
  inset: 0;
  display: block;
  backface-visibility: hidden;
}
.fd-level-face.is-out {
  animation: fd-level-out 220ms var(--ease-exit) both;
}
.fd-level-face.is-in {
  animation: fd-level-in 300ms var(--ease-land) 220ms both;
}
@keyframes fd-level-out {
  from {
    transform: none;
  }
  to {
    transform: rotateY(90deg);
    opacity: 0;
  }
}
@keyframes fd-level-in {
  from {
    transform: rotateY(-90deg);
    opacity: 0;
  }
  1% {
    opacity: 1;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.fd-poker-blinds {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.fd-poker-blinds-num {
  font: 800 30px/1.2 var(--fd-display);
  letter-spacing: .02em;
  color: var(--bone);
  justify-self: start;
  width: max-content;
}
.fd-poker-blinds > span:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 14px;
  font: 500 13px/1.35 var(--fd-body);
  color: var(--night-text);
  margin-top: 2px;
}
.fd-seat-chips-row {
  border-top: 1px solid var(--night-line);
  padding: 9px 14px;
}
.fd-seat-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 3px;
  min-height: 22px;
}
.fd-seat-chips > span {
  display: block;
}
.fd-seat-chip {
  display: grid;
  place-items: end center;
  flex-shrink: 0;
}
.fd-seat-chip.is-flat {
  opacity: .7;
}
.fd-seat-chip.is-tipping {
  transform-origin: 50% 100%;
  animation: fd-seat-tip 420ms var(--ease-land) both;
}
@keyframes fd-seat-tip {
  0% {
    transform: perspective(160px) rotateX(-62deg) translateY(-4px);
    opacity: 1;
  }
  65% {
    transform: perspective(160px) rotateX(7deg);
  }
  100% {
    transform: none;
    opacity: .7;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-roll-out,
  .fd-level-face.is-out {
    display: none;
  }
  .fd-roll-in,
  .fd-level-face.is-in,
  .fd-seat-chip.is-tipping {
    animation: none;
  }
}
.fd-seat-count {
  border-top: 1px solid var(--night-line);
  padding: 9px 14px;
}
.fd-seat-count-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.fd-seat-count-line {
  flex: 1;
  min-width: 0;
  color: var(--night-text);
  font: 500 14px/1.35 var(--fd-body);
}
.fd-seat-count-line b {
  color: var(--bone);
  font: 800 18px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  margin-left: 4px;
}
.fd-seat-action {
  flex-shrink: 0;
  min-width: 44px;
  min-height: 44px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--lamp-info);
  font: 600 14px/1 var(--fd-body);
  cursor: pointer;
}
.fd-seat-action.is-bust {
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--clay-text);
  box-shadow: var(--glass-edge);
}
.fd-seat-action.is-bust.is-confirming {
  border: 1.5px solid var(--ink0);
  background: var(--clay);
  color: var(--bone);
}
.fd-seat-action:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-chip-count-save {
  width: 100%;
}

/* src/features/poker/poker-chips.css */
.fd-poker-stacks {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  min-width: 0;
}
.fd-poker-stack {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.fd-poker-count {
  min-width: 18px;
  padding: 1px 4px;
  border-radius: 99px;
  background: var(--ink-tint);
  color: var(--ink);
  font: 700 12px/1.15 var(--fd-body);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.fd-poker-grant {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  padding: 2px 6px;
  border-radius: 99px;
  background: var(--clay-tint);
  color: var(--live2);
  font: 700 12px/1.15 var(--fd-body);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.fd-poker-tray {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 14px 18px;
}
.fd-poker-tray-denom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.fd-poker-tray-tubes {
  display: flex;
  align-items: flex-end;
  gap: 2px;
}
.fd-poker-tray-count {
  font: 700 18px/1 var(--fd-display, var(--fd-display));
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* src/features/poker/table-view.css */
.fd-table-view {
  position: fixed;
  inset: 0;
  z-index: 380;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  background: var(--night-deep);
  color: var(--bone);
  font-family: var(--fd-body);
  padding: calc(env(safe-area-inset-top, 0px) + 10px) 20px calc(env(safe-area-inset-bottom, 0px) + 18px);
  animation: fd-table-view-in var(--motion-stamp, 320ms) var(--ease-out, ease-out) both;
}
@keyframes fd-table-view-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.fd-table-view-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 60px;
}
.fd-table-view-level {
  flex: 1;
  min-width: 0;
  font: 800 16px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--night-text);
}
.fd-table-view-exit {
  min-width: 64px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 10px;
  cursor: pointer;
  background: var(--paper);
  color: var(--bone);
  border: 1px solid var(--ghost-line);
  font: 700 14px var(--fd-body);
  box-shadow: var(--glass-edge);
}
.fd-table-view-exit:focus-visible,
.fd-table-view-entry button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-table-view-ring {
  position: relative;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
}
.fd-table-view-ring svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  overflow: visible;
}
.fd-table-view-ring circle {
  fill: none;
  stroke-width: 3.5;
}
.fd-table-view-ring .track {
  stroke: var(--paper2);
}
.fd-table-view-ring .run {
  stroke: var(--sun);
  stroke-linecap: round;
  filter: drop-shadow(0 0 3px var(--sun));
  transition: stroke-dashoffset 1s linear;
}
.fd-table-view-ring.is-paused .run {
  stroke: var(--muted);
  filter: none;
}
.fd-table-view-label {
  display: block;
  color: var(--night-text);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-table-view-blinds {
  margin-top: auto;
  padding-top: 18px;
}
.fd-table-view-blinds-fit {
  line-height: .9;
  margin-top: 8px;
  padding: 10px 12px 8px;
  border-radius: 14px;
  background: var(--ink0);
  box-shadow:
    inset 0 3px 10px color-mix(in srgb, var(--ink0) 80%, transparent),
    0 0 0 1px var(--line),
    var(--glass-edge);
  overflow: hidden;
}
.fd-table-view-blinds-num {
  font-family: var(--fd-display);
  font-weight: 800;
  font-size: inherit;
  line-height: .92;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0;
  white-space: nowrap;
}
.fd-table-view-clock {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 16px;
}
.fd-table-view-clock b {
  font: 800 68px/1 var(--fd-display);
  color: var(--lamp-live-text);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 22px color-mix(in srgb, var(--lamp-live) 45%, transparent);
}
.fd-table-view-clock b.is-late {
  color: var(--clay-text);
  text-shadow: 0 0 22px color-mix(in srgb, var(--clay) 45%, transparent);
}
.fd-table-view-clock b.is-paused {
  color: var(--night-text);
  text-shadow: none;
}
.fd-table-view:focus {
  outline: none;
}
.fd-table-view-clock > span {
  font: 600 16px/1.3 var(--fd-body);
  color: var(--night-text);
  font-variant-numeric: tabular-nums;
}
.fd-table-view-seat {
  margin-top: auto;
  padding-top: 22px;
  border-top: 1px solid var(--night-line);
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.fd-table-view-stack b {
  display: block;
  margin-top: 6px;
  font: 800 52px/1 var(--fd-display);
  color: var(--sun);
  font-variant-numeric: tabular-nums;
}
.fd-table-view-denoms {
  gap: 12px;
}
.fd-table-view-denoms .fd-poker-count {
  font-size: 13px;
}
.fd-table-view-out {
  margin: 0;
  font: 900 46px/1.05 var(--fd-show);
  color: var(--clay-text);
}
.fd-table-view-in {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.fd-table-view-in span {
  font: 600 14px/1.2 var(--fd-body);
  color: var(--night-text);
}
.fd-table-view-entry {
  border-top: 1px solid var(--night-line);
}
.fd-table-view-entry button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 48px;
  padding: 0 14px;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: var(--lamp-info);
  font: 600 14px/1.2 var(--fd-body);
  letter-spacing: 0;
  text-transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .fd-table-view {
    animation: none;
  }
}

/* src/features/duels/duel-card.css */
.fd-duel-card {
  margin-bottom: 8px;
  padding: 12px;
  min-width: 0;
}
.fd-duel-card.is-bare {
  margin: 0;
  padding: 0;
}
.fd-duel-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.fd-duel-person {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink);
  text-align: left;
  font-family: var(--fd-body);
}
button.fd-duel-person {
  cursor: pointer;
}
button.fd-duel-person:disabled {
  cursor: default;
}
button.fd-duel-person:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
  border-radius: 10px;
}
.fd-duel-who {
  display: grid;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
.fd-duel-who strong {
  font-size: 22px;
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.fd-duel-status {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted2);
  font: 600 13px/1.35 var(--fd-body);
  overflow-wrap: anywhere;
}
.fd-duel-status .fd-insert {
  --lamp:var(--lamp-live);
  width: 10px;
  height: 10px;
}
.fd-duel-ante {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  flex-shrink: 0;
}
.fd-duel-ante strong {
  color: var(--sun);
  font: 800 24px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-duel-actions {
  display: grid;
  grid-template-columns: repeat(var(--duel-actions, 1), minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}
.fd-duel-act {
  min-width: 0;
  min-height: 44px;
  padding: 10px 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper2);
  color: var(--ink);
  box-shadow: var(--glass-edge);
  font: 600 13px/1.2 var(--fd-body);
  overflow-wrap: anywhere;
  cursor: pointer;
  transition: transform .1s, opacity .15s;
}
.fd-duel-act.is-primary {
  border-color: var(--action-fill);
  background: var(--action-fill);
  color: var(--action-ink);
}
.fd-duel-act.is-danger {
  border-color: var(--danger-line);
  color: var(--clay-text);
}
.fd-duel-act:disabled {
  cursor: default;
}
.fd-duel-act.is-waiting {
  opacity: .55;
}
.fd-duel-act:active:not(:disabled) {
  transform: translateY(1px);
}
.fd-duel-act:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-duel-done {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 10px 0 0;
  color: var(--muted2);
  font: 700 13px/1.3 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-duel-error {
  margin: 10px 0 0;
  color: var(--clay-text);
  font: 600 12px/1.5 var(--fd-body);
  overflow-wrap: anywhere;
}
.fd-duel-send {
  display: grid;
  justify-items: center;
  gap: 12px;
  padding: 14px 12px 12px;
}
.fd-duel-send-face {
  display: flex;
  align-items: center;
  gap: 12px;
}
.fd-duel-send-vs {
  color: var(--muted2);
  font-size: 24px;
  line-height: 1.15;
}
.fd-duel-rack {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
.fd-duel-rack > button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 52px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  perspective: 220px;
  -webkit-tap-highlight-color: transparent;
}
.fd-duel-rack > button > .fd-coin3d {
  transform: rotateX(30deg);
  transition: transform .42s var(--ease-drum);
}
.fd-duel-rack > button > .fd-coin3d > .fd-coin3d-edge {
  filter: brightness(.62);
}
.fd-duel-rack > button > .fd-coin3d > .fd-coin3d-face::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--paper);
  opacity: .32;
  transition: opacity .16s ease;
  pointer-events: none;
}
.fd-duel-rack > button.is-selected > .fd-coin3d {
  transform: translateY(-4px) translateZ(10px) rotateX(-8deg);
}
.fd-duel-rack > button.is-selected > .fd-coin3d > .fd-coin3d-edge,
.fd-duel-rack > button:disabled > .fd-coin3d > .fd-coin3d-edge {
  filter: none;
}
.fd-duel-rack > button.is-selected > .fd-coin3d > .fd-coin3d-face::after,
.fd-duel-rack > button:disabled > .fd-coin3d > .fd-coin3d-face::after {
  opacity: 0;
}
.fd-duel-rack > button.is-selected > .fd-coin3d > .fd-coin3d-face {
  border-radius: 50%;
  box-shadow: 0 0 0 2px var(--sun), var(--chip-bloom);
}
.fd-duel-rack > button:active:not(:disabled) > .fd-coin3d {
  transform: translateY(1px) translateZ(-6px) rotateX(36deg);
  transition-duration: .12s;
}
.fd-duel-rack > button:disabled {
  cursor: default;
}
.fd-duel-rack > button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-duel-unlit {
  display: block;
}
.fd-duel-unlit-body {
  fill: var(--ink0);
  stroke: var(--ghost-line);
  stroke-width: 1.5;
}
.fd-duel-unlit-tick {
  fill: color-mix(in srgb, var(--muted) 45%, var(--ink0));
}
.fd-duel-unlit-face {
  fill: color-mix(in srgb, var(--paper2) 70%, var(--ink0));
  stroke: color-mix(in srgb, var(--ink0) 80%, transparent);
  stroke-width: 1;
}
.fd-duel-unlit-value {
  fill: var(--muted2);
  font: 800 14px var(--fd-display);
  letter-spacing: 0;
}
.fd-duel-max {
  color: var(--sun);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
@media (prefers-reduced-motion: reduce) {
  .fd-duel-rack > button > .fd-coin3d {
    transition: none;
  }
}

/* src/features/standings/standings.css */
.fd-standings-page {
  padding: 0 18px 24px;
}
.fd-standings-page .fd-page-heading {
  padding-bottom: 16px;
}
.fd-board-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  color: var(--ink);
  font: 800 16px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-board-state.is-final {
  color: var(--ink);
}
.fd-leader-panel {
  position: relative;
  margin: 0 0 16px;
  padding: 18px;
  border: 1px solid var(--sun);
  border-radius: 14px;
  box-shadow: var(--chip-bloom), var(--glass-edge);
  background: var(--paper2);
  color: var(--ink);
  overflow: hidden;
}
.fd-leader-topline {
  margin: 0;
  color: var(--sun);
  font: 800 18px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-leader-identity {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 14px 0 4px;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  color: var(--ink);
  cursor: pointer;
}
.fd-leader-identity > span {
  min-width: 0;
  flex: 1;
  font-size: clamp(30px, 8.5vw, 44px);
  overflow-wrap: anywhere;
}
.fd-leader-score {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin-top: 8px;
}
.fd-leader-score > strong {
  font: 800 clamp(58px, 17vw, 82px)/.95 var(--fd-display);
  color: var(--sun);
}
.fd-leader-score > span {
  color: var(--muted2);
  font: 700 16px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-leader-tiebreak {
  border-top: 1px solid var(--line);
  margin: 15px 0 0;
  padding-top: 12px;
  font: 500 13px/1.5 var(--fd-body);
}
.fd-now-card {
  display: block;
  width: 100%;
  margin: 0 0 20px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
  color: var(--ink);
  text-align: left;
}
button.fd-now-card {
  cursor: pointer;
}
.fd-now-live {
  border-color: var(--lamp-live);
  box-shadow: var(--live-bloom), var(--glass-edge);
}
.fd-now-event-link {
  display: block;
  width: 100%;
  border: 0;
  padding: 0;
  background: none;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.fd-now-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.fd-now-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted2);
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-now-live .fd-now-status {
  color: var(--ink);
}
.fd-now-open {
  display: flex;
  color: var(--muted2);
}
.fd-now-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 8px 0 10px;
}
.fd-now-title-row > svg {
  flex-shrink: 0;
}
.fd-now-event {
  min-width: 0;
  font-size: clamp(24px, 6.5vw, 30px);
  overflow-wrap: anywhere;
}
.fd-now-matchup {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 28px minmax(0, 1fr);
  gap: 8px 5px;
  border-top: 1px solid var(--line);
  padding-top: 10px;
}
.fd-now-round {
  grid-column: 1/-1;
  font: 700 14px/1.3 var(--fd-display);
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--muted2);
}
.fd-now-players {
  display: flex;
  min-width: 0;
  flex-direction: column;
}
.fd-now-player {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  width: 100%;
  padding: 4px 0;
  border: 0;
  background: none;
  color: var(--ink);
  font: 600 14px/1.3 var(--fd-body);
  text-align: left;
  cursor: pointer;
}
.fd-now-player > span {
  overflow-wrap: anywhere;
}
.fd-now-versus {
  align-self: center;
  text-align: center;
  color: var(--muted2);
  font: 800 15px/1 var(--fd-display);
  text-transform: uppercase;
}
.fd-now-progress {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 8px 12px;
  margin-top: 10px;
  color: var(--muted2);
  font: 500 13px/1.4 var(--fd-body);
}
.fd-now-progress > button {
  display: flex;
  align-items: center;
  gap: 4px;
  border: 0;
  background: none;
  color: var(--lamp-info);
  font: 600 14px/1 var(--fd-body);
  min-height: 44px;
  cursor: pointer;
}
.fd-now-progress progress {
  width: 100%;
  height: 4px;
  grid-column: 1/-1;
  border: 0;
  border-radius: 0;
  background: var(--line);
  color: var(--lamp-live);
  appearance: none;
}
.fd-now-progress progress::-webkit-progress-bar {
  background: var(--line);
}
.fd-now-progress progress::-webkit-progress-value {
  background: var(--lamp-live);
}
.fd-now-progress progress::-moz-progress-bar {
  background: var(--lamp-live);
}
.fd-now-result {
  background: var(--paper2);
}
.fd-now-result-body {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--line);
  padding-top: 8px;
}
.fd-now-award {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  text-align: right;
  gap: 2px;
}
.fd-now-award > strong {
  font: 800 34px/.95 var(--fd-display);
  color: var(--sun);
}
.fd-now-award > span {
  font: 600 12px/1.4 var(--fd-body);
  color: var(--muted2);
}
.fd-now-impact {
  display: block;
  border-top: 1px solid var(--line);
  padding-top: 9px;
  margin-top: 9px;
  font: 400 13px/1.5 var(--fd-body);
  color: var(--muted2);
}
.fd-now-next-detail {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 5px 14px;
  font: 500 13px/1.4 var(--fd-body);
  color: var(--muted2);
}
.fd-standings-column-head {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 10px;
  margin: 4px 0 0;
  padding: 0 4px 6px;
  border-bottom: 1px solid var(--ghost-line);
  font: 700 13px/1.2 var(--fd-display);
  color: var(--muted2);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-leaderboard.has-adjustments .fd-standings-column-head {
  padding-right: 62px;
}
.fd-leaderboard {
  --fd-row-ground:var(--bg);
}
.si-sheet .fd-leaderboard {
  --fd-row-ground:var(--paper);
}
.fd-standings-list {
  position: relative;
  list-style: none;
  padding: 0;
  margin: 0;
}
.fd-standings-list > li {
  position: relative;
  border-bottom: 1px solid var(--line);
}
.fd-standings-row {
  display: grid;
  align-items: center;
  grid-template-columns: 30px 32px minmax(0, 1fr) auto;
  gap: 0 10px;
  width: 100%;
  min-height: 46px;
  padding: 5px 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-leaderboard.is-level .fd-standings-row {
  grid-template-columns: 0 32px minmax(0, 1fr) auto;
  column-gap: 12px;
}
.fd-leaderboard.is-level .fd-standings-column-head {
  grid-template-columns: 0 minmax(0, 1fr) auto;
}
.fd-standings-row:active {
  transform: none;
}
.fd-standing-position {
  position: relative;
  display: block;
  height: 24px;
  overflow: hidden;
  text-align: center;
