}
.fd-standings-list > .is-you .fd-standing-position {
  color: var(--you);
}
.fd-home .fd-standings-list > .is-you {
  position: sticky;
  bottom: calc(var(--fd-nav-height) + var(--fd-dock-h, 0px) + 8px);
}
.fd-home .fd-standings-list > .is-you[data-stuck] {
  box-shadow:
    var(--you-bloom),
    0 0 0 9px var(--fd-row-ground, var(--bg)),
