}
.si-sheet .fd-standings-list > .is-you {
  position: sticky;
  bottom: 8px;
}
.fd-standings-list > li.is-moving {
  z-index: 1;
  background-color: var(--fd-row-ground);
}
.fd-standings-list > li.is-moving.is-rising {
  z-index: 3;
  box-shadow: var(--shadow-2);
}
.fd-standings-list > li.is-you.is-moving {
  z-index: 5;
  background-color: color-mix(in srgb, var(--you) 9%, var(--fd-row-ground));
  box-shadow: var(--you-bloom);
}
.fd-standings-list > li.is-you.is-moving.is-rising {
  box-shadow: var(--you-bloom), var(--shadow-2);
}
.fd-standing-rise {
  position: absolute;
  right: 0;
  bottom: 100%;
  margin-bottom: -2px;
  white-space: nowrap;
  font: 800 16px/1 var(--fd-display);
  animation-delay: 150ms;
}
.fd-rank-roll {
  position: relative;
  display: block;
  height: 24px;
}
.fd-rank-roll > span {
  display: block;
  height: 24px;
}
.fd-rank-old {
  position: absolute;
  inset: 0;
  opacity: 0;
}
.fd-rank-roll .fd-rank-old {
  animation: fd-rank-out var(--motion-rank, 200ms) var(--ease-out) var(--roll-delay, 0ms) both;
}
.fd-rank-roll .fd-rank-new {
  animation: fd-rank-in var(--motion-rank, 200ms) var(--ease-out) var(--roll-delay, 0ms) both;
}
.fd-rank-roll.is-down .fd-rank-old {
  animation-name: fd-rank-out-down;
}
.fd-rank-roll.is-down .fd-rank-new {
  animation-name: fd-rank-in-down;
}
@keyframes fd-rank-out {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(-100%);
  }
}
@keyframes fd-rank-in {
  from {
    opacity: 0;
    transform: translateY(100%);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fd-rank-out-down {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(100%);
  }
}
@keyframes fd-rank-in-down {
  from {
    opacity: 0;
    transform: translateY(-100%);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.fd-standing-delta.is-popping {
  animation: fd-arrow-pop 220ms var(--ease-land) 1500ms both;
}
@keyframes fd-arrow-pop {
  from {
    opacity: 0;
    transform: scale(0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.fd-standings-row[data-new-leader] {
  animation: fd-lead-warm 1500ms var(--ease-out) 1500ms both;
}
.fd-standings-row[data-new-leader] .fd-standing-position {
  animation: fd-lead-ink 300ms var(--ease-out) 1500ms both;
}
@keyframes fd-lead-warm {
  from {
    background-color: transparent;
  }
  25% {
    background-color: var(--sun-tint);
  }
  to {
    background-color: transparent;
  }
}
@keyframes fd-lead-ink {
  from {
    color: var(--ink);
  }
  to {
    color: var(--sun);
  }
}
.fd-lead-sweep {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  z-index: 2;
  height: 2px;
  background: var(--sun);
  box-shadow: 0 0 10px var(--sun);
  transform-origin: left center;
  opacity: 0;
  pointer-events: none;
  animation: fd-lead-sweep 800ms var(--ease-out) 1550ms both;
}
@keyframes fd-lead-sweep {
  0% {
    opacity: 1;
    transform: scaleX(0);
  }
  50% {
    opacity: 1;
    transform: scaleX(1);
  }
  100% {
    opacity: 0;
    transform: scaleX(1);
  }
}
.fd-standings-list > .has-adjust {
  display: flex;
  align-items: center;
  gap: 10px;
}
.fd-standings-list > .has-adjust > .fd-standings-row {
