  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  padding: 23px 0 2px;
}
.fd-standings-page button:focus-visible,
.fd-leaderboard button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
@media (hover: hover) {
  .fd-now-player:hover > span,
  .fd-standings-row:hover .fd-standing-name {
    text-decoration: underline;
    text-underline-offset: 3px;
  }
  .fd-now-event-link:hover .fd-now-event {
    color: var(--lamp-info);
  }
}
@media (max-width: 360px) {
