    display: none;
  }
}
.fd-standing-flags {
  align-items: center;
}
.fd-tie-bracket {
  position: absolute;
  left: 2px;
  top: 0;
  bottom: -1px;
  width: 6px;
  pointer-events: none;
  z-index: 1;
  border-left: 2px solid var(--muted2);
}
.fd-tie-bracket::after {
  content: "";
  position: absolute;
  left: 0;
  top: calc(50% - 1px);
  width: 6px;
  height: 2px;
  background: var(--muted2);
}
.is-tie-start > .fd-tie-bracket {
  top: 50%;
  border-top-left-radius: 99px;
}
.is-tie-end > .fd-tie-bracket {
  bottom: 50%;
  border-bottom-left-radius: 99px;
}
.is-tie-start > .fd-tie-bracket::after {
  top: -1px;
}
.is-tie-end > .fd-tie-bracket::after {
  top: auto;
  bottom: -1px;
}
.fd-standings-list > .is-you > .fd-tie-bracket {
