}
@keyframes fd-row-find {
  0%, 55% {
    background-color: color-mix(in srgb, var(--you) 24%, var(--fd-row-ground, var(--bg)));
    box-shadow: var(--you-bloom), 0 0 0 2px var(--you);
  }
  28% {
    background-color: color-mix(in srgb, var(--you) 8%, var(--fd-row-ground, var(--bg)));
