  cursor: pointer;
  overflow-wrap: anywhere;
  transition: background var(--motion-fast, 120ms) var(--ease-out, ease-out), border-color var(--motion-fast, 120ms) var(--ease-out, ease-out);
}
.fd-teamname-chip.is-tool {
  min-width: 44px;
  display: grid;
  place-items: center;
  padding: 0 10px;
  color: var(--lamp-info);
}
.fd-teamname-chip.is-on {
  border-color: var(--lamp-info);
  background: var(--info-tint);
  color: var(--ink);
  box-shadow: 0 0 0 1px var(--lamp-info), 0 0 12px color-mix(in srgb, var(--lamp-info) 28%, transparent);
}
.fd-teamname-chip:disabled {
  cursor: default;
}
.fd-teamname-chip:disabled:not(.is-on) {
  opacity: .55;
}
.fd-teamname-chip.is-on[aria-pressed=true] {
  animation: fd-teamname-pick var(--motion-stamp, 320ms) var(--ease-land, ease-out) both;
}
@keyframes fd-teamname-pick {
  0% {
    transform: scale(.94);
  }
  60% {
    transform: scale(1.04);
  }
  100% {
    transform: scale(1);
  }
}
.fd-teamname-own {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin-top: 4px;
}
.fd-teamname-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--lamp-info);
  font: 600 14px/1.2 var(--fd-body);
  cursor: pointer;
}
.fd-teamname-link:disabled {
  opacity: .5;
  cursor: default;
}
.fd-teamname-write {
