  gap: 8px;
  margin-top: 8px;
}
.fd-teamname-write input {
  flex: 1;
  min-width: 0;
  height: 48px;
  padding: 0 12px;
  border: 1px solid var(--ghost-line);
  border-radius: 10px;
  background: var(--bg);
  color: var(--ink);
  font: 600 16px/1.2 var(--fd-body);
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, .45);
}
.fd-teamname-write input::placeholder {
  color: var(--muted);
}
.fd-teamname-write input:focus {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-teamname-save {
  flex-shrink: 0;
  min-width: 76px;
  height: 48px;
  padding: 0 16px;
  border: 0;
  border-radius: 8px;
  background: var(--action-fill, var(--sun));
  color: var(--ink0);
  font: 600 15px/1 var(--fd-body);
  box-shadow: var(--glass-edge);
  cursor: pointer;
}
.fd-teamname-save:disabled {
  opacity: .35;
  cursor: default;
}
.fd-teamname-error {
  margin: 8px 0 0;
  color: var(--clay-text);
  font: 600 13px/1.35 var(--fd-body);
}
.fd-teamname-desk {
  margin: 0 0 12px;
}
.fd-teamname-desk h3 {
  margin: 0 0 8px;
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-relettered {
  position: relative;
  animation: fd-reletter 520ms var(--ease-land) both;
  transform-origin: 50% 100%;
}
.fd-relettered::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: 6px;
  background:
    linear-gradient(
      100deg,
      transparent 35%,
      color-mix(in srgb, var(--lamp-info) 55%, var(--bone)) 50%,
      transparent 65%);
  background-size: 300% 100%;
  mix-blend-mode: screen;
  opacity: 0;
  animation: fd-reletter-sweep 900ms var(--ease-out, cubic-bezier(.2,.8,.2,1)) both;
}
span.fd-relettered,
strong.fd-relettered {
  display: inline-block;
}
@keyframes fd-reletter {
  0% {
    opacity: 0;
    transform: perspective(400px) rotateX(-80deg);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes fd-reletter-sweep {
  0% {
    opacity: .9;
    background-position: 100% 0;
  }
  80% {
    opacity: .9;
  }
  100% {
    opacity: 0;
    background-position: 0 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-relettered,
  .fd-relettered::after,
  .fd-teamname-chip.is-on[aria-pressed=true] {
    animation: none;
  }
}
.fd-teamname-row {
  margin: 0 0 12px;
