/* src/features/weekend/events.css */
.fd-events-session {
  margin: 0 0 26px;
}
.fd-events-session-heading {
  margin: 0 0 8px;
  padding: 0 2px;
  color: var(--muted2);
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-events-list {
  list-style: none;
  margin: 0;
  padding: 0 12px;
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
  border: 1px solid var(--line);
}
.fd-events-row {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  min-width: 0;
}
.fd-events-row + .fd-events-row {
  border-top: 1px solid var(--line);
}
.fd-events-open {
  display: flex;
  flex: 1 1 100%;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 64px;
  padding: 10px 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  transition: transform .15s var(--ease-out);
}
.fd-events-open:active:not(:disabled) {
  transform: translateX(2px);
}
.fd-events-open:disabled {
  cursor: default;
}
.fd-events-open:focus-visible,
.fd-events-bracket:focus-visible,
.fd-events-session-toggle:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
  border-radius: 8px;
}
.fd-events-lamp {
  display: grid;
  place-items: center;
  width: 14px;
  flex-shrink: 0;
}
.fd-events-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
}
.fd-events-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.fd-events-body > strong {
  font-size: 24px;
  line-height: 1.15;
  overflow-wrap: break-word;
}
.fd-events-part {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  min-width: 0;
}
.fd-events-status {
  color: var(--ink);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-events-you {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}
.fd-events-you small {
  color: var(--muted2);
  font-size: 12px;
  font-weight: 600;
}
.fd-events-pays {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.fd-events-winners {
  display: inline-flex;
}
.fd-events-medal {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bone);
  color: var(--ink0);
  border: 2px solid var(--ink0);
  font: 800 15px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-events-medal.is-first {
  background: var(--sun);
}
.fd-events-medal.is-crew {
  background: transparent;
  border: 2px dashed var(--muted);
}
.fd-events-row.is-done .fd-events-body > strong {
  color: var(--muted2);
}
.fd-events-row.is-void .fd-events-body > strong {
  color: var(--muted);
  text-decoration: line-through;
  text-decoration-thickness: 2px;
}
.fd-events-row.is-live {
  margin: 0 -12px;
  padding: 0 12px;
  background: var(--ink-tint);
  border-radius: 10px;
}
.fd-events-row.is-live + .fd-events-row,
.fd-events-row + .fd-events-row.is-live {
  border-top-color: transparent;
}
.fd-events-row.is-finale .fd-events-mark {
  border-radius: 50%;
  background: var(--sun);
  color: var(--ink0);
}
.fd-events-bracket {
  flex-shrink: 0;
  min-height: 44px;
  margin: 0 0 10px 62px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: transparent;
  color: var(--lamp-info);
  font: 600 13px/1 var(--fd-body);
  cursor: pointer;
}
.fd-events-bracket:hover {
  background: var(--info-tint);
}
.fd-events-session.is-folded {
  margin-bottom: 10px;
}
.fd-events-session-fold {
  margin: 0;
  font: inherit;
}
.fd-events-session-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 52px;
  padding: 6px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
  color: var(--muted2);
  text-align: left;
  cursor: pointer;
}
.fd-events-session.is-done:not(.is-folded) .fd-events-session-toggle {
  margin-bottom: 8px;
}
.fd-events-session-name {
  flex: 1;
  min-width: 0;
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-events-session-winners {
  flex-shrink: 0;
}
.fd-events-session.is-shelved .fd-events-row {
  opacity: .7;
}
@media (max-width: 359px) {
  .fd-events-open {
    gap: 8px;
  }
  .fd-events-body > strong {
    font-size: 22px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-events-open {
    transition: none;
  }
}
.fd-events-row:has(.fd-weekend-reorder) .fd-events-open {
  flex: 1 1 0;
}
.fd-events-row:has(.fd-events-bracket) .fd-events-open {
  padding-bottom: 4px;
  min-height: 56px;
}

/* src/features/weekend/trophy.css */
.fd-cup {
  --cup-lacquer:color-mix(in srgb, var(--bone) 6%, var(--ink0));
  --cup-lacquer-lit:color-mix(in srgb, var(--bone) 22%, var(--ink0));
  --cup-lacquer-face:linear-gradient(
      90deg,
      var(--ink0) 0%,
      var(--cup-lacquer) 9%,
      var(--cup-lacquer-lit) 24%,
      var(--cup-lacquer) 40%,
      var(--cup-lacquer) 74%,
      color-mix(in srgb, var(--bone) 13%, var(--ink0)) 86%,
      var(--ink0) 100%);
  --cup-trim:linear-gradient(
      90deg,
      color-mix(in srgb, var(--sun) 34%, var(--ink0)),
      color-mix(in srgb, var(--sun) 60%, var(--bone)) 24%,
      var(--sun) 44%,
      color-mix(in srgb, var(--sun) 62%, var(--ink0)) 74%,
      color-mix(in srgb, var(--sun) 30%, var(--ink0)));
  --cup-blank:linear-gradient(
      180deg,
      color-mix(in srgb, var(--silver) 20%, var(--ink0)),
      color-mix(in srgb, var(--silver) 12%, var(--ink0)));
  --cup-blank-edge:inset 0 1px 0 color-mix(in srgb, var(--bone) 16%, transparent),
    inset 0 -1px 0 color-mix(in srgb, var(--ink0) 70%, transparent),
    inset 0 2px 5px color-mix(in srgb, var(--ink0) 60%, transparent);
  --cup-silver:linear-gradient(
      100deg,
      color-mix(in srgb, var(--silver) 60%, var(--ink0)) 0%,
      color-mix(in srgb, var(--silver) 55%, var(--bone)) 22%,
      var(--silver) 44%,
      color-mix(in srgb, var(--silver) 80%, var(--ink0)) 72%,
      color-mix(in srgb, var(--silver) 62%, var(--bone)) 88%,
      color-mix(in srgb, var(--silver) 64%, var(--ink0)) 100%);
  --cup-silver-edge:inset 0 1px 0 color-mix(in srgb, var(--bone) 75%, transparent),
    inset 0 -1px 0 color-mix(in srgb, var(--ink0) 45%, transparent),
    0 0 0 1px color-mix(in srgb, var(--ink0) 70%, transparent),
    0 2px 3px color-mix(in srgb, var(--ink0) 70%, transparent);
  --cup-cut-ink:color-mix(in srgb, var(--ink0) 86%, var(--silver));
  --cup-cut-lip:0 1px 0 color-mix(in srgb, var(--bone) 62%, transparent), 0 -1px 0 color-mix(in srgb, var(--ink0) 28%, transparent);
  --cup-radius:4px;
  --cup-ledge:7px;
  --cup-step:14px;
  --cup-trim-h:3px;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  margin: 0 auto;
}
:where(.fd-cup) ol {
  list-style: none;
  margin: 0;
  padding: 0;
}
.fd-cup-bowl {
  position: relative;
  z-index: 2;
  width: min(82%, 320px);
  aspect-ratio: 600 / 330;
  container-type: inline-size;
}
.fd-cup-art {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.fd-cup-cartouche {
  position: absolute;
  left: 28.33%;
  top: 21.8%;
  width: 43.33%;
  height: 33.94%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .2em;
  padding: 0 3%;
  border-radius: 12% / 22%;
  background: var(--cup-silver);
  color: var(--cup-cut-ink);
  overflow: hidden;
  box-shadow:
    inset 0 2px 0 color-mix(in srgb, var(--bone) 70%, transparent),
    inset 0 -2px 0 color-mix(in srgb, var(--ink0) 40%, transparent),
    inset 0 0 0 1px color-mix(in srgb, var(--ink0) 30%, transparent),
    0 0 0 1.5px var(--ink0),
    0 3px 4px color-mix(in srgb, var(--ink0) 55%, transparent);
}
.fd-cup-cartouche::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--ink0) 34%, transparent),
      transparent 18%,
      transparent 80%,
      color-mix(in srgb, var(--ink0) 40%, transparent));
}
.fd-cup-edition {
  position: relative;
  z-index: 1;
  max-width: 100%;
  font: 800 max(12px, 4cqi)/1.1 var(--fd-show);
  letter-spacing: .04em;
  text-transform: uppercase;
  text-shadow: var(--cup-cut-lip);
  white-space: nowrap;
  opacity: .82;
}
.fd-cup-champ {
  position: relative;
  z-index: 1;
  max-width: 100%;
  font: 900 max(12px, 6.4cqi)/1.08 var(--fd-show);
  text-align: center;
  text-shadow: var(--cup-cut-lip);
  overflow-wrap: normal;
  text-wrap: balance;
}
@container (max-width: 250px) {
  .fd-cup-cartouche.is-posted .fd-cup-edition {
    display: none;
  }
}
.fd-cup-cartouche.is-next {
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--bone) 70%, transparent),
    0 0 18px color-mix(in srgb, var(--bone) 30%, transparent),
    inset 0 2px 0 color-mix(in srgb, var(--bone) 70%, transparent);
}
.fd-cup-cartouche.is-live {
  box-shadow: var(--live-bloom), inset 0 2px 0 color-mix(in srgb, var(--bone) 70%, transparent);
}
.fd-cup-base {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  margin-top: -3px;
}
.fd-cup-band {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 5px;
  width: calc(100% - var(--tier-rest, 0) * 2 * var(--cup-step));
  padding: calc(var(--cup-ledge) + var(--cup-trim-h) + 5px) 8px 8px;
  background: var(--cup-lacquer-face);
  border-radius: 3px 3px 2px 2px;
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--ink0) 80%, transparent), 0 6px 10px color-mix(in srgb, var(--ink0) 55%, transparent);
}
.fd-cup-band::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--cup-ledge);
  border-radius: 3px 3px 0 0;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 8%, var(--ink0)),
      color-mix(in srgb, var(--bone) 26%, var(--ink0)));
}
.fd-cup-band::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: var(--cup-ledge);
  height: var(--cup-trim-h);
  background: var(--cup-trim);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--ink0) 80%, transparent);
}
.fd-cup-band:last-child {
  border-radius: 3px 3px 6px 6px;
}
.fd-cup-session {
  position: relative;
  z-index: 1;
  font: 800 12px/1.2 var(--fd-show);
  text-transform: uppercase;
  letter-spacing: .08em;
  color: color-mix(in srgb, var(--sun) 70%, var(--bone));
}
.fd-cup-plates {
  position: relative;
  z-index: 1;
  display: grid;
