.fd-crown-flood {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.fd-crown-flood i {
  position: absolute;
  left: 50%;
  top: 38%;
  width: 300vmax;
  height: 300vmax;
  margin: -150vmax 0 0 -150vmax;
  border-radius: 50%;
  background: var(--crown-color);
  will-change: transform;
  animation: fd-crown-flood 1000ms cubic-bezier(.65, 0, .35, 1) calc(var(--tl, 0ms) + 14500ms) both;
}
@keyframes fd-crown-flood {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}
.fd-crown-moment.is-flood {
  color: var(--crown-ink);
  animation: fd-crown-ink 1ms linear calc(var(--tl, 0ms) + 14900ms) both;
}
@keyframes fd-crown-ink {
  from {
    color: var(--ink);
  }
  to {
    color: var(--crown-ink);
  }
}
@keyframes fd-crown-out {
  to {
    opacity: 0;
  }
}
.fd-crown-stage {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 10px;
  text-align: center;
}
.fd-crown-coins {
  display: flex;
  gap: 12px;
  perspective: 600px;
  margin-bottom: 10px;
}
.fd-crown-coin {
  display: block;
  animation: fd-crown-coin 1400ms var(--ease-out) calc(var(--tl, 0ms) + 15400ms) both;
}
@keyframes fd-crown-coin {
  0% {
    opacity: 0;
    transform: translateY(-60vh) rotateY(0deg);
  }
  8% {
    opacity: 1;
  }
  68% {
    transform: translateY(0) rotateY(720deg);
  }
  84% {
    transform: translateY(-18px) rotateY(720deg);
  }
  100% {
    transform: translateY(0) rotateY(720deg);
  }
}
.fd-crown-tag {
  margin: 0;
  font: 700 13px/1 var(--fd-body);
  letter-spacing: .3em;
  text-transform: uppercase;
  color: var(--sun);
  animation: fd-crown-tag var(--motion-stamp) var(--ease-land) calc(var(--tl, 0ms) + 15900ms) both;
}
.fd-crown-moment.is-flood .fd-crown-tag {
  color: inherit;
}
@keyframes fd-crown-tag {
  from {
    opacity: 0;
    transform: scale(1.6);
    letter-spacing: .6em;
  }
}
.fd-crown-name {
  margin: 0;
  font-size: clamp(52px, 17vw, 88px);
  line-height: 1;
  overflow-wrap: anywhere;
}
.fd-crown-name span {
  display: inline-block;
  animation: fd-crown-letter 380ms var(--ease-land) both;
  animation-delay: calc(var(--tl, 0ms) + 16200ms + var(--fd-letter) * 60ms);
}
@keyframes fd-crown-letter {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
}
.fd-crown-stack {
  margin: 4px 0 0;
  font: 600 15px/1 var(--fd-body);
  animation: fd-crown-fade 300ms ease-out calc(var(--tl, 0ms) + 17200ms) both;
}
.fd-crown-stack b {
  font: 700 40px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  margin-right: 4px;
}
.fd-crown-stack b .fd-reel {
  font-size: .78em;
  vertical-align: middle;
}
.fd-crown-you-pts .fd-reel {
  font-size: .8em;
}
@keyframes fd-crown-fade {
  from {
    opacity: 0;
  }
}
.fd-crown-cup {
  width: min(220px, 62vw);
  margin-top: 6px;
  animation: fd-crown-fade 500ms ease-out calc(var(--tl, 0ms) + 15400ms) both;
}
.fd-crown-skip {
  position: absolute;
  right: 16px;
  bottom: calc(env(safe-area-inset-bottom) + 16px);
  min-width: 64px;
  min-height: 44px;
  border: 1px solid currentColor;
  border-radius: 10px;
  background: none;
  color: inherit;
  opacity: .75;
  font: 600 14px var(--fd-body);
  cursor: pointer;
}
.fd-crown-card {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: calc(env(safe-area-inset-top) + 10px) 16px calc(env(safe-area-inset-bottom) + 20px);
}
.fd-crown-card > * {
  max-width: 420px;
  margin-left: auto;
  margin-right: auto;
}
.fd-crown-bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.fd-crown-close {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: none;
  color: var(--muted2);
  font-size: 15px;
  cursor: pointer;
}
.fd-crown-champ {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 8px auto 12px;
  padding: 9px 12px;
  border: 1px solid color-mix(in srgb, var(--sun) 45%, transparent);
  border-radius: 14px;
  background: var(--sun-tint);
}
.fd-crown-champ span {
  min-width: 0;
}
.fd-crown-champ small {
  display: block;
  margin-top: 3px;
  font: 600 12px/1.3 var(--fd-body);
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--sun);
}
.fd-crown-champ b {
  display: block;
  font: 800 20px/1.15 var(--fd-display);
}
.fd-crown-champ strong {
  margin-left: auto;
  font: 700 22px/1 var(--fd-display);
  color: var(--sun);
  font-variant-numeric: tabular-nums;
}
.fd-crown-card.is-arriving .fd-crown-bar,
.fd-crown-card.is-arriving .fd-crown-champ {
  animation: fd-crown-slide var(--motion-base) var(--ease-out) backwards;
}
@keyframes fd-crown-slide {
  from {
    opacity: 0;
    transform: translateY(-16px);
  }
}
.fd-crown-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.fd-crown-actions button {
  flex: 1;
  min-height: 48px;
  border-radius: 8px;
  font: 600 15px/1 var(--fd-body);
  cursor: pointer;
}
.fd-crown-save {
  border: 0;
  background: var(--action-fill);
  color: var(--action-ink);
}
.fd-crown-save:disabled {
  opacity: .7;
}
.fd-crown-board {
  border: 1px solid var(--line);
  background: none;
  color: var(--ink);
}
.fd-crown-poster {
  display: block;
  width: 100%;
  min-height: 48px;
  margin-top: 8px;
  border: 1px solid var(--sun);
  border-radius: 8px;
  background: none;
  color: var(--sun);
  font: 600 15px/1 var(--fd-body);
  cursor: pointer;
}
.fd-crown-poster:disabled {
  opacity: .7;
}
.fd-crown-card .fd-crown-preview {
  position: fixed;
}
.fd-crown-preview {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: calc(env(safe-area-inset-top) + 16px) 20px calc(env(safe-area-inset-bottom) + 16px);
  background: var(--scrim);
  backdrop-filter: blur(8px);
}
.fd-crown-preview img {
  max-width: 100%;
  max-height: 72vh;
  border-radius: 10px;
  box-shadow: var(--shadow-3);
  -webkit-touch-callout: default;
  user-select: auto;
  -webkit-user-select: auto;
}
.fd-crown-preview p {
  margin: 0;
  color: var(--bone);
  font: 600 14px/1.4 var(--fd-body);
  text-align: center;
}
.fd-crown-preview button {
  min-width: 120px;
  min-height: 44px;
  border: 1px solid var(--bone-line);
  border-radius: 10px;
  background: var(--paper2);
  color: var(--ink);
  font: 600 14px var(--fd-body);
  cursor: pointer;
}
.fd-lastcard {
  position: relative;
  overflow: hidden;
  padding: 16px 16px 14px;
  border-radius: 18px;
  background: var(--card-color);
  color: var(--card-ink);
  box-shadow: var(--lg-lip), var(--shadow-2);
}
.fd-lastcard-held {
  position: relative;
  perspective: 1100px;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
}
.fd-lastcard-held > .fd-lastcard,
.fd-lastcard-glare {
  transform: rotateX(calc(var(--ty,0) * -6deg)) rotateY(calc(var(--tx,0) * 8deg));
}
.fd-lastcard-glare {
  position: absolute;
  inset: 0;
  z-index: 2;
  overflow: hidden;
  border-radius: 18px;
  pointer-events: none;
}
.fd-lastcard-glare > span {
  position: absolute;
  top: -20%;
  bottom: -20%;
  left: -60%;
  right: -60%;
  background: var(--lg-sweep);
  opacity: calc(.35 + var(--tm,0) * .65);
  transform: translateX(calc(var(--tx,0) * 26% - 14%));
}
.fd-lastcard-held.is-tilting :is(.fd-lastcard, .fd-lastcard-glare, .fd-lastcard-glare > span) {
  will-change: transform;
}
.fd-lastcard-held.is-releasing :is(.fd-lastcard, .fd-lastcard-glare, .fd-lastcard-glare > span) {
  transition: transform var(--tilt-release,520ms) cubic-bezier(.16, 1, .3, 1), opacity var(--tilt-release,520ms) ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .fd-lastcard-glare > span {
    opacity: .3;
    transform: translateX(-14%);
  }
}
.fd-lastcard.is-turning {
  animation: fd-lastcard-turn var(--motion-card-flight) var(--ease-out) backwards;
  transform-origin: 50% 50%;
}
@keyframes fd-lastcard-turn {
  from {
    transform: perspective(900px) rotateY(88deg);
    opacity: .4;
  }
}
.fd-lastcard-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font: 700 12px/1.2 var(--fd-body);
  letter-spacing: .06em;
}
.fd-lastcard-chip {
  position: absolute;
  right: 14px;
  top: 30px;
}
.fd-lastcard-place {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  margin-top: 10px;
  padding-right: 70px;
}
.fd-lastcard-place b {
  font: 700 96px/.8 var(--fd-display);
  letter-spacing: -.01em;
}
.fd-lastcard-place span {
  padding-bottom: 4px;
}
.fd-lastcard-place strong {
  display: block;
  font: 700 30px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-lastcard-place small {
  font: 700 12px/1.4 var(--fd-body);
  letter-spacing: .08em;
}
.fd-lastcard-name {
  margin: 8px 0 2px;
  font: 800 44px/1 var(--fd-display);
  overflow-wrap: anywhere;
}
.fd-lastcard-chart {
  display: block;
  width: calc(100% + 8px);
  height: auto;
  margin: 10px -4px 4px;
  overflow: visible;
}
.fd-lastcard.is-turning .fd-lastcard-line {
  stroke-dasharray: 1;
  animation: fd-lastcard-draw 900ms var(--ease-out) backwards;
  animation-delay: calc(var(--motion-card-flight) - 80ms);
}
@keyframes fd-lastcard-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.fd-lastcard-chart-num {
  fill: currentColor;
  font: 700 13px var(--fd-display);
}
.fd-lastcard-tick {
  fill: currentColor;
  font: 700 12px var(--fd-body);
  letter-spacing: .04em;
}
.fd-lastcard-facts {
  margin: 6px 0 0;
  border-top: 1.5px solid currentColor;
}
.fd-lastcard-facts div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
  padding: 7px 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor 25%, transparent);
}
.fd-lastcard-facts dt {
  min-width: 0;
  font: 600 12px/1.3 var(--fd-body);
}
.fd-lastcard-facts dd {
  margin: 0;
  font: 700 16px/1 var(--fd-display);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.fd-lastcard-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
  font: 700 12px/1.2 var(--fd-body);
  letter-spacing: .06em;
}
.fd-lastcard-entry {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  min-height: 44px;
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: none;
  color: var(--ink);
  font: 600 14px/1 var(--fd-body);
  cursor: pointer;
}
.fd-lastcard-frame {
  position: relative;
  padding: 10px;
  border-radius: 18px;
  background: var(--paper2);
  box-shadow:
    var(--glass-edge),
    var(--shadow-2),
    inset 0 0 0 1px var(--line);
}
.fd-lastcard-frame > .fd-chase {
  z-index: 0;
}
.fd-lastcard-frame > .fd-chase rect {
  x: 3px;
  y: 3px;
  width: calc(100% - 6px);
  height: calc(100% - 6px);
  rx: 21px;
  ry: 21px;
  stroke-width: 4;
}
.fd-lastcard-frame > .fd-lastcard-held {
  z-index: 1;
}

/* src/features/results/keepsake.css */
