  font: inherit;
  cursor: pointer;
}
.fd-program-lead:disabled {
  cursor: default;
}
.fd-program-lead.is-edition {
  margin-top: auto;
}
.fd-program-lamp {
  flex-shrink: 0;
  align-self: center;
}
.fd-program-mark {
  position: relative;
}
.fd-program-mark > .fd-program-lamp {
  position: absolute;
  right: -3px;
  top: -3px;
  width: 14px;
  height: 14px;
}
.fd-program-title {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  max-width: 100%;
}
.fd-program-title > .is-lead {
  flex: 1;
  min-width: 0;
}
.fd-program-mark {
  flex-shrink: 0;
  display: flex;
  border-radius: 50%;
