  --ba:tp-tip 800ms linear calc(var(--tl) + var(--b-tip)) both, tp-crash 260ms ease-out calc(var(--tl) + var(--b-crash)) forwards;
  animation: var(--ba);
}
@keyframes tp-tip {
  0% {
    transform: rotate(0deg);
    animation-timing-function: cubic-bezier(.4, 0, .6, 1);
  }
  30% {
    transform: rotate(5deg);
    animation-timing-function: ease-in-out;
  }
  46% {
    transform: rotate(4deg);
    animation-timing-function: cubic-bezier(.5, 0, 1, .4);
  }
  100% {
    transform: rotate(90deg);
  }
}
@keyframes tp-crash {
  0% {
    transform: rotate(90deg);
  }
  35% {
    transform: rotate(83deg);
  }
  70% {
    transform: rotate(91deg);
  }
  100% {
    transform: rotate(90deg);
  }
}
.is-teamphoto .tp-dust {
  --dust-ms:640ms;
}

/* src/features/gags/bits/victorylap.css */
.is-victorylap .vl {
  position: absolute;
  inset: 0;
}
.is-victorylap .vl-node {
  position: absolute;
  display: block;
  width: 0;
  height: 0;
  transform-origin: 0 0;
}
.is-victorylap .vl-run {
  transform: var(--k12);
  --ba:vl-lap var(--b-arrive) linear calc(var(--tl) + 0ms) both;
  animation: var(--ba);
}
@keyframes vl-lap {
  0% {
    transform: var(--k0);
  }
  8.333% {
    transform: var(--k1);
  }
  16.667% {
    transform: var(--k2);
  }
  25% {
    transform: var(--k3);
  }
  33.333% {
    transform: var(--k4);
  }
  41.667% {
    transform: var(--k5);
  }
  50% {
    transform: var(--k6);
  }
  58.333% {
    transform: var(--k7);
  }
  66.667% {
    transform: var(--k8);
  }
  75% {
    transform: var(--k9);
  }
  83.333% {
    transform: var(--k10);
  }
  91.667% {
    transform: var(--k11);
  }
  100% {
    transform: var(--k12);
  }
}
.is-victorylap .vl-runner .cast-hop {
  --ba:vl-bound calc(var(--b-arrive) / 5) linear calc(var(--tl) + 0ms) 5 both;
  animation: var(--ba);
}
@keyframes vl-bound {
  0% {
    transform: translateY(0px);
    animation-timing-function: cubic-bezier(.2, .75, .4, 1);
  }
  42% {
    transform: translateY(var(--bob));
    animation-timing-function: linear;
  }
  64% {
    transform: translateY(var(--bob));
    animation-timing-function: cubic-bezier(.6, 0, .85, .5);
  }
  100% {
    transform: translateY(0px);
  }
}
.is-victorylap .vl-runner .cast-body-in {
  --ba:vl-lean calc(var(--b-arrive) * 2 / 5) ease-in-out calc(var(--tl) + 0ms) 2.5 both, vl-land 420ms ease-out calc(var(--tl) + var(--b-arrive)) forwards;
  animation: var(--ba);
}
@keyframes vl-lean {
  0%, 50%, 100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(4deg);
  }
  75% {
    transform: rotate(-4deg);
  }
}
@keyframes vl-land {
  0%, 100% {
    transform: rotate(0deg) scale(1, 1);
  }
  25% {
    transform: rotate(0deg) scale(1.06, .92);
  }
  60% {
    transform: rotate(0deg) scale(.98, 1.03);
  }
}
.is-victorylap .vl-runner .cast-shoe.is-l .cast-shoe-in {
  --ba:vl-kick calc(var(--b-arrive) * 2 / 5) linear calc(var(--tl) + 0ms) 2.5 both;
  animation: var(--ba);
}
.is-victorylap .vl-runner .cast-shoe.is-r .cast-shoe-in {
  --ba:vl-kick calc(var(--b-arrive) * 2 / 5) linear calc(var(--tl) + var(--b-arrive) / 5) 2 both;
  animation: var(--ba);
}
@keyframes vl-kick {
  0%, 50%, 100% {
    transform: translateY(0px) rotate(0deg);
  }
  10% {
    transform: translateY(-6px) rotate(-6deg);
  }
  25% {
    transform: translateY(-22px) rotate(-14deg);
  }
  42% {
    transform: translateY(-4px) rotate(-3deg);
  }
}
.is-victorylap .vl-runner .cast-chip-in {
  transform: rotateY(0deg) rotateX(0deg);
  --ba:vl-face var(--b-arrive) linear calc(var(--tl) + 0ms) both;
  animation: var(--ba);
}
@keyframes vl-face {
  0% {
    transform: rotateY(24deg) rotateX(0deg);
  }
  40% {
    transform: rotateY(22deg) rotateX(0deg);
  }
  62% {
    transform: rotateY(-8deg) rotateX(0deg);
  }
  82% {
    transform: rotateY(0deg) rotateX(0deg);
  }
  100% {
    transform: rotateY(0deg) rotateX(0deg);
  }
}
.is-victorylap .vl-runner.is-lead .cast-chip-in {
  --ba:vl-face var(--b-arrive) linear calc(var(--tl) + 0ms) both, vl-look 420ms cubic-bezier(.3,0,.2,1) calc(var(--tl) + var(--b-look)) forwards;
  animation: var(--ba);
}
@keyframes vl-look {
  from {
    transform: rotateY(0deg) rotateX(0deg);
  }
  to {
    transform: rotateY(-6deg) rotateX(30deg);
  }
}
.is-victorylap .vl-runner.is-mate .cast-hand.is-r .cast-hand-fx {
  --ba:vl-pump-r calc(var(--b-arrive) * 2 / 5) ease-in-out calc(var(--tl) + 0ms) 2.5 both;
  animation: var(--ba);
}
.is-victorylap .vl-runner .cast-hand.is-l .cast-hand-fx {
  --ba:vl-pump-l calc(var(--b-arrive) * 2 / 5) ease-in-out calc(var(--tl) + var(--b-arrive) / 5) 2 both;
  animation: var(--ba);
}
@keyframes vl-pump-r {
  0%, 50%, 100% {
    transform: none;
  }
  24% {
    transform: var(--pump);
  }
}
@keyframes vl-pump-l {
  0%, 50%, 100% {
    transform: none;
  }
  24% {
    transform: scaleX(-1) var(--pump) scaleX(-1);
  }
}
.is-victorylap .vl-runner.is-mate .cast-hand.is-r > .cast-hand-in {
  transform: var(--raise-r);
  --ba:vl-raise-r 300ms cubic-bezier(.2,1.5,.4,1) calc(var(--tl) + var(--b-plant)) both;
  animation: var(--ba);
}
.is-victorylap .vl-runner .cast-hand.is-l > .cast-hand-in {
  transform: var(--raise-l);
  --ba:vl-raise-l 300ms cubic-bezier(.2,1.5,.4,1) calc(var(--tl) + var(--b-plant) + 40ms) both;
  animation: var(--ba);
}
@keyframes vl-raise-r {
  from {
    transform: var(--tuck-r);
  }
  to {
    transform: var(--raise-r);
  }
}
@keyframes vl-raise-l {
  from {
    transform: var(--tuck-l);
  }
  to {
    transform: var(--raise-l);
  }
}
.is-victorylap .vl-runner.is-lead .cast-hand.is-r > .cast-hand-in {
  transform: var(--thrust);
  --ba:vl-thrust 130ms cubic-bezier(.5,0,.8,.6) calc(var(--tl) + var(--b-plant) - 130ms) both;
  animation: var(--ba);
}
@keyframes vl-thrust {
  0% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-14px);
  }
  100% {
    transform: var(--thrust);
  }
}
.is-victorylap .vl-plant-dust {
  --dust-ms:640ms;
}
.is-victorylap .vl-pole,
.is-victorylap .vl-pennant {
  position: absolute;
  display: block;
  overflow: visible;
}
.is-victorylap .vl-ink {
  fill: var(--ink0);
  stroke: var(--ink0);
  stroke-linejoin: round;
  stroke-linecap: round;
}
.is-victorylap .vl-pole-paint {
  fill: none;
  stroke: var(--bit-wood-lit);
  stroke-linecap: round;
}
.is-victorylap .vl-knob {
  fill: var(--bit-gold);
  stroke: var(--ink0);
}
.is-victorylap .vl-ripple {
  --ba:vl-ripple calc(var(--b-droop) / 6) ease-in-out calc(var(--tl) + 0ms) 6 both;
  animation: var(--ba);
}
@keyframes vl-ripple {
  0%, 100% {
    transform: skewY(0deg) scaleX(1);
  }
  25% {
    transform: skewY(7deg) scaleX(.93);
  }
  50% {
    transform: skewY(-2deg) scaleX(1.03);
  }
  75% {
    transform: skewY(-8deg) scaleX(.95);
  }
}
.is-victorylap .vl-sag {
  transform: skewY(72deg) scaleX(.2);
  --ba:vl-sag 900ms cubic-bezier(.4,0,.6,1) calc(var(--tl) + var(--b-droop)) both;
  animation: var(--ba);
}
@keyframes vl-sag {
  0% {
    transform: skewY(0deg) scaleX(1);
  }
  30% {
    transform: skewY(16deg) scaleX(.84);
  }
  70% {
    transform: skewY(75deg) scaleX(.18);
  }
  85% {
    transform: skewY(68deg) scaleX(.23);
  }
  100% {
    transform: skewY(72deg) scaleX(.2);
  }
}

/* src/features/tv/tv.css */
.tv-stage {
  position: fixed;
  inset: 0;
  z-index: 60;
  overflow: hidden;
  background: var(--night-deep);
}
.tv-canvas {
  position: absolute;
  width: 1920px;
  height: 1080px;
  transform-origin: 0 0;
  display: flex;
  flex-direction: column;
  background: var(--night-deep);
  color: var(--ink);
  overflow: hidden;
  font-family: var(--fd-body);
  --tv-glass:color-mix(in srgb, var(--bg) 80%, var(--paper));
  --tv-glass-deep:color-mix(in srgb, var(--ink0) 86%, var(--bg));
  --tv-edge:64px;
  --tv-safe-y:54px;
  --tv-window:color-mix(in srgb, var(--ink0) 88%, var(--bg));
  --tv-cut:inset 0 3px 0 color-mix(in srgb, var(--ink0) 70%, transparent), inset 0 -1px 0 color-mix(in srgb, var(--bone) 9%, transparent);
  --tv-sheen:linear-gradient(
      112deg,
      transparent 0 64%,
      color-mix(in srgb, var(--bone) 3%, transparent) 64% 71%,
      transparent 71%),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 4%, transparent),
      transparent 34%);
}
.tv-exit {
  position: fixed;
  z-index: 75;
  bottom: calc(8px + env(safe-area-inset-bottom));
  right: 12px;
  min-width: 44px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 10px;
  cursor: pointer;
  background: var(--paper);
  color: var(--ink);
  border: 1.5px solid var(--ghost-line);
  font: 700 15px/1 var(--fd-body);
  letter-spacing: .04em;
  transition: opacity .3s;
}
.tv-exit.is-idle:not(:focus-visible) {
  opacity: 0;
  pointer-events: none;
}
.tv-display {
  font-family: var(--fd-display);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .01em;
}
.tv-label {
  font: 700 28px/1.15 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted2);
}
.tv-unit {
  margin-left: .18em;
  font: 700 24px/1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: none;
  color: var(--muted2);
}
.tv-body {
  font: 600 40px/1.3 var(--fd-body);
  color: var(--muted2);
}
.tv-title {
  font-size: 56px;
  line-height: 1.1;
  color: var(--bone);
}
.tv-glass {
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: var(--glass-edge), var(--shadow-2);
}
.tv-sign {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 12px 26px;
  border-radius: 14px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
}
.tv-faces {
  display: flex;
  flex-wrap: nowrap;
  gap: 8px;
  flex-shrink: 0;
}
.tv-faces.is-overlap {
  gap: 0;
}
.tv-faces.is-overlap > * + * {
  margin-left: var(--overlap, -12px);
}
.tv-mast {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 24px;
  height: var(--tv-mast-h, 124px);
  flex-shrink: 0;
  padding: var(--tv-safe-y) var(--tv-edge) 0;
}
.tv-mast-plate,
.tv-mast-right {
  display: flex;
  align-items: center;
  gap: 22px;
  min-width: 0;
  height: 64px;
  padding: 0 26px 0 8px;
  border-radius: 99px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
}
.tv-mast-right {
  padding: 0 28px;
  flex-shrink: 0;
  margin-left: auto;
}
.tv-mast > .tv-now + .tv-mast-right {
  margin-left: 0;
}
.tv-mast-right:has(.tv-dock) {
  padding: 0 8px;
  background: none;
  border: 0;
  box-shadow: none;
}
.tv-mast-title {
  font-size: 52px;
  line-height: 1.15;
  color: var(--bone);
  white-space: nowrap;
}
.tv-mast-event {
  font-size: 52px;
  line-height: 1.15;
  color: var(--bone);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.tv-mast-edition {
  font: 700 28px/1 var(--fd-display);
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted2);
  white-space: nowrap;
}
.tv-mast:has(.tv-now) .tv-mast-right:has(> .tv-mast-edition) {
  display: none;
}
.tv-status {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  font: 800 32px/1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted2);
  white-space: nowrap;
}
.tv-status i {
  width: 16px;
  height: 16px;
  border-radius: 99px;
  background: var(--muted);
  flex-shrink: 0;
}
.tv-status .fd-insert {
  --lamp:var(--lamp-live);
  background: var(--lamp-live);
}
.tv-status.is-live,
.tv-status.is-pending {
  color: var(--muted2);
}
.tv-status.is-live i {
  background: var(--lamp-live);
  animation: fd-beat-dot var(--motion-beat) ease-in-out infinite;
}
.tv-status.is-final {
  color: var(--bone);
}
.tv-status.is-next .fd-insert {
  --lamp:var(--lamp-info);
  background: var(--lamp-info);
}
.tv-status.is-offline {
  color: var(--clay-text);
}
.tv-status.is-offline i {
  background: transparent;
  box-shadow: inset 0 0 0 3px var(--clay);
}
.fd-beat-dot.tv-beat {
  width: 16px;
  height: 16px;
  margin-right: 14px;
  vertical-align: .12em;
}
.tv-dock {
  min-width: 0;
  display: flex;
  justify-content: flex-end;
}
.tv-main {
  position: relative;
  z-index: 2;
  flex: 1;
  min-height: 0;
  display: flex;
}
.tv-pane {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: 16px var(--tv-edge) 20px;
  animation: si-fade .5s ease-out;
}
.tv-center {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.tv-ticker {
  position: relative;
  z-index: 3;
  height: var(--tv-foot-h, 120px);
  flex-shrink: 0;
}
.tv-ticker-glass,
.tv-ticker-page {
  position: absolute;
  left: var(--tv-edge);
  right: var(--tv-edge);
  top: 6px;
  height: 60px;
}
.tv-ticker-glass {
  border-radius: 14px;
  background: var(--tv-sheen), var(--tv-glass-deep);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge), var(--shadow-2);
}
.tv-ticker-page {
  display: flex;
  align-items: center;
  padding: 0 30px;
}
.tv-ticker-page.is-solo {
  justify-content: center;
}
.tv-ticker-page.is-pair {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}
.tv-ticker-page.is-pair > .tv-ticker-item:first-child {
  padding-right: 36px;
}
.tv-ticker-page.is-pair > .tv-ticker-item + .tv-ticker-item {
  padding-left: 36px;
  border-left: 1px solid var(--bone-line);
}
.tv-ticker-item {
  display: flex;
  align-items: center;
  gap: 20px;
  height: 100%;
  min-width: 0;
  overflow: hidden;
}
.tv-ticker-page.is-entering {
  animation: tv-tick-in .7s ease-out both;
}
.tv-ticker-page.is-leaving {
  animation: tv-tick-out .7s ease-in both;
}
@keyframes tv-tick-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-tick-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translateY(-12px);
  }
}
.tv-ticker-tag {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 22px;
  font: 700 26px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
}
.tv-ticker-tag::after {
  content: "";
  width: 1px;
  height: 30px;
  background: var(--bone-line);
}
.tv-ticker-item .tv-faces {
  gap: 8px;
}
.tv-ticker-text {
  min-width: 0;
  font: 600 34px/1.35 var(--fd-body);
  color: var(--bone);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-ticker-text.has-ladder {
  display: inline-flex;
  align-items: center;
  gap: 24px;
  overflow: visible;
}
.tv-ticker-amount {
  font: 800 40px/1 var(--fd-display);
  letter-spacing: .01em;
  font-variant-numeric: tabular-nums;
  color: var(--sun);
}
.tv-ticker-amount.is-won {
  color: var(--green);
}
.tv-ticker-amount.is-loss {
  color: var(--clay-text);
}
.tv-ticker.is-cut .tv-ticker-page {
  animation: none;
}
.tv-now {
  position: relative;
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
  max-width: 640px;
  height: 68px;
  margin-top: -2px;
  padding: 0 30px 0 8px;
  border-radius: 99px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
  overflow: hidden;
  animation: si-flag .55s ease-out both;
}
.tv-now-art {
  position: relative;
  flex-shrink: 0;
  display: grid;
  place-items: center;
}
.tv-now.has-art .tv-now-art {
  width: 62px;
  height: 52px;
  place-items: start;
}
.tv-now-art img {
  width: 50px;
  height: 50px;
  display: block;
  border-radius: 99px;
  object-fit: cover;
  border: 1px solid var(--ghost-line);
  animation: tv-now-art .7s cubic-bezier(.2, .75, .2, 1) both;
}
.tv-now.has-art .tv-now-chip {
  position: absolute;
  right: -2px;
  bottom: -4px;
  animation: tv-now-chip .5s cubic-bezier(.2, .8, .2, 1) .35s both;
}
.tv-now-text {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.tv-now-line {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.tv-now-name {
  min-width: 0;
  font-size: 28px;
  line-height: 1.15;
  color: var(--bone);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: none;
}
.tv-now-track {
  font: 600 24px/1.25 var(--fd-body);
  color: var(--muted2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tv-now-track b {
  color: var(--bone);
  font-weight: 700;
}
.tv-now-artist {
  margin-left: 16px;
}
.tv-now .tv-now-label {
  font-size: 24px;
  line-height: 1.2;
}
.tv-now-bar {
  position: absolute;
  left: 30px;
  right: 30px;
  bottom: 0;
  height: 3px;
  border-radius: 99px;
  background: var(--muted);
  transform-origin: left;
  animation-name: tv-now-bar;
  animation-timing-function: linear;
  animation-fill-mode: both;
}
@keyframes tv-now-bar {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}
@keyframes tv-now-art {
  from {
    opacity: 0;
    transform: scale(.86) rotate(-4deg);
  }
