    opacity: 0;
  }
}
.bit-words {
  position: absolute;
  top: calc(var(--tv-safe-y, 54px) + 4px);
  display: flex;
  flex-direction: column;
}
.bit-words.is-top {
  left: 120px;
  right: 120px;
  align-items: center;
  text-align: center;
}
.bit-words.is-top-left {
  left: calc(var(--tv-edge, 64px) + 8px);
  max-width: 900px;
  align-items: flex-start;
  text-align: left;
}
.bit-words.is-top-right {
  right: calc(var(--tv-edge, 64px) + 8px);
  max-width: 900px;
  align-items: flex-end;
  text-align: right;
}
.bit-words.is-top-left .bit-letter {
  transform-origin: 0 70%;
}
.bit-words.is-top-right .bit-letter {
  transform-origin: 100% 70%;
}
.bit-letter {
  display: block;
  max-width: 100%;
  white-space: nowrap;
  line-height: 1.15;
  color: var(--bone);
  font-family: var(--fd-show);
  font-weight: 900;
  letter-spacing: .01em;
  transform-origin: 50% 70%;
  text-shadow:
    4px 0 0 var(--ink0),
    -4px 0 0 var(--ink0),
    0 4px 0 var(--ink0),
    0 -4px 0 var(--ink0),
    3px 3px 0 var(--ink0),
    -3px 3px 0 var(--ink0),
    3px -3px 0 var(--ink0),
    -3px -3px 0 var(--ink0),
    0 9px 0 var(--ink0),
    0 0 34px color-mix(in srgb, var(--bit-lamp, var(--sun)) 72%, transparent);
  --ba:bit-stamp 360ms var(--ease-land) calc(var(--tl) + var(--b-letter) + var(--d, 0ms)) both;
  animation: var(--ba);
}
.bit-letter.is-fact {
  --d:110ms;
  font-size: 78px;
  font-variant-numeric: tabular-nums;
}
.bit-letter.is-fact.is-loss {
  color: var(--clay-text);
}
@keyframes bit-stamp {
  0% {
    opacity: 0;
    transform: scale(1.7) rotate(-5deg);
  }
  62% {
    opacity: 1;
    transform: scale(.95) rotate(1deg);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes bit-show {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes bit-hide {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes bit-shake {
  0%, 100% {
    transform: none;
  }
  20% {
    transform: translate(-9px, 4px);
  }
  40% {
    transform: translate(8px, -5px);
  }
  60% {
    transform: translate(-5px, 3px);
  }
  80% {
    transform: translate(3px, -1px);
  }
}
@keyframes bit-shake-big {
  0%, 100% {
    transform: none;
  }
  14% {
    transform: translate(-24px, 12px) rotate(-.7deg);
  }
  30% {
    transform: translate(20px, -14px) rotate(.6deg);
  }
  48% {
    transform: translate(-13px, 8px) rotate(-.3deg);
  }
  66% {
    transform: translate(9px, -5px);
  }
  84% {
    transform: translate(-4px, 2px);
  }
}

/* src/features/gags/phone-bit.css */
.fd-moment.fd-bit {
  padding-left: 0;
  padding-right: 0;
