}
.fd-bit-screen {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--ink0);
  box-shadow: 0 -2px 0 color-mix(in srgb, var(--bit-lamp, var(--sun)) 70%, transparent), 0 2px 0 color-mix(in srgb, var(--bit-lamp, var(--sun)) 70%, transparent);
}
.fd-bit-screen > .bit-stage {
  position: absolute;
  inset: 0;
}
.fd-bit-words {
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 0 20px;
  text-align: center;
}
.fd-bit-name,
.fd-bit-fact {
  margin: 0;
  max-width: 100%;
  font-family: var(--fd-show);
  font-weight: 900;
  color: var(--bone);
  letter-spacing: .01em;
  transform-origin: 50% 70%;
  text-shadow:
    2px 0 0 var(--ink0),
    -2px 0 0 var(--ink0),
    0 2px 0 var(--ink0),
    0 -2px 0 var(--ink0),
    0 4px 0 var(--ink0),
    0 0 18px color-mix(in srgb, var(--bit-lamp, var(--sun)) 60%, transparent);
  --ba:bit-stamp 360ms var(--ease-land) calc(var(--tl) + var(--b-letter) + var(--d, 0ms)) both;
  animation: var(--ba);
}
.fd-bit-name {
  line-height: 1.08;
}
.fd-bit-name > span {
  display: block;
  white-space: nowrap;
}
.fd-bit-fact {
  --d:110ms;
  font-size: 40px;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.fd-bit-fact.is-loss {
  color: var(--clay-text);
}

/* src/features/moments/sky.css */
.fd-sky {
  --star-size:min(20px, calc((100vw - 36px) / var(--sky-n, 12) * .62));
  position: relative;
  margin: 4px -14px 0 -18px;
  padding: 4px 18px 5px;
  background:
    linear-gradient(
      to bottom,
      transparent,
      color-mix(in srgb, var(--night-deep, var(--bg)) 55%, transparent));
}
.fd-sky-hit {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.fd-sky-hit:active {
  transform: none;
}
.fd-sky-row {
  position: relative;
  height: 42px;
}
.fd-sky-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}
.fd-sky-thread {
  stroke: var(--line);
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}
.fd-sky-line {
  fill: none;
  stroke: var(--bone);
  stroke-width: 1.5px;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 0;
  animation: fd-sky-line 600ms var(--ease-out) backwards;
}
@keyframes fd-sky-line {
  from {
    stroke-dashoffset: 100;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.fd-sky-star {
  position: absolute;
  top: 62%;
  z-index: 1;
  width: var(--star-size);
  height: var(--star-size);
  margin: calc(var(--star-size) / -2) 0 0 calc(var(--star-size) / -2);
  pointer-events: none;
}
.fd-sky-star svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.fd-sky-star polygon {
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
}
.fd-sky-game {
  display: grid;
  place-items: center;
}
.fd-sky-game > svg,
.fd-sky-game > span {
  width: 100%;
  height: 100%;
}
.fd-sky-game.is-open {
  opacity: .55;
  filter: saturate(.4);
}
.fd-sky-ring {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  box-shadow: var(--live-bloom);
}
.fd-sky-star.is-lit polygon {
  fill: var(--star, var(--muted2));
  stroke: color-mix(in srgb, var(--bone) 40%, transparent);
  stroke-width: 1px;
}
.fd-sky-star.is-champ svg {
  transform: scale(1.3);
}
.fd-sky-star.is-fresh svg {
  animation: fd-sky-pop 620ms var(--ease-land) 200ms backwards;
}
@keyframes fd-sky-pop {
  0% {
    opacity: 0;
    transform: scale(0) rotate(-90deg);
  }
  70% {
    opacity: 1;
    transform: scale(1.5) rotate(10deg);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
.fd-sky-reading {
  width: 100%;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  animation: fd-sky-reading 200ms var(--ease-out) backwards;
}
.fd-sky-reading:active {
  transform: none;
}
@keyframes fd-sky-reading {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}
.fd-sky-reading-text {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 1px;
}
.fd-sky-reading-event {
  font-size: 15px;
  line-height: 1.2;
  letter-spacing: .02em;
  color: var(--ink);
}
.fd-sky-reading-text b {
  font: 700 15px/1.25 var(--fd-body);
  color: var(--ink);
}
.fd-sky-reading-chips {
  flex-shrink: 0;
  display: flex;
  align-items: center;
}
.fd-sky-reading-chips {
  gap: 2px;
}
.fd-sky-reading-chips i {
  margin-left: 6px;
  font: 800 14px/1 var(--fd-display);
  font-style: normal;
  color: var(--muted2);
}
.fd-sky-star.is-lit {
  display: grid;
  place-items: center;
}
.fd-sky-face {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  line-height: 0;
  border-radius: 50%;
  box-shadow: 0 0 0 1.5px var(--star, var(--muted2)), 0 0 0 3px var(--ink0);
}
.fd-sky-face img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.fd-sky-star.is-lit .fd-sky-badge {
  position: absolute;
  right: -5px;
  top: -5px;
  width: 10px;
  height: 10px;
}
.fd-sky-star.is-champ .fd-sky-face {
  box-shadow: 0 0 0 2px var(--sun), 0 0 8px color-mix(in srgb, var(--sun) 60%, transparent);
}
.fd-sky-star.is-champ svg {
  transform: none;
}
.fd-sky-star.is-fresh .fd-sky-face {
  animation: fd-sky-pop 620ms var(--ease-land) 200ms backwards;
}
.fd-sky-cue {
  position: absolute;
  top: 0;
  display: flex;
  align-items: center;
  gap: 2px;
  max-width: 60%;
  pointer-events: none;
  white-space: nowrap;
  color: var(--ink);
  font: 800 12px/14px var(--fd-show);
  letter-spacing: .03em;
}
.fd-sky-cue {
  top: 4px;
  text-align: left;
}
.fd-sky-cue.is-start {
  left: max(6px, calc(18px + (100% - 36px) * var(--x) - 12px));
}
.fd-sky-cue.is-mid {
  left: calc(18px + (100% - 36px) * var(--x));
  transform: translateX(-50%);
}
.fd-sky-cue.is-end {
  right: max(6px, calc(18px + (100% - 36px) * (1 - var(--x)) - 12px));
}
.fd-sky-cue.is-live .fd-sky-cue-name {
  color: var(--ink);
  text-shadow: 0 0 8px color-mix(in srgb, var(--lamp-live) 70%, transparent);
}
.fd-sky-cue:not(.is-live) .fd-sky-cue-name {
  color: var(--muted2);
}
.fd-sky-cue-name {
  min-width: 0;
}
.fd-sky-cue-go {
  flex: none;
  color: var(--lamp-info);
}

/* src/features/duels/quickdraw.css */
.fd-qd {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow-y: auto;
  background: var(--bg);
  color: var(--ink);
  text-align: center;
  overscroll-behavior: contain;
}
.fd-qd-scene {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  min-height: clamp(330px, 54svh, 460px);
  padding: calc(env(safe-area-inset-top) + 20px) 12px 16px;
}
.fd-qd-title {
  --lamp:var(--lamp-live);
  margin: 0;
  font-size: 40px;
  line-height: 1.15;
}
.fd-qd-ring {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: start;
  gap: 4px;
}
.fd-qd-side {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 0;
  animation: fd-qd-in-left 420ms var(--ease-out) both;
}
.fd-qd-side.is-right {
  animation-name: fd-qd-in-right;
}
@keyframes fd-qd-in-left {
  from {
    opacity: 0;
    transform: translateX(-36px);
  }
}
@keyframes fd-qd-in-right {
  from {
    opacity: 0;
    transform: translateX(36px);
  }
}
.fd-qd-chip {
  position: relative;
  line-height: 0;
  transition: opacity .5s var(--ease-out);
}
.fd-qd-side.is-lost .fd-qd-chip {
  opacity: .6;
}
.fd-qd-name {
  max-width: 100%;
  font-size: 24px;
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.fd-qd-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 46px;
}
.fd-qd-lamp {
  width: 16px;
  height: 16px;
}
.fd-qd-lamp.is-live {
  --lamp:var(--lamp-live);
}
.fd-qd-lamp.is-you {
  --lamp:var(--you);
}
.fd-qd-time {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  padding: 5px 8px 4px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--ink0) 88%, transparent);
  box-shadow: var(--window-bezel);
  color: var(--bone);
  font: 800 26px/1 var(--fd-display);
}
.fd-qd-time.is-you {
  font-size: 30px;
}
.fd-qd-time small {
  color: var(--muted2);
  font: 700 13px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
}
.fd-qd-foul {
  padding: 6px 10px 5px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--ink0) 88%, transparent);
  color: var(--clay-text);
  font: 900 26px/1.1 var(--fd-show);
}
.fd-qd-stamp {
  position: absolute;
  left: 50%;
  top: 4px;
  z-index: 2;
  padding: 4px 10px 3px;
  border: 3px solid var(--sun);
  border-radius: 8px;
  background: color-mix(in srgb, var(--ink0) 72%, transparent);
  color: var(--sun);
  font-size: 28px;
  line-height: 1;
  letter-spacing: .04em;
  white-space: nowrap;
  transform: translate(-50%, -50%) rotate(-8deg);
  animation: fd-qd-stamp var(--motion-stamp) var(--ease-land) both;
}
.fd-qd-stamp.is-tie {
  border-color: var(--bone);
  color: var(--bone);
}
@keyframes fd-qd-stamp {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) rotate(-8deg) scale(1.9);
  }
  70% {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-8deg) scale(.94);
  }
}
.fd-qd-antes {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  min-height: 88px;
  padding: 0 2px;
}
.fd-qd-ante {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}
.fd-qd-ante small {
  color: var(--sun);
  font: 800 15px/1.15 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-qd-ante.is-empty i {
  display: block;
  width: 30px;
  height: 14px;
  margin-bottom: 22px;
  border: 1.5px dashed var(--ghost-line);
  border-radius: 50%;
}
.fd-qd-antes.is-to-left .fd-qd-ante,
.fd-qd-antes.is-to-right .fd-qd-ante {
  opacity: 0;
  animation: fd-qd-take-left var(--slide-ms, 650ms) var(--ease-exit) var(--slide-at, 0ms) both;
}
.fd-qd-antes.is-to-right .fd-qd-ante {
  animation-name: fd-qd-take-right;
}
@keyframes fd-qd-take-left {
  from {
    opacity: 1;
    transform: none;
  }
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translate(-96px, -30px) scale(.55);
  }
}
@keyframes fd-qd-take-right {
  from {
    opacity: 1;
    transform: none;
  }
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translate(96px, -30px) scale(.55);
  }
}
.fd-qd-drain {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: var(--lamp-info);
  transform-origin: left center;
  transform: scaleX(0);
  animation: fd-qd-drain var(--drain-ms) linear both;
}
@keyframes fd-qd-drain {
  from {
    transform: scaleX(var(--drain-left, 1));
  }
  to {
    transform: scaleX(0);
  }
}
.fd-qd-deck {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 20px 20px calc(env(safe-area-inset-bottom) + 20px);
}
.fd-qd-line {
  max-width: 340px;
  margin: 0;
  color: var(--muted2);
  font: 400 15px/1.5 var(--fd-body);
}
.fd-qd-line.is-strong {
  color: var(--ink);
  font-size: 17px;
  font-weight: 600;
}
.fd-qd-line.is-error {
  color: var(--clay-text);
  font-weight: 600;
}
.fd-qd-state {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  color: var(--muted2);
  font: 800 20px/1.1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-qd-state .fd-qd-lamp {
  --lamp:var(--muted);
}
.fd-qd-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
}
.fd-qd-failed {
  display: grid;
  justify-items: center;
  gap: 10px;
  width: 100%;
}
.fd-qd-quiet {
  min-height: 44px;
  padding: 0 16px;
  border: 0;
  background: none;
  color: var(--lamp-info);
  font: 600 15px/1 var(--fd-body);
  cursor: pointer;
}
.fd-qd-quiet:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
  border-radius: 6px;
}
.fd-qd-delta {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font: 800 48px/1 var(--fd-display);
  animation: fd-qd-rise 420ms var(--ease-out) both;
}
.fd-qd-delta.is-up {
  color: var(--green);
}
.fd-qd-delta.is-down {
  color: var(--clay-text);
}
.fd-qd-delta.is-down .fd-reel {
  color: var(--clay-text);
  --reel-tint:var(--clay);
  --reel-mix:8%;
}
@keyframes fd-qd-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.fd-qd.is-over .fd-qd-ring {
  opacity: .55;
}
.fd-qd.is-armed .fd-qd-title {
  opacity: .55;
}
.fd-qd-count {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 26px;
  min-height: 120px;
}
.fd-qd-count-lamp {
  width: 34px;
  height: 34px;
  --lamp:var(--lamp-live);
  box-shadow: var(--lens-rim), 0 0 22px 4px color-mix(in srgb, var(--lamp-on) 55%, transparent);
  animation: fd-qd-lamp-on 90ms steps(1, start) both;
}
@keyframes fd-qd-lamp-on {
  from {
    background: var(--lens-off);
    box-shadow: var(--lens-rim);
  }
  to {
    background: var(--lens-lit);
  }
}
.fd-qd.is-armed {
  touch-action: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}
.fd-qd-run {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
}
.fd-qd-run.is-go {
  background: var(--lamp-live);
}
.fd-qd-go {
  color: var(--ink0);
  font-size: clamp(112px, 36vw, 176px);
  line-height: 1.15;
}
@media (prefers-reduced-motion: reduce) {
  .fd-qd-side,
  .fd-qd-stamp,
  .fd-qd-antes .fd-qd-ante,
  .fd-qd-delta,
  .fd-qd-count-lamp,
  .fd-qd-drain {
    animation: none;
  }
  .fd-qd-drain {
    transform: scaleX(var(--drain-left, 1));
  }
}

/* src/features/director/run-of-show.css */
.fd-runshow {
  width: 100%;
  border: 1px solid var(--bone-line);
  border-radius: 14px;
  background: var(--night);
  color: var(--bone);
