  gap: 2px;
}
.fd-stack-row b {
  font: 600 14px/1.2 var(--fd-body);
  color: var(--ink);
  overflow-wrap: anywhere;
}
.fd-stack-row small {
  font: 500 12px/1.3 var(--fd-body);
  color: var(--muted);
}
.fd-stack-row small.is-grant {
  color: var(--live2);
}
.fd-stack-row strong {
  font: 700 19px/1 var(--fd-display);
  color: var(--ink);
  min-width: 56px;
  text-align: right;
}
.fd-stack-row > span.fd-stack-total {
  flex: 0 0 auto;
  align-items: flex-end;
  gap: 4px;
}
.fd-stack-row > span > .fd-poker-stacks {
  margin-top: 4px;
}
.fd-stack-tray {
  display: grid;
  gap: 10px;
  margin: 14px 0 4px;
  padding: 12px;
  border-radius: 10px;
  background: var(--bg);
  border: 1px solid var(--night-line);
  font: 600 12.5px/1.4 var(--fd-body);
  color: var(--muted2);
}
.fd-stack-summary {
  display: grid;
  gap: 6px;
  margin: 12px 0 14px;
  font: 600 12.5px/1.4 var(--fd-body);
  color: var(--muted2);
}
.fd-stack-summary div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.fd-stack-summary strong {
  color: var(--ink);
}
.fd-stack-summary .fd-stack-grants {
  display: flex;
  align-items: center;
  gap: 4px;
}
.fd-sheet-header:has(> .fd-sheet-dock:not(:empty)) {
  flex-wrap: wrap;
  row-gap: 4px;
}
.fd-sheet-dock {
  order: 1;
  flex: 1 0 100%;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 6px;
}
.fd-sheet-dock:empty {
  display: none;
}

/* src/features/roster/roster.css */
.fd-roster-count {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 2px 0 14px;
}
.fd-roster-count strong {
  font: 900 44px/1 var(--fd-display);
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.fd-roster-count span {
  font: 700 15px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--night-text);
}
.fd-roster {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}
.fd-roster-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 10px;
  row-gap: 6px;
  min-height: 56px;
  padding: 6px 0;
  border-bottom: 1px solid var(--line);
}
.fd-roster-row:last-child {
  border-bottom: 0;
}
.fd-roster-who {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.fd-roster-face {
  display: inline-flex;
  border-radius: 50%;
  transition: filter var(--motion-base, 220ms) var(--ease-out, ease-out), opacity var(--motion-base, 220ms) var(--ease-out, ease-out);
}
.fd-roster-name {
  min-width: 0;
  overflow-wrap: anywhere;
  font: 700 16px/1.15 var(--fd-body);
  color: var(--bone);
}
.fd-roster-row.is-away .fd-roster-name {
  color: var(--muted2);
}
.fd-roster-row.is-out .fd-roster-face {
  filter: grayscale(1);
  opacity: .42;
}
.fd-roster-row.is-out .fd-roster-name {
  color: var(--muted);
  text-decoration: line-through;
  text-decoration-thickness: 2px;
  text-decoration-color: color-mix(in srgb, var(--muted) 70%, transparent);
}
.fd-roster-switch {
  display: inline-grid;
  grid-template-columns: repeat(3, auto);
  padding: 3px;
  gap: 2px;
  border: 1px solid var(--bone-line);
  border-radius: 10px;
  background: var(--ink0);
}
.fd-roster-switch button {
  min-width: 52px;
  min-height: 44px;
  padding: 0 9px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--night-text);
  font: 700 13px/1 var(--fd-body);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--motion-fast, 160ms) var(--ease-out, ease-out), color var(--motion-fast, 160ms) var(--ease-out, ease-out);
}
.fd-roster-switch button:disabled {
  cursor: default;
}
.fd-roster-switch button[aria-checked=true] {
  color: var(--ink0);
}
.fd-roster-row.is-here .fd-roster-switch button[aria-checked=true] {
  background: var(--lamp-info);
}
.fd-roster-row.is-away .fd-roster-switch button[aria-checked=true] {
  background: var(--sun);
}
.fd-roster-row.is-out .fd-roster-switch button[aria-checked=true] {
  background: var(--paper2);
  color: var(--bone);
  box-shadow: inset 0 0 0 1px var(--bone-line);
}
.fd-roster-row.is-pending .fd-roster-switch {
  opacity: .7;
}
.fd-roster-error {
  grid-column: 1 / -1;
  margin: 0;
  font: 600 13px/1.35 var(--fd-body);
  color: var(--clay-text);
}
.fd-roster-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  margin: 2px 0 14px;
}
.fd-roster-head .fd-roster-count {
  margin: 0;
}
.fd-roster-door {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 6px 10px;
  min-width: 0;
}
.fd-roster-door-count {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.fd-roster-door-count .fd-insert {
  --lamp:var(--lamp-info);
}
.fd-roster-door-count span {
  font: 700 14px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--night-text);
}
.fd-roster-door-count strong {
  font: 800 20px/1 var(--fd-display);
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.fd-roster-door-link {
  min-height: 44px;
  padding: 0 6px;
  border: 0;
  background: none;
  color: var(--lamp-info);
  font: 600 14px/1 var(--fd-body);
  cursor: pointer;
}
.fd-roster-door-link:disabled {
  opacity: .5;
  cursor: default;
}
.fd-roster-door .fd-roster-error {
  flex-basis: 100%;
  text-align: right;
}
.fd-roster-row.is-road .fd-roster-face {
  filter: grayscale(1);
  opacity: .62;
  outline: 1.5px dashed var(--ghost-line);
  outline-offset: 2px;
}
.fd-roster-row.is-road .fd-roster-name {
  color: var(--muted2);
}
.fd-roster-arrive {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-left: 66px;
}
.fd-roster-arrive-word {
  font: 700 13px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--lamp-info);
}
@media (max-width: 360px) {
  .fd-roster-switch button {
    min-width: 46px;
    padding: 0 7px;
    font-size: 12px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-roster-face,
  .fd-roster-switch button {
    transition: none;
  }
}

/* src/features/director/crew-check.css */
.fd-crew-shape {
  margin: 0 0 12px;
  font: 800 17px/1.15 var(--fd-show);
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--ink);
}
.fd-crew-grid {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px 6px;
}
.fd-crew-seat {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
}
.fd-crew-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  width: 100%;
  min-height: 44px;
  padding: 4px 2px 6px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: none;
  color: var(--ink);
  cursor: pointer;
  transition: background-color .16s, border-color .16s;
}
.fd-crew-chip:disabled {
  cursor: default;
}
.fd-crew-chip:not(:disabled):active {
  background: var(--ink-tint);
}
.fd-crew-seat.is-open .fd-crew-chip {
  border-color: var(--bone-line);
  background: var(--paper2);
}
.fd-crew-face {
  position: relative;
  display: block;
  border-radius: 50%;
  line-height: 0;
  transition:
    filter .18s,
    opacity .18s,
    box-shadow .18s;
}
.fd-crew-name {
  max-width: 100%;
  min-height: 2.3em;
  font: 700 13px/1.15 var(--fd-body);
  color: var(--ink);
  text-align: center;
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.fd-crew-tag {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin-top: -2px;
  padding: 0 6px;
  border-radius: 6px;
  white-space: nowrap;
  font: 800 13px/1 var(--fd-show);
  letter-spacing: .03em;
  text-transform: uppercase;
}
.fd-crew-tag.is-crew {
  border: 1px solid color-mix(in srgb, var(--lamp-info) 55%, transparent);
  background: color-mix(in srgb, var(--lamp-info) 12%, var(--paper));
  color: var(--lamp-info);
}
.fd-crew-tag.is-out {
  border: 1px dashed var(--ghost-line);
  color: var(--muted2);
}
.fd-crew-tag.is-auto {
  gap: 3px;
  padding-left: 4px;
  border-style: dashed;
}
.fd-crew-tag.is-auto svg {
  flex: 0 0 auto;
}
.fd-crew-seat.is-crew .fd-crew-face {
  box-shadow: 0 0 0 2px var(--lamp-info), 0 0 14px color-mix(in srgb, var(--lamp-info) 45%, transparent);
}
.fd-crew-seat.is-out .fd-crew-face {
  opacity: .5;
}
.fd-crew-seat.is-out .fd-crew-face::before {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px dashed var(--muted2);
  pointer-events: none;
}
.fd-crew-seat.is-out .fd-crew-name {
  color: var(--muted2);
}
.fd-crew-seat.is-away .fd-crew-face {
  filter: grayscale(1);
  opacity: .38;
}
.fd-crew-seat.is-away .fd-crew-face::after {
  content: "";
  position: absolute;
  left: -4px;
  right: -4px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: 99px;
  background: var(--muted);
  transform: rotate(-38deg);
}
.fd-crew-seat.is-away .fd-crew-name {
  color: var(--muted);
  text-decoration: line-through;
}
.fd-crew-seat.is-road .fd-crew-face {
  filter: grayscale(1);
  opacity: .42;
}
.fd-crew-seat.is-road .fd-crew-face::before {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px dashed var(--ghost-line);
  pointer-events: none;
}
.fd-crew-seat.is-road .fd-crew-name {
  color: var(--muted2);
}
.fd-crew-tag.is-road {
  border: 1px dashed var(--ghost-line);
  color: var(--muted2);
}
.fd-crew-seat.is-pending .fd-crew-face {
  animation: fd-crew-wait 1.2s steps(1, end) infinite;
}
@keyframes fd-crew-wait {
  50% {
    opacity: .55;
  }
}
.fd-crew-choice {
  position: relative;
  grid-column: 1 / -1;
  display: grid;
  gap: 8px;
  margin: -4px 0 2px;
  padding: 8px;
  border: 1px solid var(--bone-line);
  border-radius: 12px;
  background: var(--paper2);
  box-shadow: var(--glass-edge), var(--shadow-1);
  animation: fd-crew-choice-in var(--motion-stamp, 320ms) var(--ease-out, ease-out) both;
}
.fd-crew-choice::before {
  content: "";
  position: absolute;
  top: -7px;
  left: var(--caret, 50%);
  width: 12px;
  height: 12px;
  margin-left: -6px;
  border-left: 1px solid var(--bone-line);
  border-top: 1px solid var(--bone-line);
  background: var(--paper2);
  transform: rotate(45deg);
}
@keyframes fd-crew-choice-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
}
.fd-crew-choice-row {
  display: flex;
  align-items: stretch;
  gap: 10px;
}
.fd-crew-choice-states {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-auto-columns: minmax(0, 1fr);
  grid-auto-flow: column;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  overflow: hidden;
}
.fd-crew-choice-away {
  flex: 0 0 76px;
  display: grid;
}
.fd-crew-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  min-height: 52px;
  padding: 7px 4px 6px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--muted2);
  cursor: pointer;
  font: 800 14px/1 var(--fd-show);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.fd-crew-choice-states .fd-crew-option + .fd-crew-option {
  border-left: 1px solid var(--line);
}
.fd-crew-choice-away .fd-crew-option {
  border: 1px dashed var(--ghost-line);
  border-radius: 10px;
}
.fd-crew-option > span {
  white-space: nowrap;
}
.fd-crew-option:disabled {
  cursor: default;
  opacity: .6;
}
.fd-crew-option:not(:disabled):active {
  filter: brightness(1.15);
}
.fd-crew-lens {
  position: relative;
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  flex-shrink: 0;
}
.fd-crew-option.is-playing .fd-crew-lens {
  background: var(--muted2);
  box-shadow: inset 0 0 0 2px var(--paper);
  border: 1px solid var(--muted2);
}
.fd-crew-option.is-crew .fd-crew-lens {
  background: var(--lamp-info);
  box-shadow:
    0 0 0 2px var(--paper),
    0 0 0 3.5px var(--lamp-info),
    0 0 10px color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-crew-option.is-out .fd-crew-lens {
  border: 2px dashed var(--muted2);
}
.fd-crew-option.is-away .fd-crew-lens {
  background: var(--lens-spent, var(--paper2));
  border: 1px solid var(--muted);
}
.fd-crew-option.is-here {
  color: var(--lamp-info);
}
.fd-crew-option.is-here .fd-crew-lens {
  background: var(--lamp-info);
  box-shadow: 0 0 10px color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-crew-option.is-here:not(.is-on) .fd-crew-lens {
  opacity: 1;
  filter: none;
}
.fd-crew-option.is-away .fd-crew-lens::after {
  content: "";
  position: absolute;
  left: -3px;
  right: -3px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: 99px;
  background: var(--muted);
  transform: rotate(-38deg);
}
.fd-crew-option:not(.is-on) .fd-crew-lens {
  opacity: .45;
  filter: saturate(.5);
}
.fd-crew-option.is-on {
  color: var(--ink);
  border-color: color-mix(in srgb, var(--bone) 70%, transparent);
  background: color-mix(in srgb, var(--bone) 13%, var(--paper));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bone) 25%, transparent);
}
.fd-crew-option.is-crew.is-on {
  border-color: color-mix(in srgb, var(--lamp-info) 70%, transparent);
  background: color-mix(in srgb, var(--lamp-info) 14%, var(--paper));
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--lamp-info) 60%, transparent);
}
.fd-crew-choice-away .fd-crew-option.is-on {
  border-style: solid;
}
.fd-crew-option.is-playing.is-on .fd-crew-lens {
  background: var(--bone);
  border-color: var(--bone);
}
.fd-crew-choice-roles {
  display: flex;
  padding-top: 8px;
  border-top: 1px solid var(--night-line);
}
.fd-crew-role-cycle {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 0 12px 0 14px;
  border-radius: 10px;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--lamp-info) 60%, transparent);
  background: color-mix(in srgb, var(--lamp-info) 12%, var(--paper));
  color: var(--lamp-info);
  font: 800 15px/1 var(--fd-show);
  letter-spacing: .03em;
  text-transform: uppercase;
  white-space: nowrap;
}
.fd-crew-role-name {
  flex: 1;
  min-width: 0;
  text-align: left;
  overflow-wrap: anywhere;
  white-space: normal;
}
.fd-crew-role-lamps {
  display: flex;
  align-items: center;
  gap: 5px;
}
.fd-crew-role-lamps i {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 99px;
  border: 1px solid color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-crew-role-lamps i.is-on {
  background: var(--lamp-info);
  border-color: var(--lamp-info);
  box-shadow: 0 0 6px color-mix(in srgb, var(--lamp-info) 60%, transparent);
}
.fd-crew-role-cycle:not(:disabled):active {
  filter: brightness(1.15);
}
.fd-crew-role-cycle:disabled {
  cursor: default;
  opacity: .6;
}
.fd-crew-check button:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-crew-error {
  margin: 0 0 10px;
  color: var(--clay-text);
  font-size: 13px;
}
.fd-sheet-footer .fd-crew-error {
  margin: 0;
}
@media (prefers-reduced-motion: reduce) {
  .fd-crew-seat.is-pending .fd-crew-face,
  .fd-crew-choice {
    animation: none;
  }
  .fd-crew-face,
  .fd-crew-chip {
    transition: none;
  }
}

/* src/features/awards/awards.css */
.tv-pane.tv-awards {
  align-items: center;
  justify-content: space-between;
  padding: 8px 60px 40px;
  gap: 12px;
}
@keyframes tv-award-in {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-award-rise {
  from {
    opacity: 0;
    transform: translateY(48px) scale(.9);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-award-stamp {
  0% {
    opacity: 0;
    transform: rotate(-6deg) scale(1.9);
  }
  70% {
    opacity: 1;
    transform: rotate(-6deg) scale(.94);
  }
  100% {
    opacity: 1;
    transform: rotate(-6deg) scale(1);
  }
}
@keyframes tv-award-drop {
  from {
    opacity: 0;
    transform: translateY(-60px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-awards-head {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  animation: tv-award-in 480ms var(--ease-out) calc(var(--tl) + 0ms) backwards;
}
.tv-awards-head .tv-label {
  color: var(--muted2);
}
.tv-awards-title {
  font-size: 96px;
  line-height: .95;
  color: var(--bone);
  max-width: 1760px;
}
.tv-awards-field {
  flex: 1;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 0;
}
.tv-award-nominee {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  min-width: 0;
  transition: opacity 500ms var(--ease-out), transform 500ms var(--ease-out);
  animation: tv-award-rise 420ms var(--ease-out) calc(var(--tl) + var(--nominee-in, 500ms)) backwards;
}
.tv-award-nominee.is-dim {
  opacity: .3;
}
.tv-award-nominee.is-winner {
  transform: translateY(-14px);
}
.tv-award-pile {
  height: 270px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  gap: 14px;
}
.tv-awards-field[data-crowded] .tv-award-pile {
  height: 230px;
}
.tv-award-slips {
  display: flex;
  flex-direction: column-reverse;
  align-items: stretch;
}
.tv-award-slips i {
  display: block;
  border-radius: 3px;
  background: var(--bone);
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--ink0) 22%, transparent), 0 2px 6px color-mix(in srgb, var(--ink0) 55%, transparent);
  animation: tv-award-drop 260ms var(--ease-land) both;
