  text-overflow: ellipsis;
  white-space: nowrap;
}
.fd-awards-chip {
  display: block;
  border-radius: 50%;
  line-height: 0;
  transition: box-shadow var(--motion-fast) var(--ease-out), transform var(--motion-fast) var(--ease-out);
}
.fd-awards-nominee.is-picked {
  background: var(--info-tint);
}
.fd-awards-nominee.is-picked .fd-awards-chip {
  box-shadow:
    0 0 0 3px var(--paper),
    0 0 0 5px var(--lamp-info),
    0 0 16px color-mix(in srgb, var(--lamp-info) 55%, transparent);
  transform: scale(1.06);
}
@keyframes fd-awards-pick {
  0% {
    transform: scale(.86);
