  60% {
    transform: scale(1.14);
  }
  100% {
    transform: scale(1.06);
  }
}
.fd-awards-nominee.is-picked.is-fresh .fd-awards-chip {
  animation: fd-awards-pick var(--motion-stamp) var(--ease-land) both;
}
.fd-awards-nominee.is-picked > span:last-child {
  color: var(--lamp-info);
  font-weight: 800;
}
.fd-awards-nominee:disabled {
  cursor: default;
  opacity: .4;
}
.fd-awards-note {
  margin: 10px 0 0;
  font: 500 13px/1.4 var(--fd-body);
  color: var(--muted2);
}
.fd-awards-error {
  margin: 10px 0 0;
  font: 600 13px/1.35 var(--fd-body);
  color: var(--clay-text);
}
.fd-awards-results {
  list-style: none;
  margin: 0;
  padding: 0 14px 6px;
  border-top: 1px solid var(--line);
}
.fd-awards-result {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 56px;
  padding: 6px 0;
  border-top: 1px solid var(--line);
}
.fd-awards-result:first-child {
