}
.fd-awards-result > span:first-child {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.fd-awards-result small {
  color: var(--muted2);
  font: 800 13px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-awards-result strong {
  font: 900 24px/1.12 var(--fd-show);
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fd-awards-result-who {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.fd-awards-result-who button + button {
  margin-left: -14px;
}
.fd-awards-result-who button {
  min-width: 44px;
  min-height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  border-radius: 50%;
}
.fd-awards-result-votes {
  min-width: 48px;
  text-align: right;
  font: 600 13px/1.2 var(--fd-body);
  color: var(--muted2);
  font-variant-numeric: tabular-nums;
}
@keyframes fd-awards-new {
  from {
    background: var(--live-tint);
  }
  to {
    background: transparent;
  }
}
.fd-awards-result.is-new {
  animation: fd-awards-new 1600ms var(--ease-out) both;
}
.fd-awards-desk {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.fd-awards-count {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.fd-awards-count strong {
  font: 700 56px/1 var(--fd-display);
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.fd-awards-count span {
  font: 600 15px/1.2 var(--fd-body);
  color: var(--muted);
}
.fd-awards-edit {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--paper);
}
.fd-awards-edit-row {
  display: flex;
  gap: 8px;
  align-items: center;
}
.fd-awards-edit input[type=text] {
  flex: 1;
  min-width: 0;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper2);
  color: var(--ink);
  font: 600 16px/1.2 var(--fd-body);
}
.fd-awards-toggle {
  display: flex;
  gap: 6px;
}
.fd-awards-toggle button {
  min-height: 44px;
  flex: 1;
