/* src/features/geo/geo.css */
.fd-geo-map {
  position: relative;
  width: 100%;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--paper2);
  isolation: isolate;
}
.fd-geo-map > .fd-geo-map-box {
  position: absolute;
  inset: 0;
}
.fd-geo-map-loading {
  position: absolute;
  inset: 0;
  background: var(--paper);
  animation: fd-geo-wait 1.1s ease-in-out infinite alternate;
}
@keyframes fd-geo-wait {
  from {
    opacity: .35;
  }
  to {
    opacity: .8;
  }
}
.fd-geo-map .maplibregl-canvas {
  outline: none;
}
.fd-geo-map .maplibregl-ctrl.maplibregl-ctrl-attrib {
  background: color-mix(in srgb, var(--bg) 78%, transparent);
  color: var(--muted2);
  font: 500 12px/1.3 var(--fd-body);
}
.fd-geo-map .maplibregl-ctrl.maplibregl-ctrl-attrib.maplibregl-compact {
  min-height: 24px;
}
.fd-geo-map .maplibregl-ctrl-attrib a {
  color: var(--muted2);
}
.fd-geo-map .maplibregl-ctrl-attrib-button {
  filter: invert(1);
  opacity: .7;
}
.fd-geo-map .leaflet-container {
  background: var(--paper2);
  font: 500 12px/1.3 var(--fd-body);
}
.fd-geo-map .leaflet-control-attribution {
  background: color-mix(in srgb, var(--bg) 70%, transparent);
  color: var(--muted2);
}
.fd-geo-map .leaflet-bar a {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--line);
}
.fd-geo-map-failed {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 16px;
  text-align: center;
  color: var(--muted2);
  font: 500 13px/1.4 var(--fd-body);
}
.fd-geo-pick {
  height: min(46vh, 320px);
}
.fd-geo-full {
  position: absolute;
  inset: 0;
  height: auto;
  border: 0;
  border-radius: 0;
}
.fd-geo-icon {
  background: none;
  border: 0;
}
.fd-geo-marker {
  position: relative;
  width: 36px;
  height: 48px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  cursor: grab;
}
.fd-geo-marker:active {
  cursor: grabbing;
}
.fd-geo-head {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--pin, var(--sun));
  border: 3px solid var(--ink0);
  box-shadow: var(--shadow-2);
}
.fd-geo-head b {
  font: 800 12px/1 var(--fd-body);
  letter-spacing: .02em;
  color: var(--ink0);
}
.fd-geo-stem {
  width: 4px;
  height: 16px;
  margin-top: -2px;
  border-radius: 0 0 99px 99px;
  background: var(--bone);
  box-shadow: 0 0 0 1.5px var(--ink0);
}
.fd-geo-marker::after {
  content: "";
  position: absolute;
  bottom: -3px;
  width: 14px;
  height: 5px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--ink0) 55%, transparent);
}
.fd-geo-marker.is-dropping > * {
  animation: fd-geo-drop .62s cubic-bezier(.2, .9, .3, 1.25) var(--drop-delay, 0ms) both;
}
.fd-geo-marker.is-dropping::after {
  animation: fd-geo-shadow .62s ease-out var(--drop-delay, 0ms) both;
}
@keyframes fd-geo-drop {
  0% {
    transform: translateY(-70px);
    opacity: 0;
  }
  55% {
    transform: translateY(3px);
    opacity: 1;
  }
  75% {
    transform: translateY(-6px);
  }
  100% {
    transform: none;
  }
}
@keyframes fd-geo-shadow {
  0% {
    transform: scale(.2);
    opacity: 0;
  }
  55% {
    transform: scale(1.15);
    opacity: 1;
  }
  100% {
    transform: none;
  }
}
.fd-geo-marker.is-answer {
  width: 44px;
  height: 44px;
  justify-content: center;
  cursor: default;
}
.fd-geo-marker.is-answer::after {
  display: none;
}
.fd-geo-marker.is-answer .fd-geo-head {
  width: 34px;
  height: 34px;
  background: var(--bone);
  border: 4px solid var(--sun);
  box-shadow: 0 0 0 3px var(--ink0), var(--shadow-2);
}
.fd-geo-marker.is-answer .fd-geo-head i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--ink0);
}
.fd-geo-pulse {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 3px solid var(--sun);
  animation: fd-geo-pulse 1.8s ease-out infinite;
}
@keyframes fd-geo-pulse {
  from {
    transform: scale(.6);
    opacity: .9;
  }
  to {
    transform: scale(2.2);
    opacity: 0;
  }
}
.fd-geo-marker.is-answer.is-dropping > .fd-geo-head {
  animation: fd-geo-land .55s cubic-bezier(.2, .9, .3, 1.4) var(--drop-delay, 0ms) both;
}
@keyframes fd-geo-land {
  from {
    transform: scale(0);
  }
  to {
    transform: none;
  }
}
.fd-geo-game {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--bg);
  color: var(--ink);
  animation: fd-geo-in .28s ease-out both;
}
@keyframes fd-geo-in {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.fd-geo-game-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: calc(env(safe-area-inset-top) + 8px) 12px 12px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  box-shadow: inset 0 3px 0 var(--lamp-live);
  transition: background .3s ease;
}
.fd-geo-timebar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 6px;
  background: var(--bg);
}
.fd-geo-timebar i {
  position: absolute;
  inset: 0;
  background: var(--lamp-live);
  transform-origin: left;
  box-shadow: 0 0 10px color-mix(in srgb, var(--lamp-live) 70%, transparent);
  transition: transform .25s linear, background .3s ease;
}
.fd-geo-game.is-urgent .fd-geo-game-head {
  background: var(--clay-tint);
  box-shadow: inset 0 3px 0 var(--clay);
}
.fd-geo-game.is-urgent .fd-geo-timebar i {
  background: var(--clay);
  box-shadow: 0 0 10px var(--clay);
  animation: fd-geo-urgent .5s ease-in-out infinite alternate;
}
@keyframes fd-geo-urgent {
  from {
    opacity: 1;
  }
  to {
    opacity: .45;
  }
}
.fd-geo-final {
  position: fixed;
  z-index: 150;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  pointer-events: none;
  font: 700 140px/1 var(--fd-display);
  color: var(--clay-text);
  opacity: 0;
  animation: fd-geo-final 1s ease-out both;
  text-shadow: 0 4px 0 var(--ink0);
}
@keyframes fd-geo-final {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.6);
  }
  18% {
    opacity: .92;
    transform: translate(-50%, -50%) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.9);
  }
}
.fd-geo-primary.is-hurry {
  background: var(--clay);
  color: var(--bone);
}
.fd-geo-count {
  flex: 1;
  min-width: 0;
