  gap: 3px;
}
.fd-geo-count small {
  color: var(--lamp-live-text);
  font: 900 22px/1.1 var(--fd-show);
  letter-spacing: .01em;
  text-transform: none;
  text-shadow: 0 0 14px color-mix(in srgb, var(--lamp-live) 45%, transparent);
}
.fd-geo-count b {
  font: 800 22px/1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.fd-geo-count i {
  font-style: normal;
  color: var(--muted2);
}
.fd-geo-close {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--paper);
  color: var(--ink);
  font: 400 26px/1 var(--fd-body);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-geo-clock {
  position: relative;
  width: 54px;
