/* src/features/trivia/trivia.css */
.fd-trivia-game {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
  animation: fd-trivia-in .28s ease-out both;
}
@keyframes fd-trivia-in {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.fd-trivia-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: calc(env(safe-area-inset-top) + 8px) 12px 12px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  box-shadow: inset 0 3px 0 var(--lamp-live);
  transition: background .3s ease;
}
.fd-trivia-count {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 3px;
}
.fd-trivia-count small {
  color: var(--lamp-live-text);
  font: 900 21px/1.15 var(--fd-show);
  overflow-wrap: anywhere;
  text-shadow: 0 0 14px color-mix(in srgb, var(--lamp-live) 45%, transparent);
}
.fd-trivia-count b {
  font: 800 20px/1.1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.fd-trivia-count i {
  font-style: normal;
  color: var(--muted2);
}
.fd-trivia-close {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-trivia-timebar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 6px;
  background: var(--bg);
}
.fd-trivia-timebar i {
  position: absolute;
  inset: 0;
  background: var(--lamp-live);
  transform-origin: left;
  box-shadow: 0 0 10px color-mix(in srgb, var(--lamp-live) 70%, transparent);
  transition: transform .25s linear, background .3s ease;
}
.fd-trivia-game.is-urgent .fd-trivia-head {
  background: var(--clay-tint);
  box-shadow: inset 0 3px 0 var(--clay);
}
.fd-trivia-game.is-urgent .fd-trivia-timebar i {
  background: var(--clay);
  box-shadow: 0 0 10px var(--clay);
  animation: fd-trivia-urgent .5s ease-in-out infinite alternate;
}
@keyframes fd-trivia-urgent {
  from {
    opacity: 1;
  }
  to {
    opacity: .45;
  }
}
.fd-trivia-clock {
  position: relative;
  flex-shrink: 0;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
}
.fd-trivia-clock svg {
  position: absolute;
  inset: 0;
  transform: rotate(-90deg);
  overflow: visible;
}
.fd-trivia-clock circle {
  fill: none;
  stroke-width: 4;
}
.fd-trivia-clock .track {
  stroke: var(--bg);
}
.fd-trivia-clock .run {
  stroke: var(--lamp-live);
  stroke-linecap: round;
  transition: stroke-dashoffset .25s linear;
  filter: drop-shadow(0 0 3px var(--lamp-live));
}
.fd-trivia-clock b {
  font: 800 22px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-trivia-clock.is-low .run {
  stroke: var(--clay);
  filter: drop-shadow(0 0 3px var(--clay));
}
.fd-trivia-clock.is-low b {
  color: var(--clay-text);
  animation: fd-trivia-beat 1s ease-in-out infinite;
}
@keyframes fd-trivia-beat {
  50% {
    transform: scale(1.18);
  }
}
.fd-trivia-stamp {
  position: fixed;
  z-index: 150;
  left: 50%;
  top: 40%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  font: 900 150px/1 var(--fd-display);
  color: var(--lamp-live-text);
  opacity: 0;
  text-shadow: 0 4px 0 var(--ink0);
  animation: fd-trivia-stamp 1.6s var(--ease-land) both;
}
@keyframes fd-trivia-stamp {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.7);
  }
  22% {
    opacity: .9;
    transform: translate(-50%, -50%) scale(1);
  }
  70% {
    opacity: .6;
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.94);
  }
}
.fd-trivia-body {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px 16px 18px;
}
.fd-trivia-text {
  margin: 0;
  font: 900 30px/1.15 var(--fd-show);
  letter-spacing: .01em;
  color: var(--ink);
  overflow-wrap: anywhere;
  text-wrap: balance;
  animation: fd-trivia-rise .4s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-trivia-text.is-long {
  font-size: 25px;
}
@keyframes fd-trivia-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}
.fd-trivia-options {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-trivia-options li {
  animation: fd-trivia-rise .38s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-trivia-options li:nth-child(2) {
  animation-delay: 60ms;
}
.fd-trivia-options li:nth-child(3) {
  animation-delay: 120ms;
}
.fd-trivia-options li:nth-child(4) {
  animation-delay: 180ms;
}
.fd-trivia-option {
  position: relative;
  width: 100%;
  min-height: 62px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px 10px 10px;
  border: 1px solid var(--ghost-line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  box-shadow: var(--glass-edge);
  transition:
    background .18s ease,
    border-color .18s ease,
    transform .1s ease;
  -webkit-tap-highlight-color: transparent;
}
.fd-trivia-option:active:not(:disabled) {
  transform: scale(.98);
}
.fd-trivia-option:disabled {
  cursor: default;
}
.fd-trivia-letter {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: var(--bg);
  box-shadow: inset 0 2px 4px color-mix(in srgb, var(--ink0) 60%, transparent);
  font: 800 20px/1 var(--fd-display);
  color: var(--muted2);
}
.fd-trivia-option-text {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 3px;
  font: 600 17px/1.3 var(--fd-body);
  overflow-wrap: anywhere;
}
.fd-trivia-option-text b {
  font: inherit;
}
.fd-trivia-option-text small {
  color: var(--muted2);
  font: 500 14px/1.3 var(--fd-body);
}
.fd-trivia-option.is-picked {
  border-color: var(--you);
  background: var(--you-tint);
  box-shadow: var(--you-bloom);
}
.fd-trivia-option.is-picked .fd-trivia-letter {
  background: var(--you);
  color: var(--ink0);
  box-shadow: none;
}
.fd-trivia-lock {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--ink0);
  color: var(--bone);
}
.fd-trivia-option.is-locked {
  animation: fd-trivia-lockin .4s var(--ease-land) both;
}
@keyframes fd-trivia-lockin {
  from {
    transform: scale(1.04);
  }
}
.fd-trivia-option.is-right {
  border-color: var(--green);
  background: color-mix(in srgb, var(--green) 16%, var(--paper));
  box-shadow:
    var(--glass-edge),
    0 0 0 1px var(--green),
    0 0 18px color-mix(in srgb, var(--green) 30%, transparent);
  animation: fd-trivia-right .5s var(--ease-land) .25s both;
}
.fd-trivia-option.is-right .fd-trivia-letter {
  background: var(--green);
  color: var(--ink0);
  box-shadow: none;
}
@keyframes fd-trivia-right {
  from {
    transform: scale(1.06);
  }
}
.fd-trivia-option.is-out {
  opacity: .62;
}
.fd-trivia-option.is-wrong {
  opacity: 1;
  border-color: var(--clay);
  background: var(--clay-tint);
  box-shadow: var(--glass-edge);
}
.fd-trivia-option.is-wrong .fd-trivia-letter {
  background: var(--clay);
  color: var(--bone);
}
.fd-trivia-tally {
  flex-shrink: 0;
  min-width: 40px;
  padding: 6px 8px;
  border-radius: 10px;
  background: var(--bg);
  text-align: center;
  box-shadow: inset 0 2px 4px color-mix(in srgb, var(--ink0) 60%, transparent);
  font: 800 22px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--muted2);
  animation: fd-trivia-rise .4s cubic-bezier(.2, .8, .2, 1) .6s both;
}
.fd-trivia-option.is-right .fd-trivia-tally {
  color: var(--green);
}
.fd-trivia-faces {
  display: flex;
  align-items: center;
  margin-top: 6px;
  padding-left: 4px;
}
.fd-trivia-faces > span {
  display: grid;
  margin-left: 2px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px var(--paper);
  animation: fd-trivia-land .36s var(--ease-land) calc(.8s + var(--i) * 50ms) both;
}
.fd-trivia-faces > span.is-mine {
  box-shadow: 0 0 0 2px var(--you), 0 0 10px color-mix(in srgb, var(--you) 55%, transparent);
  z-index: 1;
}
.fd-trivia-faces > b {
  margin-left: 6px;
  color: var(--muted2);
  font: 800 15px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
@keyframes fd-trivia-land {
  from {
    opacity: 0;
    transform: scale(.4) translateY(-8px);
  }
}
.fd-trivia-photo {
  position: relative;
  flex-shrink: 0;
  width: 100%;
  height: 180px;
  padding: 0;
  border: 0;
  border-radius: 14px;
  overflow: hidden;
  background: var(--ink0);
  cursor: zoom-in;
  box-shadow: var(--glass-edge);
}
.fd-trivia-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  animation: fd-trivia-photo .45s ease-out both;
}
.fd-trivia-photo.is-full {
  height: min(60vh, 460px);
  cursor: zoom-out;
}
.fd-trivia-photo.is-full img {
  object-fit: contain;
}
@keyframes fd-trivia-photo {
  from {
    opacity: 0;
    transform: scale(1.04);
  }
}
.fd-trivia-listen {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  min-height: 88px;
  border-radius: 14px;
  background: var(--bg);
  box-shadow: inset 0 2px 8px color-mix(in srgb, var(--ink0) 60%, transparent);
  color: var(--muted2);
}
.fd-trivia-bars {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 56px;
}
.fd-trivia-bars i {
  width: 8px;
  height: 56px;
  border-radius: 99px;
  background: var(--lamp-live);
  transform: scaleY(.18);
  opacity: .5;
}
.fd-trivia-listen.is-live {
  color: var(--lamp-live-text);
}
.fd-trivia-listen.is-live .fd-trivia-bars i {
  opacity: 1;
  box-shadow: 0 0 8px color-mix(in srgb, var(--lamp-live) 50%, transparent);
  animation: fd-trivia-bar .9s ease-in-out calc(var(--i) * -.13s) infinite alternate;
}
@keyframes fd-trivia-bar {
  0% {
    transform: scaleY(.2);
  }
  40% {
    transform: scaleY(.95);
  }
  70% {
    transform: scaleY(.45);
  }
  100% {
    transform: scaleY(.75);
  }
}
.fd-trivia-number {
  display: grid;
  justify-items: center;
  gap: 10px;
}
.fd-trivia-wheels {
  display: grid;
  grid-template-columns: repeat(var(--digits), minmax(0, 52px));
  gap: 6px;
  justify-content: center;
  width: 100%;
}
.fd-trivia-wheels .fd-wheel-item {
  font-size: 30px;
}
.fd-trivia-number.is-off {
  opacity: .7;
  pointer-events: none;
}
.fd-trivia-unit {
  color: var(--muted2);
  font: 800 18px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-trivia-unit.is-watch {
  margin: 0;
  text-align: center;
}
.fd-trivia-foot {
  display: grid;
  gap: 10px;
  padding: 10px 14px calc(env(safe-area-inset-bottom) + 12px);
  border-top: 1px solid var(--line);
  background: var(--chrome);
}
.fd-trivia-room {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
  margin: 0;
  padding: 2px 0;
  list-style: none;
}
.fd-trivia-room li {
  display: grid;
  border-radius: 50%;
  opacity: .3;
  filter: saturate(.2);
  transition: opacity .3s ease, filter .3s ease;
}
.fd-trivia-room li.is-set {
  opacity: .55;
}
.fd-trivia-room li.is-locked {
  opacity: 1;
  filter: none;
  animation: fd-trivia-land .36s var(--ease-land) both;
}
.fd-trivia-room li.is-mine {
  box-shadow: 0 0 0 2px var(--you);
}
.fd-trivia-primary {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 14px;
  background: var(--action-fill);
  color: var(--action-ink);
  font: 700 17px/1 var(--fd-body);
  cursor: pointer;
  box-shadow: var(--chip-bloom);
  transition: transform .12s ease, background .2s ease;
}
.fd-trivia-primary:active:not(:disabled) {
  transform: scale(.97);
}
.fd-trivia-primary:disabled {
  background: var(--paper2);
  color: var(--muted2);
  cursor: default;
  box-shadow: var(--glass-edge);
}
.fd-trivia-primary.is-hurry {
  background: var(--clay);
  color: var(--bone);
  box-shadow: none;
}
.fd-trivia-primary b {
  font-variant-numeric: tabular-nums;
}
.fd-trivia-primary.is-done {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px var(--lamp-info);
  animation: fd-trivia-lockin .4s var(--ease-land) both;
}
.fd-trivia-primary.is-done b {
  color: var(--ink);
  font: 800 20px/1 var(--fd-display);
}
.fd-trivia-primary.is-over {
  background: var(--paper2);
  color: var(--muted2);
  box-shadow: var(--glass-edge);
}
.fd-trivia-error {
  margin: 0;
  color: var(--clay-text);
  font: 600 13px/1.4 var(--fd-body);
}
.fd-trivia-game.is-reveal,
.fd-trivia-game.is-board {
  grid-template-rows: auto minmax(0, 1fr);
}
.fd-trivia-body.is-reveal {
  padding-bottom: calc(env(safe-area-inset-bottom) + 20px);
}
.fd-trivia-points {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 4px 14px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
  animation: fd-trivia-rise .45s cubic-bezier(.2, .8, .2, 1) .5s both;
}
.fd-trivia-points > b {
  grid-row: span 2;
  font: 800 44px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
.fd-trivia-points.is-none > b {
  font-size: 24px;
  color: var(--muted2);
}
.fd-trivia-unit {
  margin-left: 4px;
  font: 800 16px/1 var(--fd-display);
  letter-spacing: .04em;
  color: var(--muted2);
}
.fd-trivia-points.is-wrong {
  border-color: color-mix(in srgb, var(--clay) 55%, transparent);
}
.fd-trivia-points.is-wrong > b {
  color: var(--clay-text);
}
.fd-trivia-points.is-wrong small {
  color: var(--clay-text);
}
.fd-trivia-split {
  display: flex;
  height: 12px;
  border-radius: 99px;
  overflow: hidden;
  background: var(--bg);
  box-shadow: inset 0 2px 4px color-mix(in srgb, var(--ink0) 60%, transparent);
}
.fd-trivia-split i {
  width: calc(var(--w) * 100%);
  transform-origin: left;
  animation: fd-trivia-fill .7s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-trivia-split .is-base {
  background: var(--bone);
  animation-delay: .7s;
}
.fd-trivia-split .is-bonus {
  background: var(--lamp-info);
  animation-delay: 1.25s;
}
@keyframes fd-trivia-fill {
  from {
    transform: scaleX(0);
  }
}
.fd-trivia-points small {
  grid-column: 2;
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-trivia-split {
  grid-column: 2;
}
.fd-trivia-place {
  grid-column: 3;
  grid-row: 1 / span 2;
  color: var(--you);
  font: 800 30px/1 var(--fd-display);
  font-style: normal;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 14px color-mix(in srgb, var(--you) 40%, transparent);
}
.fd-trivia-numreveal {
  display: grid;
  gap: 14px;
}
.fd-trivia-answer {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 10px;
  margin: 0;
  animation: fd-trivia-right .5s var(--ease-land) .2s both;
}
.fd-trivia-answer b {
  font: 800 56px/1 var(--fd-display);
  color: var(--green);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px color-mix(in srgb, var(--green) 30%, transparent);
}
.fd-trivia-answer span {
  color: var(--muted2);
  font: 800 18px/1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-trivia-numreveal ol {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-trivia-numreveal li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  grid-template-areas: "face name guess pts" "face name off pts";
  align-items: center;
  gap: 2px 10px;
  padding: 8px 12px 8px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  animation: fd-trivia-rise .4s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-trivia-numreveal li:nth-child(2) {
  animation-delay: 80ms;
}
.fd-trivia-numreveal li:nth-child(3) {
  animation-delay: 160ms;
}
.fd-trivia-numreveal li:nth-child(4) {
  animation-delay: 240ms;
}
.fd-trivia-numreveal li > :first-child {
  grid-area: face;
}
.fd-trivia-numreveal li .fd-trivia-name {
  grid-area: name;
}
.fd-trivia-numreveal li b {
  grid-area: guess;
  text-align: right;
  font: 800 22px/1.1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-trivia-numreveal li .fd-trivia-off {
  grid-area: off;
  text-align: right;
  color: var(--muted2);
  font: 500 13px/1.2 var(--fd-body);
}
.fd-trivia-numreveal li em {
  grid-area: pts;
  min-width: 56px;
  text-align: right;
  font: 800 24px/1 var(--fd-display);
  font-style: normal;
  color: var(--ink);
}
.fd-trivia-numreveal li.is-mine {
  border-color: var(--you);
  background: var(--you-tint);
  box-shadow: var(--you-bloom);
}
.fd-trivia-numreveal li.is-gap {
  margin-top: 8px;
}
.fd-trivia-numreveal li.is-none {
  display: block;
  color: var(--muted2);
}
.fd-trivia-standings {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-trivia-standings li {
  display: grid;
  grid-template-columns: 28px auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 12px 8px 8px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
}
.fd-trivia-standings.is-compact li {
  padding: 5px 10px 5px 6px;
  border-radius: 10px;
}
.fd-trivia-standings li.is-mine {
  border-color: var(--you);
  background: var(--you-tint);
  box-shadow: var(--you-bloom);
}
.fd-trivia-standings li.fd-trivia-gap {
  height: 0;
  padding: 0;
  border: 0;
  border-top: 2px dotted var(--ghost-line);
  border-radius: 0;
  background: none;
  margin: 2px 40%;
}
.fd-trivia-rank {
  font: 800 22px/1 var(--fd-display);
  color: var(--muted2);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.fd-trivia-standings li.is-mine .fd-trivia-rank {
  color: var(--you);
}
.fd-trivia-name {
  min-width: 0;
  font: 600 15px/1.25 var(--fd-body);
  color: var(--ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fd-trivia-total {
  display: grid;
  justify-items: end;
  font: 800 24px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-trivia-standings.is-compact .fd-trivia-total {
  font-size: 22px;
  grid-auto-flow: column;
  align-items: baseline;
  gap: 8px;
}
.fd-trivia-total small {
  color: var(--green);
  font: 800 14px/1.2 var(--fd-display);
}
.fd-trivia-body.is-board {
  gap: 18px;
}
.fd-trivia-board-title {
  margin: 0;
  font: 900 40px/1.1 var(--fd-show);
  color: var(--ink);
  overflow-wrap: anywhere;
  text-shadow: 0 0 18px color-mix(in srgb, var(--lamp-live) 35%, transparent);
}
.fd-trivia-body.is-board .fd-trivia-standings li {
  animation: fd-trivia-rise .45s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-trivia-body.is-board .fd-trivia-standings li:nth-child(2) {
  animation-delay: 90ms;
}
.fd-trivia-body.is-board .fd-trivia-standings li:nth-child(3) {
  animation-delay: 180ms;
}
.fd-trivia-body.is-board .fd-trivia-standings li:nth-child(4) {
  animation-delay: 270ms;
}
.fd-trivia-body.is-board .fd-trivia-standings li:nth-child(5) {
  animation-delay: 360ms;
}
.fd-trivia-body.is-board .fd-trivia-standings li:nth-child(n+6) {
  animation-delay: 520ms;
}
.fd-trivia-home {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 60px;
  margin: 12px 0 0;
  padding: 10px 14px;
  border: 1px solid var(--lamp-live);
  border-radius: 14px;
  background: color-mix(in srgb, var(--lamp-live) 6%, var(--paper));
  box-shadow: var(--live-bloom), var(--glass-edge);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-trivia-home > span:first-child {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 10px;
  align-items: baseline;
}
.fd-trivia-home > span:last-child {
  color: var(--lamp-info);
}
.fd-trivia-home small {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--ink);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-trivia-home small .fd-beat-dot {
  --lamp:var(--lamp-live);
}
.fd-trivia-home strong {
  font: 800 22px/1.1 var(--fd-display);
  letter-spacing: .02em;
  text-transform: uppercase;
}
.fd-trivia-home em {
  font: 700 15px/1.2 var(--fd-body);
  font-style: normal;
  color: var(--lamp-live-text);
  font-variant-numeric: tabular-nums;
}
@media (max-height: 740px) {
  .fd-trivia-body {
    gap: 12px;
    padding-top: 14px;
  }
  .fd-trivia-text {
    font-size: 25px;
  }
  .fd-trivia-text.is-long {
    font-size: 22px;
  }
  .fd-trivia-option {
    min-height: 52px;
    padding-top: 6px;
    padding-bottom: 6px;
  }
  .fd-trivia-options {
    gap: 8px;
  }
  .fd-trivia-letter {
    width: 32px;
    height: 32px;
  }
  .fd-trivia-photo {
    height: 120px;
  }
  .fd-trivia-listen {
    min-height: 64px;
  }
  .fd-trivia-foot {
    gap: 8px;
    padding-top: 8px;
  }
  .fd-trivia-primary {
    min-height: 52px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-trivia-game,
  .fd-trivia-text,
  .fd-trivia-options li,
  .fd-trivia-faces > span,
  .fd-trivia-tally,
  .fd-trivia-option.is-locked,
  .fd-trivia-option.is-right,
  .fd-trivia-photo img,
  .fd-trivia-points,
  .fd-trivia-split i,
  .fd-trivia-answer,
  .fd-trivia-numreveal li,
  .fd-trivia-primary.is-done,
  .fd-trivia-body.is-board .fd-trivia-standings li,
  .fd-trivia-clock.is-low b,
  .fd-trivia-game.is-urgent .fd-trivia-timebar i,
  .fd-trivia-listen.is-live .fd-trivia-bars i,
  .fd-trivia-room li.is-locked {
    animation: none;
  }
  .fd-trivia-stamp {
    display: none;
  }
}
.fd-trivia-desk,
.fd-trivia-editor {
  display: grid;
  gap: 12px;
}
.fd-trivia-hint {
  margin: 0;
  color: var(--muted2);
