/* src/features/trivia/board.css */
.fd-board-game {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
  animation: fd-trivia-in .28s ease-out both;
}
.fd-board-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: calc(env(safe-area-inset-top) + 8px) 12px 10px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  box-shadow: inset 0 3px 0 var(--lamp-live);
}
.fd-board-title {
  flex: 1;
  min-width: 0;
  font: 900 22px/1.15 var(--fd-show);
  letter-spacing: .01em;
  color: var(--lamp-live-text);
  text-shadow: 0 0 14px color-mix(in srgb, var(--lamp-live) 45%, transparent);
}
.fd-board-yours .fd-reel {
  font: 800 22px/1 var(--fd-display);
}
.fd-board-yours.is-neg .fd-reel,
.fd-board-score.is-neg .fd-reel {
  color: var(--clay-text);
  --reel-tint:var(--clay);
  --reel-mix:10%;
}
.fd-board-body {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px 16px calc(env(safe-area-inset-bottom) + 18px);
}
.fd-board-error {
  margin: 0;
  color: var(--clay-text);
  font: 600 13px/1.4 var(--fd-body);
}
.fd-board-turnlamp {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--ink);
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-board-lamp {
  width: 12px;
  height: 12px;
  --lamp:var(--lamp-live);
}
.fd-board-turnlamp.is-chip {
  color: var(--sun);
}
.fd-board-turnlamp.is-chip .fd-board-lamp {
  --lamp:var(--sun);
}
.fd-board-turnlamp.is-quiet {
  margin-left: auto;
  color: var(--lamp-live-text);
}
.fd-board-picker {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
}
