  gap: 10px;
  border: 0;
  border-radius: 14px;
  background: var(--action-fill);
  color: var(--action-ink);
  font: 700 17px/1 var(--fd-body);
  cursor: pointer;
  box-shadow: var(--chip-bloom);
  transition: transform .12s ease;
}
.fd-board-primary:active:not(:disabled) {
  transform: scale(.97);
}
.fd-board-primary:disabled {
  background: var(--paper2);
  color: var(--muted2);
  cursor: default;
  box-shadow: var(--glass-edge);
}
.fd-board-primary.is-done {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px var(--lamp-info);
  animation: fd-trivia-lockin .4s var(--ease-land) both;
}
.fd-board-primary.is-over {
  background: var(--paper2);
  color: var(--muted2);
  box-shadow: var(--glass-edge);
}
.fd-board-dd {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 8px 0 2px;
  text-align: center;
}
.fd-board-dd-word {
  font: 900 46px/1.05 var(--fd-show);
  color: var(--sun);
  transform: rotate(-4deg);
  text-shadow: 0 3px 0 var(--ink0), 0 0 22px color-mix(in srgb, var(--sun) 45%, transparent);
}
.fd-board-dd.is-sting .fd-board-dd-word {
  animation: fd-board-dd 900ms cubic-bezier(.3, 1.6, .5, 1) both;
}
@keyframes fd-board-dd {
  0% {
    opacity: 0;
    transform: rotate(-4deg) scale(2.2);
  }
  60% {
    opacity: 1;
    transform: rotate(-4deg) scale(.9, 1.12);
  }
  100% {
    transform: rotate(-4deg);
  }
}
.fd-board-dd .fd-board-cat {
  flex: none;
  text-align: center;
}
.fd-board-finalhead {
  display: grid;
  gap: 4px;
}
.fd-board-final-cat {
  font: 900 30px/1.12 var(--fd-show);
  color: var(--ink);
  overflow-wrap: anywhere;
}
.fd-board-final-text {
  margin: 0;
  font: 900 26px/1.18 var(--fd-show);
  letter-spacing: .01em;
  color: var(--ink);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.fd-board-final-text.is-long {
  font-size: 22px;
}
.fd-board-photo {
  flex-shrink: 0;
  height: 150px;
  border-radius: 14px;
  overflow: hidden;
  background: var(--ink0);
}
.fd-board-photo img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}
.fd-board-body.is-clue {
  padding-bottom: 12px;
}
.fd-board-foot {
  display: grid;
  gap: 10px;
  padding: 10px 14px calc(env(safe-area-inset-bottom) + 12px);
  border-top: 1px solid var(--line);
  background: var(--chrome);
}
.fd-board-final-you {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--paper);
  border: 1px solid var(--line);
}
.fd-board-final-you > b {
  font: 800 34px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-board-final-you > b.is-up {
  color: var(--green);
}
.fd-board-final-you > b.is-down {
  color: var(--clay-text);
}
.fd-board-final-you .fd-board-score {
  margin-left: auto;
}
.fd-board-standings-title {
  margin: 0;
  font: 900 40px/1.1 var(--fd-show);
  color: var(--ink);
  text-shadow: 0 0 18px color-mix(in srgb, var(--lamp-live) 35%, transparent);
}
.fd-trivia-total.is-neg {
  color: var(--clay-text);
}
.fd-board-formats {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.fd-board-formats button:disabled {
  opacity: .4;
  cursor: default;
}
.fd-board-desk {
  display: grid;
  gap: 10px;
}
.fd-board-gridwrap.is-blank {
  min-height: 120px;
}
.fd-board-colname.is-edit {
  min-height: 44px;
  margin: 0;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--ink);
  cursor: pointer;
  font-family: var(--fd-show);
  font-weight: 900;
}
.fd-board-colname.is-edit:active {
  background: var(--info-tint);
}
.fd-board-grid.is-desk .fd-board-cell {
  min-height: 40px;
  font-size: 17px;
}
.fd-board-pips {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px;
  min-height: 8px;
  padding-top: 2px;
}
.fd-board-pips i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--muted);
  opacity: .45;
}
.fd-board-out {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-board-out button {
  min-height: 44px;
  padding: 0 12px;
  border: 1px dashed var(--ghost-line);
  border-radius: 10px;
  background: none;
  color: var(--muted2);
  font: 900 16px/1.15 var(--fd-show);
  opacity: .7;
  cursor: pointer;
}
.fd-board-finalcard {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--sun) 45%, var(--line));
  border-radius: 12px;
  background: var(--paper2);
}
.fd-board-finalcard .fd-trivia-qtext strong {
  font: 900 20px/1.15 var(--fd-show);
}
.fd-board-final-answer {
  color: var(--green) !important;
}
.fd-board-sealed {
  display: flex;
  align-items: center;
  gap: 12px;
}
.fd-board-sealed i {
  width: 44px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  font: 800 30px/1 var(--fd-display);
  font-style: normal;
  color: color-mix(in srgb, var(--sun) 60%, var(--bg));
  background:
    radial-gradient(
      110% 95% at 50% 40%,
      color-mix(in srgb, var(--sun) 16%, var(--bg)),
      var(--bg) 75%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sun) 30%, transparent);
}
.fd-board-sealed b {
  font: 600 15px/1.3 var(--fd-body);
  color: var(--muted2);
}
.fd-board-final-edit {
  display: grid;
  gap: 12px;
}
@media (max-height: 740px) {
  .fd-board-body {
    gap: 10px;
    padding-top: 12px;
  }
  .fd-buzzer {
    min-height: 250px;
  }
  .fd-buzzer-button {
    width: min(64vw, 240px);
  }
  .fd-board-cell {
    min-height: 44px;
  }
  .fd-board-option {
    min-height: 52px;
    padding-top: 6px;
    padding-bottom: 6px;
  }
  .fd-board-options {
    gap: 8px;
  }
  .fd-board-wager-reel .fd-reel {
    font-size: 48px;
  }
  .fd-board-dd-word {
    font-size: 38px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-board-game,
  .fd-board-cell.is-pending,
  .fd-buzzer-button,
  .fd-buzzer.is-live .fd-buzzer-bulbs .is-on,
  .fd-buzzer-ms,
  .fd-board-in li.is-in,
  .fd-board-option.is-right,
  .fd-board-delta,
  .fd-board-primary.is-done,
  .fd-board-dd-word {
    animation: none !important;
  }
  .fd-buzzer-cap {
    transition: none;
  }
}

/* src/features/music/winSong.css */
.fd-song {
  display: grid;
  gap: 12px;
  touch-action: manipulation;
}
.fd-song button {
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
.fd-song-note {
  margin: 0;
  color: var(--muted2);
  font: 500 13px/1.45 var(--fd-body);
}
.fd-song-search {
  display: grid;
  gap: 6px;
}
.fd-song-field {
  display: flex;
  align-items: center;
  gap: 8px;
}
.fd-song-field input {
  flex: 1;
  min-width: 0;
  height: 48px;
  padding: 0 40px 0 14px;
  border-radius: 10px;
  border: 1px solid var(--ghost-line);
  background: var(--bg);
  color: var(--ink);
  font: 500 16px var(--fd-body);
  outline: none;
  box-shadow: inset 0 2px 5px color-mix(in srgb, var(--ink0) 55%, transparent);
  -webkit-appearance: none;
  appearance: none;
}
.fd-song-field input:focus {
  border-color: var(--lamp-info);
  box-shadow: 0 0 0 1px var(--lamp-info), 0 0 14px color-mix(in srgb, var(--lamp-info) 30%, transparent);
}
.fd-song-field input::-webkit-search-cancel-button {
  display: none;
}
.fd-song-clear {
  margin-left: -48px;
  width: 44px;
  height: 44px;
  border: 0;
  background: none;
  color: var(--muted2);
  font: 500 22px/1 var(--fd-body);
  cursor: pointer;
}
.fd-song-cancel {
  min-height: 44px;
  padding: 0 4px;
  border: 0;
  background: none;
  color: var(--lamp-info);
  font: 600 14px var(--fd-body);
  cursor: pointer;
}
.fd-song-status {
  min-height: 18px;
  color: var(--muted2);
  font: 500 12px/1.5 var(--fd-body);
}
.fd-song-status .is-error {
  color: var(--clay-text);
}
.fd-song-results {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
  transition: opacity .2s;
}
.fd-song-results.is-stale {
  opacity: .55;
}
.fd-song-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 64px;
}
.fd-song-use {
  flex: 1;
  min-width: 0;
  min-height: 56px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 2px;
  border: 0;
  background: none;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}
.fd-song-use-pill {
  flex-shrink: 0;
  padding: 7px 14px;
  border-radius: 99px;
  border: 1px solid color-mix(in srgb, var(--lamp-info) 55%, transparent);
  color: var(--lamp-info);
  font: 600 13px var(--fd-body);
}
.fd-song-use:active .fd-song-use-pill {
  background: var(--info-tint);
  border-color: var(--lamp-info);
}
.fd-song-credit {
  margin: 4px 0 0;
  color: var(--muted2);
  font: 500 12px/1.4 var(--fd-body);
}
.fd-song-play {
  position: relative;
  flex-shrink: 0;
  padding: 0;
  border: 0;
  border-radius: 10px;
  overflow: hidden;
  background: var(--bg);
  box-shadow: inset 0 0 0 1px var(--ghost-line);
  cursor: pointer;
}
.fd-song-play img,
.fd-song-play-blank {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.fd-song-play-glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--ink0) 28%, transparent);
  transition: background .15s;
}
.fd-song-play-glyph svg {
  width: 40%;
  height: 40%;
  max-width: 28px;
  max-height: 28px;
  fill: var(--bone);
}
.fd-song-play.is-playing .fd-song-play-glyph {
  background: color-mix(in srgb, var(--ink0) 45%, transparent);
}
.fd-song-play:active {
  transform: scale(.96);
}
.fd-song-play.is-still {
  display: block;
  cursor: default;
}
.fd-song-play.is-still:active {
  transform: none;
}
.fd-song-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.fd-song-ring circle {
  fill: none;
  stroke-width: 3;
}
.fd-song-ring-track {
  stroke: color-mix(in srgb, var(--bone) 22%, transparent);
}
.fd-song-ring-fill {
  stroke: var(--sun);
  stroke-linecap: round;
  transition: stroke-dashoffset .25s linear;
}
.fd-song-ring-fill.is-loading {
  animation: fd-song-spin .9s linear infinite;
  transform-origin: 50% 50%;
  transition: none;
}
@keyframes fd-song-spin {
  to {
    transform: rotate(270deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-song-ring-fill.is-loading {
    animation: none;
  }
}
.fd-song-text {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 2px;
}
.fd-song-text strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: 700 15px/1.3 var(--fd-body);
}
.fd-song-text small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted2);
  font: 500 13px/1.3 var(--fd-body);
}
.fd-song-text a {
  justify-self: start;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  color: var(--lamp-info);
  font: 700 13px var(--fd-body);
  text-decoration: none;
}
.fd-song-e {
  display: inline-block;
  margin-left: 6px;
  padding: 0 4px;
  border-radius: 6px;
  background: var(--ink-tint);
  color: var(--muted2);
  font: 700 12px/1.5 var(--fd-body);
  font-style: normal;
  vertical-align: 2px;
}
.fd-song-pick {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper2);
  box-shadow: var(--glass-edge);
}
.fd-song-pick .fd-song-play {
  border-radius: 10px;
}
.fd-song-pick .fd-song-text strong {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  white-space: normal;
  overflow-wrap: anywhere;
  font: 900 24px/1.15 var(--fd-show);
}
.fd-song-change {
  flex-shrink: 0;
  align-self: flex-start;
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  font: 600 13px var(--fd-body);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-song-start {
  padding: 14px 14px 12px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper2);
  box-shadow: var(--glass-edge);
  display: grid;
  gap: 8px;
}
.fd-song-start-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}
.fd-song-start-head span {
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-song-start-head strong {
  font: 800 44px/1 var(--fd-display);
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.fd-song-strip {
  position: relative;
  height: 56px;
  margin-top: 4px;
  border-radius: 10px;
  background: var(--bg);
  box-shadow: inset 0 2px 6px color-mix(in srgb, var(--ink0) 60%, transparent), inset 0 0 0 1px var(--line);
  touch-action: none;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  overflow: hidden;
}
.fd-song-strip:active {
  cursor: grabbing;
}
.fd-song-strip:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}
.fd-song-strip i {
  position: absolute;
  top: 50%;
  width: 2px;
  height: 14px;
  margin: -7px 0 0 -1px;
  border-radius: 99px;
  background: var(--line);
}
.fd-song-strip i.is-minute {
  height: 26px;
  margin-top: -13px;
  background: var(--muted);
}
.fd-song-window {
  position: absolute;
  top: 3px;
  bottom: 3px;
  min-width: 10px;
  border-radius: 8px;
  border: 2px solid var(--lamp-info);
  background: var(--info-tint);
  box-sizing: border-box;
  pointer-events: none;
  box-shadow: 0 0 14px color-mix(in srgb, var(--lamp-info) 40%, transparent), inset 0 0 10px color-mix(in srgb, var(--lamp-info) 25%, transparent);
}
.fd-song-minutes {
  position: relative;
  height: 16px;
  color: var(--muted2);
  font: 500 12px var(--fd-body);
}
.fd-song-minutes span {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  font-variant-numeric: tabular-nums;
}
.fd-song-minutes span:first-child {
  transform: none;
}
.fd-song-start-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.fd-song-start-foot span {
  color: var(--muted2);
  font: 500 13px var(--fd-body);
  text-align: center;
}
.fd-song-start-foot button {
  min-width: 64px;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  font: 600 14px var(--fd-body);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-song-start-foot button:disabled {
  opacity: .4;
  cursor: default;
}
.fd-song-snippet {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}
.fd-song-snippet-go {
  min-height: 48px;
  border: 0;
  border-radius: 10px;
  background: var(--action-fill);
  color: var(--action-ink);
  font: 700 15px var(--fd-body);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-song-snippet-go.is-finding {
  opacity: .7;
  cursor: default;
}
.fd-song-snippet-go.is-playing {
  background: none;
  border: 1.5px solid var(--sun);
  color: var(--sun);
}
.fd-song-snippet-video {
  width: 100%;
  aspect-ratio: 16 / 9;
  min-height: 200px;
  border-radius: 10px;
  overflow: hidden;
  background: var(--ink0);
}
.fd-song-snippet-video[hidden] {
  display: none;
}
.fd-song-snippet-video iframe {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
}
.fd-song-snippet-note {
  margin: 0;
  color: var(--muted2);
  font: 500 12px/1.4 var(--fd-body);
}
.fd-song-snippet-note.is-error {
  color: var(--clay-text);
}
.fd-song-remove {
  justify-self: start;
  min-height: 44px;
  padding: 0 2px;
  border: 0;
  background: none;
  color: var(--clay-text);
  font: 600 13px var(--fd-body);
  cursor: pointer;
}
.fd-song button:focus-visible,
.fd-song-field input:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}

/* src/features/karaoke/songPicker.css */
.fd-ksong {
  gap: 10px;
}
.fd-ksong-song .fd-song-text strong {
  font: 900 20px/1.15 var(--fd-show);
}
.fd-ksong.is-compact .fd-song-pick {
  padding: 10px;
  gap: 12px;
}
.fd-ksong.is-compact .fd-ksong-song .fd-song-text strong {
  font-size: 18px;
}
.fd-ksong-status {
  min-height: 18px;
  color: var(--muted2);
  font: 500 13px/1.45 var(--fd-body);
}
.fd-ksong-status:empty {
  display: none;
}
.fd-ksong-status .is-error {
  color: var(--clay-text);
}
.fd-ksong-finding {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.fd-ksong-finding::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 99px;
  background: var(--lamp-info);
  box-shadow: 0 0 8px color-mix(in srgb, var(--lamp-info) 60%, transparent);
  animation: fd-ksong-lamp 1.2s ease-in-out infinite;
}
@keyframes fd-ksong-lamp {
  50% {
    opacity: .35;
  }
}
@media (prefers-reduced-motion: reduce) {
  .fd-ksong-finding::before {
    animation: none;
  }
}
.fd-ksong-retry {
  justify-self: start;
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  font: 600 14px var(--fd-body);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-ksong-videos {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.fd-ksong-video {
  display: grid;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper2);
  box-shadow: var(--glass-edge);
}
.fd-ksong-video.is-open {
  border-color: color-mix(in srgb, var(--lamp-info) 55%, transparent);
}
.fd-ksong-video-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 72px;
}
.fd-ksong-thumb {
  position: relative;
  flex-shrink: 0;
  width: 128px;
  height: 72px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  overflow: hidden;
  background: var(--ink0);
  cursor: pointer;
  box-shadow: inset 0 0 0 1px var(--ghost-line);
}
.fd-ksong-thumb img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.fd-ksong-thumb-glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--ink0) 30%, transparent);
}
.fd-ksong-thumb-glyph svg {
  width: 24px;
  height: 24px;
  fill: var(--bone);
  stroke: var(--bone);
  stroke-width: 2;
  stroke-linecap: round;
}
.fd-ksong-thumb[aria-pressed=true] {
  box-shadow: inset 0 0 0 2px var(--lamp-info);
}
.fd-ksong-thumb[aria-pressed=true] .fd-ksong-thumb-glyph {
  background: color-mix(in srgb, var(--ink0) 55%, transparent);
}
.fd-ksong-thumb:active {
  transform: scale(.97);
}
.fd-ksong-video-text {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 2px;
}
.fd-ksong-video-text strong {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  color: var(--ink);
  font: 700 15px/1.3 var(--fd-body);
}
.fd-ksong-video-text small {
  color: var(--muted2);
  font: 500 13px/1.3 var(--fd-body);
  font-variant-numeric: tabular-nums;
}
.fd-ksong-use {
  flex-shrink: 0;
  min-width: 64px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 99px;
  border: 1px solid color-mix(in srgb, var(--lamp-info) 55%, transparent);
  background: none;
  color: var(--lamp-info);
  font: 600 14px var(--fd-body);
  cursor: pointer;
}
.fd-ksong-use:active {
  background: var(--info-tint);
  border-color: var(--lamp-info);
}
.fd-ksong-use:disabled {
  opacity: .45;
  cursor: default;
}
.fd-ksong-use[aria-busy=true] {
  opacity: 1;
  background: var(--info-tint);
}
.fd-ksong-preview {
  display: grid;
  gap: 6px;
}
.fd-ksong-player {
  width: 100%;
  aspect-ratio: 16 / 9;
  min-height: 200px;
  border-radius: 10px;
  overflow: hidden;
  background: var(--ink0);
}
.fd-ksong-player iframe {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
}
.fd-ksong-paste {
  display: grid;
  gap: 4px;
  margin-top: 2px;
}
.fd-ksong-paste input {
  width: 100%;
  height: 48px;
  padding: 0 14px;
  border-radius: 10px;
  border: 1px solid var(--ghost-line);
  background: var(--bg);
  color: var(--ink);
  font: 500 16px var(--fd-body);
  outline: none;
  box-sizing: border-box;
  box-shadow: inset 0 2px 5px color-mix(in srgb, var(--ink0) 55%, transparent);
  -webkit-appearance: none;
  appearance: none;
}
.fd-ksong-paste input:focus {
  border-color: var(--lamp-info);
  box-shadow: 0 0 0 1px var(--lamp-info);
}
.fd-ksong-error {
  margin: 0;
  color: var(--clay-text);
  font: 500 13px/1.45 var(--fd-body);
}
.fd-ksong button:focus-visible,
.fd-ksong-paste input:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 2px;
}

/* src/features/karaoke/karaoke.css */
.fd-karaoke-game {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  background: var(--bg);
  color: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
  animation: fd-karaoke-in .28s ease-out both;
}
@keyframes fd-karaoke-in {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
.fd-karaoke-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: calc(env(safe-area-inset-top) + 8px) 12px 12px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  box-shadow: inset 0 3px 0 var(--lamp-live);
}
.fd-karaoke-count {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 3px;
}
.fd-karaoke-count small {
  color: var(--lamp-live-text);
  font: 900 21px/1.15 var(--fd-show);
  text-shadow: 0 0 14px color-mix(in srgb, var(--lamp-live) 45%, transparent);
}
.fd-karaoke-count b {
  font: 800 20px/1.1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}
.fd-karaoke-clock {
  flex-shrink: 0;
  min-width: 48px;
  text-align: right;
  font: 800 30px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}
.fd-karaoke-clock.is-low {
  color: var(--clay-text);
}
.fd-karaoke-close,
.fd-karaoke-more {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-karaoke-more.is-open {
  border-color: var(--lamp-info);
  background: var(--info-tint);
  color: var(--lamp-info);
}
.fd-karaoke-timebar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 6px;
  overflow: hidden;
  background: var(--bg);
}
.fd-karaoke-drain {
  position: absolute;
  inset: 0;
  display: block;
  transform-origin: left center;
  transform: scaleX(var(--drain-left));
  background: var(--lamp-live);
  box-shadow: 0 0 10px color-mix(in srgb, var(--lamp-live) 70%, transparent);
  animation: fd-karaoke-drain var(--drain-ms) linear var(--drain-wait, 0ms) both, fd-karaoke-drain-low 1ms step-start var(--drain-low) forwards;
}
@keyframes fd-karaoke-drain {
  from {
    transform: scaleX(var(--drain-left));
  }
  to {
    transform: scaleX(0);
  }
}
@keyframes fd-karaoke-drain-low {
  to {
    background: var(--clay);
    box-shadow: 0 0 10px var(--clay);
  }
}
.fd-karaoke-trayslot {
  min-height: 0;
}
.fd-karaoke-tray {
  display: grid;
  gap: 8px;
  margin: 10px 10px 0;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  box-shadow: var(--shadow-2), var(--glass-edge);
  animation: fd-karaoke-rise .2s ease-out both;
}
.fd-karaoke-tray .fd-karaoke-error {
  padding: 0 8px 6px;
}
.fd-karaoke-game.is-tray .fd-karaoke-body {
  visibility: hidden;
}
.fd-karaoke-body {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px 16px 18px;
}
@keyframes fd-karaoke-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}
@keyframes fd-karaoke-land {
  from {
    opacity: 0;
    transform: scale(.4) translateY(-8px);
  }
}
@keyframes fd-karaoke-word {
  0% {
    opacity: 0;
    transform: scale(1.7);
  }
  70% {
    opacity: 1;
    transform: scale(.96);
  }
  100% {
    transform: none;
  }
}
.fd-karaoke-song {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 12px;
  border: 1px solid var(--ghost-line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
  text-align: left;
  animation: fd-karaoke-rise .4s cubic-bezier(.2, .8, .2, 1) both;
}
.fd-karaoke-cover {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  overflow: hidden;
  background: var(--bg);
  color: var(--muted2);
  box-shadow: inset 0 2px 6px color-mix(in srgb, var(--ink0) 60%, transparent);
}
.fd-karaoke-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.fd-karaoke-song-text {
  min-width: 0;
  display: grid;
  gap: 5px;
}
.fd-karaoke-song-text b {
  font: 900 25px/1.1 var(--fd-show);
  color: var(--ink);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.fd-karaoke-song-text small {
  font: 800 15px/1.25 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted2);
  overflow-wrap: anywhere;
}
.fd-karaoke-song.is-locked {
  border-color: var(--lamp-info);
  box-shadow: var(--glass-edge), 0 0 0 1px var(--lamp-info);
}
.fd-karaoke-song.is-hero {
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: 16px;
  padding: 22px 18px 20px;
  text-align: center;
}
.fd-karaoke-song.is-hero .fd-karaoke-cover {
  width: min(180px, 46vw);
  height: min(180px, 46vw);
  border-radius: 14px;
}
.fd-karaoke-song.is-hero .fd-karaoke-song-text {
  justify-items: center;
  gap: 7px;
}
.fd-karaoke-song.is-hero b {
  font-size: 34px;
}
.fd-karaoke-song.is-hero small {
  font-size: 17px;
}
.fd-karaoke-song.is-sm {
  gap: 8px;
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
  animation: none;
}
.fd-karaoke-song.is-sm .fd-karaoke-cover {
  width: 30px;
  height: 30px;
  border-radius: 6px;
}
.fd-karaoke-song.is-sm .fd-karaoke-song-text {
  gap: 1px;
}
.fd-karaoke-song.is-sm b {
  font: 700 15px/1.25 var(--fd-body);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-karaoke-song.is-sm small {
  font: 700 12px/1.25 var(--fd-display);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-karaoke-room {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
  margin: 0;
  padding: 2px 0;
  list-style: none;
}
.fd-karaoke-room li {
  display: grid;
  border-radius: 50%;
}
.fd-karaoke-room li > * {
  opacity: .3;
  filter: saturate(.2);
  transition: opacity .3s ease, filter .3s ease;
}
.fd-karaoke-room li.is-lit > * {
  opacity: 1;
  filter: none;
}
.fd-karaoke-room li.is-lit {
  animation: fd-karaoke-land .36s var(--ease-land) both;
}
.fd-karaoke-room li.is-mine {
  box-shadow: 0 0 0 2px var(--you);
}
.fd-karaoke-room.is-big {
  gap: 12px;
  padding: 14px 0;
}
.fd-karaoke-body.is-watch {
  justify-content: center;
}
.fd-karaoke-body.is-pick {
  justify-content: center;
}
.fd-karaoke-body.is-pick.is-picking {
  justify-content: flex-start;
}
.fd-karaoke-broken {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--danger-line);
  border-radius: 12px;
  background: var(--clay-tint);
  color: var(--clay-text);
  font: 700 16px/1.3 var(--fd-body);
}
.fd-karaoke-body.is-stage,
.fd-karaoke-body.is-legendary {
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 14px;
}
.fd-karaoke-body.is-stage .fd-karaoke-song,
.fd-karaoke-body.is-legendary .fd-karaoke-song {
  width: 100%;
  max-width: 420px;
}
.fd-karaoke-word {
  margin: 0;
  font: 900 clamp(46px, 15vw, 68px)/1 var(--fd-show);
  color: var(--you);
  text-shadow: 0 0 18px color-mix(in srgb, var(--you) 40%, transparent);
}
.fd-karaoke-word.is-up {
  animation: fd-karaoke-word .38s var(--ease-land) both;
}
.fd-karaoke-eyebrow {
  margin: 0;
  font: 800 17px/1.2 var(--fd-display);
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--lamp-live-text);
}
.fd-karaoke-name {
  margin: -2px 0 0;
  font: 900 34px/1.08 var(--fd-show);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.fd-karaoke-face {
  display: grid;
  border-radius: 50%;
  animation: fd-karaoke-land .45s var(--ease-land) both;
}
.fd-karaoke-face.is-mine {
  box-shadow: 0 0 0 3px var(--you), var(--you-bloom);
}
.fd-karaoke-body.is-vote {
  gap: 14px;
  padding-bottom: 14px;
}
.fd-karaoke-singer {
  flex: 1 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
  text-align: center;
}
.fd-karaoke-singer > :first-child {
  animation: fd-karaoke-land .45s var(--ease-land) both;
}
.fd-karaoke-singer-name {
  max-width: 100%;
  font: 900 32px/1.06 var(--fd-show);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.fd-karaoke-singer .fd-karaoke-song.is-sm {
  max-width: 100%;
}
.fd-karaoke-vote-title {
  margin: 2px 0 -4px;
  font: 800 15px/1.2 var(--fd-display);
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--lamp-live-text);
}
.fd-karaoke-game.is-vote-closed .fd-karaoke-vote-title {
  color: var(--muted2);
}
.fd-karaoke-tiers {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-karaoke-tier {
  position: relative;
  width: 100%;
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 10px;
  border: 2px solid color-mix(in srgb, var(--ink0) 45%, var(--tier));
  border-radius: 14px;
  background: var(--tier);
  color: var(--tier-text);
  font: 800 22px/1.05 var(--fd-display);
  letter-spacing: .05em;
  text-transform: uppercase;
  text-align: center;
  cursor: pointer;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--bone) 24%, transparent), inset 0 -3px 0 color-mix(in srgb, var(--ink0) 32%, transparent);
  transition:
    transform .1s ease,
    box-shadow .18s ease,
    border-color .18s ease;
  -webkit-tap-highlight-color: transparent;
}
.fd-karaoke-tier:active:not(:disabled) {
  transform: scale(.97);
}
.fd-karaoke-tier.is-mine {
  border-color: var(--you);
  box-shadow: var(--you-bloom), inset 0 -3px 0 color-mix(in srgb, var(--ink0) 32%, transparent);
  animation: fd-karaoke-pick .3s var(--ease-land) both;
}
@keyframes fd-karaoke-pick {
  from {
    transform: scale(1.05);
  }
}
.fd-karaoke-tier:disabled {
  cursor: default;
  opacity: .55;
}
.fd-karaoke-tier:disabled.is-mine {
  opacity: 1;
}
.fd-karaoke-legendary {
  margin: 0;
  padding: 10px 24px 12px;
  border-radius: 14px;
  background: var(--tier);
  color: var(--tier-text);
  font: 900 clamp(42px, 13vw, 60px)/1 var(--fd-show);
  letter-spacing: .05em;
  text-transform: uppercase;
  transform: rotate(-4deg);
  box-shadow: inset 0 2px 0 color-mix(in srgb, var(--bone) 35%, transparent), inset 0 -4px 0 color-mix(in srgb, var(--ink0) 30%, transparent);
  animation: fd-karaoke-stamp .42s var(--ease-land) both;
}
@keyframes fd-karaoke-stamp {
  0% {
    opacity: 0;
    transform: scale(1.8) rotate(-12deg);
  }
  70% {
    opacity: 1;
    transform: scale(.96) rotate(-4deg);
  }
  100% {
    transform: rotate(-4deg);
  }
}
.fd-karaoke-body.is-reveal {
  padding-bottom: calc(env(safe-area-inset-bottom) + 20px);
}
.fd-karaoke-ranking {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.fd-karaoke-ranking li {
  min-height: 56px;
  display: grid;
  grid-template-columns: 42px auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 6px 12px 6px 6px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper);
}
.fd-karaoke-ranking li.is-shown {
  animation: fd-karaoke-rise .45s var(--ease-land) both;
}
.fd-karaoke-ranking li.is-ahead {
  background: none;
  border-style: dashed;
  border-color: var(--ghost-line);
}
.fd-karaoke-ranking li.is-mine {
  border-color: var(--you);
  background: var(--you-tint);
  box-shadow: var(--you-bloom);
}
.fd-karaoke-place {
  font: 800 21px/1 var(--fd-display);
  color: var(--muted2);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.fd-karaoke-ranking li.is-podium .fd-karaoke-place {
  color: var(--ink);
}
.fd-karaoke-ranking li.is-mine .fd-karaoke-place {
  color: var(--you);
}
.fd-karaoke-who {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.fd-karaoke-who b {
  font: 700 16px/1.2 var(--fd-body);
  overflow-wrap: anywhere;
}
.fd-karaoke-who small {
  font: 500 13px/1.25 var(--fd-body);
  color: var(--muted2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fd-karaoke-score {
  display: grid;
  justify-items: end;
  gap: 4px;
}
.fd-karaoke-score b {
  font: 800 26px/1 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.fd-karaoke-tierchip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted2);
  font: 800 13px/1.2 var(--fd-display);
  font-style: normal;
  letter-spacing: .06em;
  text-transform: uppercase;
  white-space: nowrap;
}
.fd-karaoke-tierlens {
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--tier);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink0) 40%, transparent), inset 0 2px 0 color-mix(in srgb, var(--bone) 25%, transparent);
}
.fd-karaoke-foot {
  display: grid;
  gap: 10px;
  padding: 10px 14px calc(env(safe-area-inset-bottom) + 12px);
  border-top: 1px solid var(--line);
  background: var(--chrome);
}
.fd-karaoke-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr);
  gap: 10px;
}
.fd-karaoke-actions > :only-child {
  grid-column: 1 / -1;
}
.fd-karaoke-primary,
.fd-karaoke-secondary {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 14px;
  font: 700 17px/1 var(--fd-body);
}
.fd-karaoke-primary {
  border: 0;
  background: var(--action-fill);
  color: var(--action-ink);
  cursor: pointer;
  box-shadow: var(--chip-bloom);
  transition: transform .12s ease, background .2s ease;
}
.fd-karaoke-primary:active:not(:disabled) {
  transform: scale(.97);
}
.fd-karaoke-primary:disabled {
  background: var(--paper2);
  color: var(--muted2);
  cursor: default;
  box-shadow: var(--glass-edge);
}
.fd-karaoke-primary.is-done {
  background: var(--info-tint);
  color: var(--lamp-info);
  box-shadow: inset 0 0 0 1px var(--lamp-info);
  cursor: default;
  animation: fd-karaoke-pick .4s var(--ease-land) both;
}
.fd-karaoke-primary.is-over {
  background: var(--paper2);
  color: var(--muted2);
  box-shadow: var(--glass-edge);
  cursor: default;
}
.fd-karaoke-secondary {
  border: 1px solid var(--ghost-line);
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
  box-shadow: var(--glass-edge);
}
.fd-karaoke-error {
  margin: 0;
  color: var(--clay-text);
  font: 600 14px/1.4 var(--fd-body);
}
.fd-karaoke-home {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 60px;
  margin: 12px 0 0;
  padding: 10px 14px;
  border: 1px solid var(--lamp-live);
  border-radius: 14px;
  background: color-mix(in srgb, var(--lamp-live) 6%, var(--paper));
  box-shadow: var(--live-bloom), var(--glass-edge);
  color: var(--ink);
