/* src/features/jersey/jersey.css */
.fd-jersey-stage {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 10px;
  margin: 0 0 16px;
  padding: 18px 12px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--bg);
  box-shadow: var(--glass-edge);
  overflow: hidden;
}
.fd-jersey-stage::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 3px dotted color-mix(in srgb, var(--bone) 18%, transparent);
  border-radius: 10px;
  pointer-events: none;
}
.fd-jersey-art {
  position: relative;
  width: min(220px, 70vw);
  height: auto;
  display: block;
  filter: drop-shadow(0 0 22px color-mix(in srgb, var(--bone) 16%, transparent));
}
.fd-jersey-cloth {
  fill: var(--paper2);
  stroke: var(--ghost-line);
  stroke-width: 1.5;
  stroke-linejoin: round;
}
.fd-jersey-collar {
  fill: none;
  stroke: var(--muted);
  stroke-width: 3;
  stroke-linecap: round;
}
.fd-jersey-tag {
  fill: var(--bone);
}
.fd-jersey-tag-text {
  fill: var(--ink0);
  font: 800 10px/1 var(--fd-display);
}
.fd-jersey-name {
  fill: var(--ink);
  font: 800 25px/1 var(--fd-display);
  letter-spacing: .1em;
}
.fd-jersey-num {
  fill: var(--ink);
  font: 800 108px/1 var(--fd-display);
}
.fd-jersey-name.is-empty,
.fd-jersey-num.is-empty {
  fill: var(--muted);
  opacity: .5;
}
.fd-jersey-status {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-jersey-status.is-ok {
  color: var(--lamp-info);
}
.fd-jersey-size {
  margin-top: 16px;
}
.fd-jersey-locked-size {
  margin: 0;
  color: var(--muted2);
  font: 500 14px/1.4 var(--fd-body);
}
.fd-jersey-locked-size strong {
  color: var(--ink);
}
.fd-profile-field input:disabled {
  opacity: .6;
}

/* src/ui/shell.css */
* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}
html {
  touch-action: manipulation;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
body {
  margin: 0;
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
@supports (-webkit-touch-callout:none) {
  input:not([type=range]):not([type=checkbox]):not([type=radio]),
  select,
  textarea {
    font-size: max(16px, 1em) !important;
  }
}
button:active:not(:disabled) {
  transform: scale(0.97);
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 2px solid var(--lamp-info);
  outline-offset: 3px;
}
input::placeholder {
  color: var(--muted);
}
@keyframes si-fall {
  to {
    transform: translateY(110vh) translateX(var(--drift)) rotate(720deg);
    opacity: 0.7;
  }
}
@keyframes si-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
@keyframes si-up {
  from {
    transform: translateY(26px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
@keyframes si-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes si-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes si-flag {
  0% {
    opacity: 0;
    transform: translateY(30px) scale(0.92);
  }
  60% {
    transform: translateY(-4px) scale(1.015);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes si-shine {
  0% {
    transform: translateX(-120%) skewX(-18deg);
  }
  100% {
    transform: translateX(240%) skewX(-18deg);
  }
}
@keyframes si-tick {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}
@keyframes si-pop {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(1.22);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes si-trophy {
  from {
    transform: rotateY(0deg);
  }
  to {
    transform: rotateY(360deg);
  }
}
@keyframes si-route {
  from {
    stroke-dashoffset: var(--len);
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes si-land {
  0%, 100% {
    r: 3.4;
    opacity: 1;
  }
  50% {
    r: 5.2;
    opacity: 0.55;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
  .fd-travel-motion {
    display: none;
  }
}
::-webkit-scrollbar {
  width: 0;
  height: 0;
}
.si-vh {
  min-height: 100vh;
  min-height: 100dvh;
}
.si-sheet {
  max-height: 90vh;
  max-height: 90dvh;
}

