/* src/ui/motion.css */
:root {
  --motion-fast:140ms;
  --motion-base:260ms;
  --motion-story:720ms;
  --motion-count:750ms;
  --motion-delta:1100ms;
  --motion-row:560ms;
  --motion-stamp:320ms;
  --motion-flight:340ms;
  --motion-card-flight:520ms;
  --motion-pop:320ms;
  --motion-sheet-in:260ms;
  --motion-sheet-out:200ms;
  --motion-settle:2400ms;
  --motion-beat:2000ms;
  --motion-reel:240ms;
  --ease-out:cubic-bezier(.2,.8,.2,1);
  --ease-land:cubic-bezier(.3,.7,.35,1.25);
  --ease-exit:cubic-bezier(.5,0,.75,.4);
  --ease-drum:cubic-bezier(.3,1.35,.5,1);
  --ease-drum-spin:cubic-bezier(.14,.62,.3,1.025);
}
@keyframes fd-beat {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: .3;
  }
}
@keyframes fd-beat-dot {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: .3;
    transform: scale(.75);
  }
}
@keyframes fd-beat-pop {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.5);
  }
}
@keyframes fd-beat-fill {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: .55;
  }
}
@keyframes fd-beat-lamp {
  0%, 100% {
    box-shadow: var(--lens-rim), 0 0 9px 1px color-mix(in srgb, var(--lamp-on) 60%, transparent);
  }
  50% {
    box-shadow: var(--lens-rim), 0 0 3px 0 color-mix(in srgb, var(--lamp-on) 35%, transparent);
  }
}
.fd-beat {
  animation: fd-beat var(--motion-beat) ease-in-out infinite;
}
.fd-beat-dot {
  display: inline-block;
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: fd-beat-dot var(--motion-beat) ease-in-out infinite;
}
.fd-beat-fill {
  position: relative;
  isolation: isolate;
  background: transparent;
}
.fd-beat-fill::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: var(--sun);
  animation: fd-beat-fill var(--motion-beat) ease-in-out infinite;
}
:root[data-fd-link=down] .fd-beat,
:root[data-fd-link=down] .fd-beat-dot,
:root[data-fd-link=down] .fd-beat-fill::before {
  animation: none;
}
:root[data-fd-link=down] .fd-beat-dot {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px var(--clay);
}
:root[data-fd-link=back] .fd-beat-dot {
  animation: fd-beat-pop var(--motion-pop) var(--ease-land);
}
@keyframes fd-delta-rise {
  0% {
    opacity: 0;
    transform: translateY(0);
  }
  15% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(-18px);
  }
}
.fd-motion-delta {
  pointer-events: none;
  font-variant-numeric: tabular-nums;
  opacity: 0;
  animation: fd-delta-rise var(--motion-delta) var(--ease-out) both;
}
.fd-motion-delta.is-up {
  color: var(--green);
}
.fd-motion-delta.is-down {
  color: var(--live2);
}
.fd-flight-layer {
  position: fixed;
  inset: 0;
  z-index: 600;
  pointer-events: none;
  overflow: hidden;
  contain: strict;
}
.fd-flight {
  position: fixed;
  pointer-events: none;
  transform-origin: 50% 50%;
  will-change: transform;
}
@keyframes fd-flight-hover {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-3px);
  }
}
.fd-flight.is-hover > * {
  animation: fd-flight-hover .66s ease-in-out infinite;
}
.fd-flight.is-coin {
  perspective: 240px;
}
@keyframes fd-scrim-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes fd-scrim-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes fd-sheet-rise {
  from {
    transform: translateY(var(--fd-sheet-from, 100%));
  }
  to {
    transform: none;
  }
}
@keyframes fd-sheet-fall {
  from {
    transform: none;
  }
  to {
    transform: translateY(var(--fd-sheet-from, 100%));
  }
}
@keyframes fd-sheet-swap {
  from {
    opacity: .4;
  }
  to {
    opacity: 1;
  }
}
.fd-sheet-overlay::before {
  animation: fd-scrim-in var(--motion-sheet-in) var(--ease-out) backwards;
}
.fd-sheet-overlay .si-sheet {
  animation: fd-sheet-rise var(--motion-sheet-in) var(--ease-out) backwards;
}
.fd-sheet-overlay.is-swap::before {
  animation: none;
}
.fd-sheet-overlay.is-swap .si-sheet {
  animation: fd-sheet-swap var(--motion-fast) ease-out backwards;
}
.fd-sheet-overlay.is-leaving {
  pointer-events: none;
}
.fd-sheet-overlay.is-leaving::before {
  animation: fd-scrim-out var(--motion-sheet-out) var(--ease-exit) both;
}
.fd-sheet-overlay.is-leaving .si-sheet {
  animation: fd-sheet-fall var(--motion-sheet-out) var(--ease-exit) both;
}
@media (min-width: 700px) {
  .fd-sheet-overlay {
    --fd-sheet-from:24px;
  }
  .fd-sheet-overlay .si-sheet {
    animation: fd-sheet-rise var(--motion-sheet-in) var(--ease-out) backwards, fd-scrim-in var(--motion-sheet-in) var(--ease-out) backwards;
  }
  .fd-sheet-overlay.is-leaving .si-sheet {
    animation: fd-sheet-fall var(--motion-sheet-out) var(--ease-exit) both, fd-scrim-out var(--motion-sheet-out) var(--ease-exit) both;
  }
}

/* src/features/check-in/arrival.css */
.fd-arrival {
  color-scheme: dark;
  width: 100%;
  flex: 1;
  padding: 36px 40px 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--fd-body);
  min-height: 100dvh;
}
.fd-arrival button,
.fd-arrival input {
  font: inherit;
}
.fd-arrival button:focus-visible,
.fd-arrival input:focus-visible,
.fd-arrival a:focus-visible {
  outline: 3px solid var(--lamp-info);
  outline-offset: 3px;
}
.fd-arrival-header {
  display: flex;
  gap: 16px 20px;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  padding-bottom: 26px;
}
.fd-arrival-mark {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font: 900 24px/1 var(--fd-show);
  color: var(--ink);
}
.fd-arrival-mark > span {
  color: var(--muted2);
  font: 800 13px/1 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-eyebrow,
.fd-arrival-progress {
  font: 800 13px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-arrival-progress {
  color: var(--lamp-info);
  font-variant-numeric: tabular-nums;
}
.fd-arrival-progress-track {
  width: 100%;
  display: flex;
  gap: 6px;
  margin-top: -4px;
}
.fd-arrival-progress-track span {
  height: 4px;
  flex: 1;
  border-radius: 99px;
  background: var(--paper2);
}
.fd-arrival-progress-track .is-complete {
  background: var(--lamp-info);
  box-shadow: 0 0 8px color-mix(in srgb, var(--lamp-info) 60%, transparent);
}
.fd-arrival-layout {
  display: grid;
  grid-template-columns: minmax(0, .92fr) minmax(0, 1fr);
  gap: 64px;
  padding: 22px 0 0;
  align-items: start;
}
.fd-arrival-aside {
  position: sticky;
  top: 40px;
}
.fd-invitation-art {
  position: relative;
  padding: 0 0 20px;
  border-radius: 18px;
  color: var(--ink);
  background: color-mix(in srgb, var(--lamp-live) 5%, var(--bg));
  border: 1px solid var(--ghost-line);
  box-shadow: var(--glass-edge), var(--shadow-2);
}
.fd-invitation-art .fd-chase {
  z-index: 2;
}
.fd-invitation-art > *:not(.fd-chase):not(.fd-invitation-seal) {
  position: relative;
  z-index: 1;
}
.fd-invitation-seal {
  z-index: 3;
}
.fd-invitation-scene {
  margin: 7px 7px 0;
  padding: 16px 16px 52px;
  border-radius: 10px 10px 0 0;
}
.fd-invitation-wordmark {
  font: 900 clamp(80px, 10vw, 120px)/.95 var(--fd-show);
  letter-spacing: .01em;
  color: var(--bone);
  text-shadow:
    3px 0 0 var(--ink0),
    -3px 0 0 var(--ink0),
    0 3px 0 var(--ink0),
    0 -3px 0 var(--ink0),
    2px 2px 0 var(--ink0),
    -2px 2px 0 var(--ink0),
    2px -2px 0 var(--ink0),
    -2px -2px 0 var(--ink0),
    0 6px 0 var(--ink0),
    0 0 28px color-mix(in srgb, var(--lamp-live) 70%, transparent);
}
.fd-invitation-wordmark > span {
  display: block;
}
.fd-invitation-wordmark > span + span {
  font-size: 1.3em;
  margin-top: -2px;
}
.fd-invitation-seal {
  position: absolute;
  width: 96px;
  height: 96px;
  right: 10px;
  top: 52px;
  transform: rotate(12deg);
  color: var(--sun);
  filter: drop-shadow(0 0 14px color-mix(in srgb, var(--sun) 45%, transparent));
}
.fd-invitation-seal svg {
  width: 100%;
  height: 100%;
}
.fd-invitation-seal > span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  color: var(--ink0);
}
.fd-invitation-seal strong {
  font: 900 46px/.9 var(--fd-display);
  letter-spacing: 0;
}
.fd-invitation-seal small {
  font: 800 12px/1 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
  margin-top: 3px;
}
.fd-invitation-edition {
  display: flex;
  justify-content: space-between;
  align-items: start;
  margin: 0;
  padding: 14px 22px 0;
  color: var(--muted2);
  font: 800 14px/1.35 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-invitation-edition > span:last-child {
  text-align: right;
}
.fd-arrival-heading h1 {
  font: 800 clamp(32px, 3.3vw, 40px)/1.02 var(--fd-display);
  letter-spacing: .01em;
  text-transform: uppercase;
  margin: 0;
  text-wrap: balance;
  outline: none;
}
.fd-arrival-heading:has(> h1:only-child) {
  margin-bottom: 20px;
}
.fd-arrival-heading p {
  font-size: 15px;
  line-height: 1.55;
  color: var(--muted2);
  margin: 12px 0 22px;
  text-wrap: pretty;
}
.fd-arrival-fields {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
.fd-arrival-fields:disabled {
  opacity: .7;
}
.fd-guest-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}
.fd-guest-list button {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 52px;
  padding: 12px 11px;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  text-align: left;
  border-radius: 10px;
  box-shadow: var(--glass-edge);
}
.fd-guest-list button[aria-pressed=true] {
  background: var(--you-tint);
  color: var(--you);
  border-color: var(--you);
  box-shadow: var(--you-bloom);
}
.fd-guest-index {
  font: 800 15px/1 var(--fd-display);
  color: var(--muted2);
}
.fd-guest-list button[aria-pressed=true] .fd-guest-index {
  color: var(--you);
}
.fd-guest-name {
  min-width: 0;
  overflow-wrap: anywhere;
}
.fd-arrival-actions {
  position: sticky;
  bottom: 0;
  background: var(--bg);
  padding: 18px 0 max(18px, env(safe-area-inset-bottom));
  margin-top: 12px;
  z-index: 2;
  box-shadow: 0 -1px 0 var(--line);
}
.fd-continue {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  width: 100%;
  border: 1px solid var(--action-fill);
  border-radius: 8px;
  background: var(--action-fill);
  color: var(--action-ink);
  padding: 16px 19px;
  font-size: 16px !important;
  font-weight: 700 !important;
  cursor: pointer;
  min-height: 56px;
  text-align: left;
  box-shadow: var(--chip-bloom);
}
.fd-continue > span:last-child {
  font-size: 22px;
  line-height: 1;
}
.fd-continue:disabled {
  cursor: default;
  background: var(--paper2);
  border-color: var(--line);
  color: var(--muted2);
  box-shadow: var(--glass-edge);
}
.fd-arrival-links {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
  font-size: 13px;
  color: var(--muted2);
  min-height: 44px;
}
.fd-text-button {
  background: none;
  color: var(--lamp-info);
  border: 0;
  padding: 8px 0;
  min-height: 44px;
  cursor: pointer;
  font-size: 14px !important;
  font-weight: 600 !important;
}
.fd-text-button:disabled {
  color: var(--muted);
  cursor: default;
}
.fd-save-error {
  border: 1px solid var(--danger-line);
  border-radius: 10px;
  padding: 10px 12px;
  margin: 0 0 12px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--clay-text);
  background: var(--clay-tint);
}
.fd-arrival-chapter {
  padding: 24px 0;
  border-top: 1px solid var(--line);
  display: flex;
  flex-direction: column;
}
.fd-arrival-chapter > strong {
  font: 900 220px/.9 var(--fd-display);
  letter-spacing: -.02em;
  color: transparent;
  -webkit-text-stroke: 3px var(--lamp-info);
  margin: 30px 0 24px -6px;
  filter: drop-shadow(0 0 18px color-mix(in srgb, var(--lamp-info) 35%, transparent));
}
.fd-chapter-name {
  font: 800 34px/1.05 var(--fd-display);
  letter-spacing: .02em;
  text-transform: uppercase;
}
.fd-chapter-date {
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  margin-top: 24px;
}
.fd-starting-stack {
  position: relative;
  padding: 20px 22px 22px;
  border-radius: 14px;
  background: var(--ink0);
  color: var(--bone);
  border: 1px solid var(--line);
  box-shadow: inset 0 3px 12px color-mix(in srgb, var(--ink0) 80%, transparent), var(--glass-edge);
}
.fd-starting-stack-sub {
  display: block;
  margin-top: 10px;
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-starting-stack > strong {
  display: flex;
  align-items: baseline;
  gap: 12px;
  font: 800 96px/.95 var(--fd-display);
}
.fd-starting-stack > strong > span:last-child {
  color: var(--sun);
  font: 800 18px/1 var(--fd-display);
  letter-spacing: .1em;
  text-transform: uppercase;
}
.fd-weekend-rules > div {
  display: flex;
  gap: 18px;
  border-bottom: 1px solid var(--line);
  padding: 18px 0;
}
.fd-weekend-rules > div > span {
  font: 800 18px/1.2 var(--fd-display);
  color: var(--lamp-info);
  margin-top: 1px;
}
.fd-weekend-rules h2,
.fd-details-panel h2 {
  font: 800 20px/1.1 var(--fd-display);
  letter-spacing: .04em;
  text-transform: uppercase;
  margin: 0 0 6px;
}
.fd-weekend-rules p {
  font-size: 14px;
  line-height: 1.55;
  color: var(--muted2);
  margin: 0;
}
.fd-arrival-map {
  margin-top: 28px;
}
.fd-destination-note {
  border-top: 1px solid var(--line);
  margin-top: 20px;
  padding: 18px 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.fd-destination-note > span {
  color: var(--muted2);
  font: 800 14px/1.2 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.fd-destination-note strong {
  font: 900 34px/1.05 var(--fd-show);
}
.fd-details-panel {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 18px;
  margin-top: 20px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
}
.fd-details-panel h2 {
  margin-bottom: 20px;
}
.fd-rating-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 14px;
  color: var(--muted2);
}
.fd-rating-group {
  margin-top: 24px;
}
.fd-rating-group .fd-eyebrow {
  margin: 0 0 4px;
  color: var(--ink);
  font-size: 16px;
}
.fd-rating-labels,
.fd-rating-row {
  display: grid;
  grid-template-columns: 95px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
}
.fd-rating-labels > div,
.fd-rating-options {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
}
.fd-rating-labels > div {
  font: 800 12px/1.2 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  text-align: center;
  color: var(--muted2);
  margin: 6px 0;
}
.fd-rating-row {
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.fd-rating-row strong {
  font-size: 14px;
  display: block;
}
.fd-rating-row small {
  display: block;
  font-size: 13px;
  color: var(--muted2);
  margin-top: 3px;
}
.fd-rating-options button {
  min-height: 44px;
  min-width: 0;
  border: 1px solid var(--line);
  background: var(--bg);
  color: var(--muted2);
  border-radius: 99px;
  cursor: pointer;
  padding: 0;
  font: 800 15px/1 var(--fd-display);
  box-shadow: inset 0 2px 4px color-mix(in srgb, var(--ink0) 50%, transparent);
}
.fd-rating-options .is-filled {
  background: var(--info-tint);
  color: var(--lamp-info);
  border-color: color-mix(in srgb, var(--lamp-info) 60%, transparent);
  box-shadow: none;
}
.fd-rating-options button[aria-pressed=true] {
  background: var(--lamp-info);
  color: var(--ink0);
  border-color: var(--lamp-info);
  box-shadow: 0 0 12px color-mix(in srgb, var(--lamp-info) 50%, transparent);
}
.fd-install {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--glass-edge);
}
.fd-install p {
  font-size: 14px;
  line-height: 1.6;
  color: var(--muted2);
}
@media (hover: hover) {
  .fd-guest-list button:hover:not([aria-pressed=true]) {
    border-color: var(--ghost-line);
  }
  .fd-continue:hover:not(:disabled) {
    filter: brightness(1.06);
  }
}
@media (prefers-reduced-motion: no-preference) {
  .fd-arrival-main {
    animation: fd-arrive .28s ease-out both;
  }
  .fd-guest-list button,
  .fd-continue {
    transition:
      background .16s,
      color .16s,
      box-shadow .16s,
      border-color .16s;
  }
  @keyframes fd-arrive {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}
@media (max-width: 759px) {
  .fd-arrival {
    padding: calc(22px + env(safe-area-inset-top)) 16px 0;
  }
  .fd-arrival-header {
    padding-bottom: 18px;
    gap: 14px;
  }
  .fd-arrival-layout {
    display: block;
    padding-top: 0;
  }
  .fd-arrival-aside {
    position: static;
  }
  .is-invitation .fd-arrival-aside {
    margin-bottom: 22px;
  }
  .fd-arrival-chapter {
    display: none;
  }
  .fd-invitation-art {
    padding: 0 0 18px;
  }
  .fd-invitation-scene {
    padding: 14px 12px 48px;
  }
  .fd-invitation-edition {
    padding: 14px 18px 0;
  }
  .fd-invitation-wordmark {
    font-size: clamp(64px, 19vw, 96px);
  }
  .fd-invitation-wordmark > span + span {
    font-size: 1.22em;
  }
  .fd-invitation-seal {
    right: 12px;
    top: 46px;
    width: 86px;
    height: 86px;
  }
  .fd-invitation-seal strong {
    font-size: 40px;
  }
  .fd-arrival-heading h1 {
    font-size: 34px;
  }
  .is-invitation .fd-arrival-heading h1 {
    font-size: 30px;
  }
  .fd-arrival-heading p {
    font-size: 15px;
    margin: 10px 0 18px;
  }
  .fd-guest-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
  }
  .fd-guest-list button {
    min-height: 48px;
    padding: 10px 9px;
    font-size: 14px;
    gap: 7px;
  }
  .fd-guest-index {
    font-size: 13px;
  }
  .fd-arrival-actions {
    padding-top: 14px;
  }
  .fd-starting-stack > strong {
    font-size: 84px;
  }
}
@media (max-width: 359px) {
  .fd-arrival {
    padding-left: 14px;
    padding-right: 14px;
  }
  .fd-guest-list button {
    padding: 10px 7px;
    gap: 5px;
    font-size: 13px;
  }
  .fd-invitation-seal {
    width: 74px;
    height: 74px;
    top: 44px;
    right: 6px;
  }
  .fd-invitation-seal strong {
    font-size: 34px;
  }
}
@media (max-width: 419px) {
  .fd-rating-row,
  .fd-rating-labels {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }
  .fd-rating-labels > span {
    display: none;
  }
  .fd-rating-labels > div {
    margin: 0;
  }
  .fd-rating-row strong,
  .fd-rating-row small {
    display: inline;
    margin: 0 8px 0 0;
  }
}

/* src/features/tv/tv-moments.css */
.tv-canvas[data-moment] :is(.tv-mast, .tv-rail, .tv-now, .tv-ticker, .tv-horizon) {
  opacity: 0;
  pointer-events: none;
  transition: opacity 420ms var(--ease-out);
}
.tv-takeover {
  position: fixed;
  left: 0;
  top: 0;
  width: 1920px;
  height: 1080px;
  z-index: 30;
  overflow: hidden;
  pointer-events: none;
}
.tv-take-dim {
  position: absolute;
  inset: 0;
  background: var(--night-deep);
  animation: tv-take-dim 900ms var(--ease-out) calc(var(--tl, 0ms) + 0ms) both;
}
@keyframes tv-take-dim {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes tv-take-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes tv-take-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
.tv-walkout {
  background: var(--night-deep);
  animation: tv-take-in 400ms var(--ease-out) calc(var(--tl) + 0ms) both;
}
.tv-walkout-dock {
  position: absolute;
  inset: 0;
  transform-origin: 1420px 52px;
  animation: tv-walk-dock 700ms var(--ease-exit) calc(var(--tl) + 8400ms) both;
}
@keyframes tv-walk-dock {
  from {
    transform: none;
    opacity: 1;
  }
  to {
    transform: scale(.14);
    opacity: 0;
  }
}
.tv-walkout-panel {
  position: absolute;
  inset: 28px;
  border-radius: 18px;
  overflow: hidden;
  background: var(--night);
}
.tv-walkout-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    var(--lg-bands),
    radial-gradient(
      74% 84% at 50% 46%,
      transparent 58%,
      color-mix(in srgb, var(--ink0) 40%, transparent) 100%),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 16%, transparent),
      transparent 42%,
      transparent 70%,
      color-mix(in srgb, var(--ink0) 26%, transparent));
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--ink0) 55%, transparent), inset 0 0 96px color-mix(in srgb, var(--ink0) 28%, transparent);
  border-radius: inherit;
  animation: tv-take-in 600ms var(--ease-out) calc(var(--tl) + 500ms) both;
}
.tv-walkout-flood {
  position: absolute;
  display: block;
  border-radius: 50%;
  background: var(--walk-color);
  will-change: transform;
  left: calc(var(--walk-x) - 28px - var(--walk-r));
  top: calc(var(--walk-y) - 28px - var(--walk-r));
  width: calc(var(--walk-r) * 2);
  height: calc(var(--walk-r) * 2);
  animation: tv-walk-flood 800ms cubic-bezier(.65, 0, .35, 1) calc(var(--tl) + 0ms) both;
}
@keyframes tv-walk-flood {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}
.tv-walkout-chase {
  animation: tv-take-in 240ms linear calc(var(--tl) + 700ms) both;
}
.tv-walkout-art {
  position: absolute;
  left: 150px;
  top: 220px;
  width: 640px;
  height: 640px;
  animation: tv-walk-art 520ms var(--ease-land) calc(var(--tl) + 250ms) both;
}
.tv-walkout-art img {
  display: block;
  width: 640px;
  height: 640px;
  object-fit: cover;
  border-radius: 18px;
  box-shadow: 0 0 0 8px var(--walk-ink), var(--shadow-3);
}
.tv-walkout-record {
  position: relative;
  display: block;
  width: 640px;
  height: 640px;
  border-radius: 50%;
  box-shadow: 0 0 0 8px var(--walk-ink), var(--shadow-3);
}
.tv-walkout-grooves,
.tv-walkout-sheen {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}
.tv-walkout-grooves {
  background:
    conic-gradient(
      from 0deg,
      transparent 0 71%,
      color-mix(in srgb, var(--bone) 7%, transparent) 72% 74%,
      transparent 75%),
    radial-gradient(
      circle,
      transparent 0 22%,
      color-mix(in srgb, var(--bone) 10%, var(--ink0)) 22.4% 23%,
      transparent 23.4%),
    repeating-radial-gradient(
      circle,
      var(--ink0) 0 3px,
      color-mix(in srgb, var(--bone) 7%, var(--ink0)) 3px 4px),
    var(--ink0);
  animation: tv-record-turn 4.8s linear calc(var(--tl) + 250ms) infinite;
}
.tv-walkout-label {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 280px;
  height: 280px;
  margin: -140px 0 0 -140px;
  line-height: 0;
