  padding: 12px 16px;
  border-radius: 10px;
  background: var(--tv-window);
  box-shadow: var(--tv-cut);
}
.tv-draft-order li > span {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.tv-draft-order small {
  font: 700 24px/1.2 var(--fd-body);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
}
.tv-draft-order li.is-back small::after {
  content: " \21a9";
}
.tv-draft-order b {
  font: 700 28px/1.25 var(--fd-body);
  color: var(--bone);
  white-space: nowrap;
  max-width: 190px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-draft-teams {
  flex: 1;
  min-height: 0;
  display: grid;
  gap: 18px;
}
.tv-draft-col {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  padding: 14px 22px 10px;
  border-radius: 14px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
}
.tv-draft-col.is-clock {
  border: 2px solid var(--lamp-live);
  padding: 13px 21px 9px;
  box-shadow: var(--live-bloom);
}
.tv-draft-col > header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 10px;
  border-bottom: 1.5px solid var(--ghost-line);
}
.tv-draft-captain {
  flex: 1;
  min-width: 0;
  font-size: 44px;
  line-height: 1.15;
  color: var(--bone);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-draft-count {
  font-size: 40px;
  line-height: 1.15;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.tv-draft-col ol {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-rows: repeat(var(--draft-rows, 5), minmax(0, 120px));
  align-content: start;
  margin: 0;
  padding: 0;
  list-style: none;
}
.tv-draft-seat {
  position: relative;
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 0;
  padding: 0 12px;
  margin: 0 -12px;
  border-bottom: 1px solid var(--line);
  border-radius: 10px;
}
.tv-draft-seat:last-child {
  border-bottom: 0;
}
.tv-draft-seat-chip {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 56px;
  height: 56px;
}
.tv-draft-seat-name {
  flex: 1;
  min-width: 0;
  font: 700 34px/1.3 var(--fd-body);
  color: var(--bone);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-draft-seat.is-latest {
  background: var(--ink-tint);
}
.tv-draft-seat-pick {
  font: 700 24px/1.2 var(--fd-body);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted2);
}
.tv-draft-seat.is-arriving > * {
  opacity: 0;
}
.tv-draft-slot {
  display: block;
}
.tv-draft-slot circle {
  fill: none;
  stroke: var(--ghost-line);
  stroke-width: 2;
  stroke-dasharray: 5 4;
}
.tv-draft-slot.is-next circle {
  fill: var(--ink-tint);
  stroke: var(--bone);
  stroke-dasharray: none;
}
.tv-draft-seat-open {
  font: 600 26px/1.25 var(--fd-body);
  color: var(--muted);
}
.tv-draft-seat-open.is-next {
  color: var(--bone);
  font-weight: 700;
}
.tv-draft-pool {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 24px;
  border-radius: 18px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
}
.tv-draft-wall {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
}
.tv-draft-wall-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 140px;
}
.tv-draft-wall-chip {
  display: block;
  width: 72px;
  height: 72px;
}
.tv-draft-wall-name {
  max-width: 100%;
  font: 700 26px/1.2 var(--fd-body);
  color: var(--bone);
  text-align: center;
  overflow-wrap: normal;
}
.tv-draft-flyer {
  position: absolute;
  z-index: 5;
  pointer-events: none;
  transform-origin: 50% 50%;
  will-change: transform;
}
.tv-draft.is-fresh .tv-draft-clock-copy {
  animation: tv-draft-turn var(--motion-base) var(--ease-out) both;
}
.tv-draft.is-passing .tv-draft-clock-chip {
  animation: tv-draft-chip .5s var(--ease-land) .45s both;
}
.tv-draft.is-fresh .tv-draft-col {
  transition: border-color var(--motion-base) ease-out .6s;
}
.tv-draft-seat.is-slam .tv-draft-seat-chip {
  animation: tv-draft-land var(--motion-stamp) var(--ease-land) both;
}
.tv-draft-seat.is-slam .tv-draft-seat-name {
  animation: tv-draft-slam var(--motion-stamp) var(--ease-land) both;
  transform-origin: 0 50%;
}
.tv-draft-seat.is-slam .tv-draft-seat-pick {
  animation: tv-draft-stamp var(--motion-stamp) var(--ease-land) .12s both;
}
@keyframes tv-draft-turn {
  from {
    opacity: .25;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-draft-chip {
  from {
    opacity: 0;
    transform: translateY(-40px) rotate(-60deg) scale(.6);
  }
  to {
    opacity: 1;
    transform: rotate(-9deg);
  }
}
@keyframes tv-draft-land {
  0% {
    transform: scale(1.18);
  }
  60% {
    transform: scale(.94);
  }
  100% {
    transform: none;
  }
}
@keyframes tv-draft-slam {
  0% {
    opacity: 0;
    transform: scale(1.35);
  }
  70% {
    opacity: 1;
    transform: scale(.97);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-draft-stamp {
  0% {
    opacity: 0;
    transform: scale(1.8) rotate(-8deg);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tv-draft *,
  .tv-draft *::before,
  .tv-draft *::after {
    animation: none !important;
    transition: none !important;
  }
  .tv-draft-flyer {
    display: none;
  }
}
.tv-draft .tv-draft-who,
.tv-draft .tv-draft-captain {
  text-transform: none;
}

/* src/features/tv/tv-podium.css */
.tv-podium-stage {
  position: relative;
  flex: 1;
  min-width: 0;
  isolation: isolate;
  --keyline:2px 0 0 var(--ink0),
    -2px 0 0 var(--ink0),
    0 2px 0 var(--ink0),
    0 -2px 0 var(--ink0),
    2px 2px 0 var(--ink0),
    -2px 2px 0 var(--ink0),
    2px -2px 0 var(--ink0),
    -2px -2px 0 var(--ink0),
    0 4px 0 var(--ink0);
}
.tv-podium-title {
  position: absolute;
  z-index: 4;
  left: var(--tv-edge);
  right: var(--tv-edge);
  top: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 26px;
  animation: tv-podium-title .6s var(--ease-out) calc(var(--tl) + 0ms) both;
}
.tv-podium-event {
  line-height: 1.12;
  color: var(--bone);
  text-shadow: var(--keyline);
  white-space: nowrap;
  text-align: left;
}
.tv-podium-title .fd-gamemark,
.tv-podium-title > :first-child {
  flex-shrink: 0;
  filter: drop-shadow(0 4px 0 var(--ink0));
}
@keyframes tv-podium-title {
  from {
    opacity: 0;
    transform: translateY(-18px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-podium-floor {
  position: absolute;
  z-index: 0;
  left: 120px;
  right: 120px;
  height: 2px;
  pointer-events: none;
  background:
    linear-gradient(
      90deg,
      transparent,
      color-mix(in srgb, var(--bone) 28%, transparent) 20% 80%,
      transparent);
}
.tv-podium-floor::after {
  content: "";
  position: absolute;
  left: 6%;
  right: 6%;
  top: 2px;
  height: 46px;
  background:
    radial-gradient(
      50% 100% at 50% 0,
      color-mix(in srgb, var(--ink0) 70%, transparent),
      transparent);
}
.tv-step {
  position: absolute;
  z-index: 2;
  --ink-place:var(--muted);
  --light:var(--ink-place);
  animation: tv-step-rise .62s var(--ease-out) calc(var(--tl) + var(--rise)) both;
}
.tv-step.is-p1 {
  z-index: 3;
  --ink-place:var(--sun);
}
.tv-step.is-p2 {
  --ink-place:var(--silver);
}
.tv-step.is-p3 {
  --ink-place:var(--bronze);
}
.tv-step.is-lit {
  --light:var(--win);
}
@keyframes tv-step-rise {
  from {
    opacity: 0;
    transform: translateY(70px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-step-lid {
  position: absolute;
  z-index: 2;
  left: 0;
  right: 0;
  top: 0;
  height: var(--lid);
  pointer-events: none;
  clip-path: polygon(5% 0, 95% 0, 100% 100%, 0 100%);
  background:
    linear-gradient(
      0deg,
      color-mix(in srgb, var(--bone) 55%, transparent) 0 1.5px,
      transparent 1.5px),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 7%, var(--bg)),
      color-mix(in srgb, var(--ink-place) 22%, var(--paper2)));
}
.tv-step.is-p2 .tv-step-lid {
  clip-path: polygon(5% 0, 100% 0, 100% 100%, 0 100%);
}
.tv-step.is-p3 .tv-step-lid {
  clip-path: polygon(0 0, 95% 0, 100% 100%, 0 100%);
}
.tv-step.is-lit .tv-step-lid {
  background:
    linear-gradient(
      0deg,
      color-mix(in srgb, var(--bone) 65%, transparent) 0 1.5px,
      transparent 1.5px),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--win) 22%, var(--bg)),
      color-mix(in srgb, var(--win) 46%, var(--paper2)));
}
.tv-step-face {
  position: absolute;
  z-index: 1;
  left: 0;
  right: 0;
  top: var(--lid);
  bottom: 0;
  overflow: hidden;
  overflow: clip;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding-top: 6px;
  border-radius: 0 0 6px 6px;
  background:
    var(--lg-bands),
    var(--lg-fall),
    var(--lg-caustic),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--paper2) 70%, var(--bg)),
      color-mix(in srgb, var(--ink0) 70%, var(--bg)));
  box-shadow:
    var(--lg-lip),
    var(--lg-fringe),
    var(--shadow-2);
}
.tv-step.is-p2 .tv-step-face {
  border-bottom-right-radius: 0;
  box-shadow:
    var(--lg-lip),
    var(--lg-fringe),
    inset -2px 0 0 var(--ink0),
    var(--shadow-2);
}
.tv-step.is-p3 .tv-step-face {
  border-bottom-left-radius: 0;
  box-shadow:
    var(--lg-lip),
    var(--lg-fringe),
    inset 2px 0 0 var(--ink0),
    var(--shadow-2);
}
.tv-step-glow {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background:
    radial-gradient(
      75% 60% at 50% 0,
      color-mix(in srgb, var(--light) 34%, transparent),
      transparent 78%),
    radial-gradient(
      70% 45% at 50% 108%,
      color-mix(in srgb, var(--light) 30%, transparent),
      transparent 80%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--light) 42%, transparent), inset 0 18px 30px -18px color-mix(in srgb, var(--light) 55%, transparent);
  animation: tv-step-light .5s ease-out calc(var(--tl) + var(--beat)) both;
}
.tv-step.is-lit .tv-step-glow {
  background:
    radial-gradient(
      80% 66% at 50% 0,
      color-mix(in srgb, var(--win) 58%, transparent),
      transparent 80%),
    radial-gradient(
      75% 50% at 50% 108%,
      color-mix(in srgb, var(--win) 44%, transparent),
      transparent 80%),
    color-mix(in srgb, var(--win) 10%, transparent);
}
.tv-step.is-empty .tv-step-glow {
  display: none;
}
@keyframes tv-step-light {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.tv-step-num {
  position: relative;
  line-height: 1;
  color: color-mix(in srgb, var(--ink-place) 80%, var(--bone));
  text-shadow: 0 3px 0 var(--ink0), 0 -1px 0 color-mix(in srgb, var(--bone) 30%, transparent);
}
.tv-step.is-p1 .tv-step-num {
  font-size: 168px;
}
.tv-step.is-p2 .tv-step-num {
  font-size: 120px;
}
.tv-step.is-p3 .tv-step-num {
  font-size: 72px;
}
.tv-step.is-empty .tv-step-num {
  color: color-mix(in srgb, var(--bone) 22%, transparent);
  text-shadow: 0 2px 0 var(--ink0);
}
.tv-step.is-p1.is-filled .tv-step-num {
  color: var(--sun);
  text-shadow: 0 3px 0 var(--ink0), 0 0 30px color-mix(in srgb, var(--sun) 45%, transparent);
  animation: tv-step-num-lit .5s ease-out calc(var(--tl) + var(--beat)) both;
}
@keyframes tv-step-num-lit {
  from {
    color: color-mix(in srgb, var(--sun) 40%, var(--bone));
    text-shadow: 0 3px 0 var(--ink0);
  }
}
.tv-step-amount {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  font: 800 56px/1.12 var(--fd-display);
  letter-spacing: .01em;
  font-variant-numeric: tabular-nums;
  color: var(--sun);
  text-shadow: 0 2px 0 var(--ink0);
  animation: tv-step-stamp .34s var(--ease-land) calc(var(--tl) + var(--beat) + 220ms) both;
}
.tv-step.is-p2 .tv-step-amount,
.tv-step.is-p3 .tv-step-amount {
  font-size: 40px;
}
.tv-step-amount .fd-reel {
  font-size: .8em;
  align-self: center;
}
.tv-step-sign {
  align-self: center;
  margin-right: -4px;
}
.tv-step-amount small {
  font: 700 28px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted2);
}
@keyframes tv-step-stamp {
  0% {
    opacity: 0;
    transform: scale(1.6);
  }
  60% {
    opacity: 1;
    transform: scale(.96);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
.tv-step-sweep {
  position: absolute;
  inset: -10% -70%;
  z-index: 2;
  pointer-events: none;
  background: var(--lg-sweep);
  transform: translateX(-80%);
  opacity: 0;
  animation: tv-step-sweep 1.1s var(--ease-out) calc(var(--tl) + var(--sweep) + var(--rise)) both;
}
@keyframes tv-step-sweep {
  0% {
    opacity: 1;
    transform: translateX(-80%);
  }
  100% {
    opacity: 1;
    transform: translateX(80%);
  }
}
.tv-step-pool {
  position: absolute;
  z-index: 0;
  left: -4%;
  right: -4%;
  top: 100%;
  height: 58px;
  pointer-events: none;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--light) 24%, transparent),
      transparent 90%);
  -webkit-mask-image:
    linear-gradient(
      90deg,
      transparent,
      var(--ink0) 22%,
      var(--ink0) 78%,
      transparent);
  mask-image:
    linear-gradient(
      90deg,
      transparent,
      var(--ink0) 22%,
      var(--ink0) 78%,
      transparent);
  animation: tv-step-light .6s ease-out calc(var(--tl) + var(--beat)) both;
}
.tv-step.is-lit .tv-step-pool {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--win) 40%, transparent),
      transparent 90%);
}
.tv-step.is-empty .tv-step-pool {
  display: none;
}
.tv-step-shaft {
  position: absolute;
  z-index: 0;
  left: -10%;
  right: -10%;
  bottom: calc(100% - var(--lid) - 4px);
  height: 760px;
  pointer-events: none;
  clip-path: polygon(38% 0, 62% 0, 100% 100%, 0 100%);
  background:
    linear-gradient(
      180deg,
      transparent 8%,
      color-mix(in srgb, var(--win, var(--bone)) 14%, transparent) 70%,
      color-mix(in srgb, var(--win, var(--bone)) 24%, transparent));
  -webkit-mask-image:
    linear-gradient(
      90deg,
      transparent 4%,
      var(--ink0) 34%,
      var(--ink0) 66%,
      transparent 96%);
  mask-image:
    linear-gradient(
      90deg,
      transparent 4%,
      var(--ink0) 34%,
      var(--ink0) 66%,
      transparent 96%);
  transform-origin: 50% 100%;
  animation: tv-step-shaft .8s var(--ease-out) calc(var(--tl) + var(--beat)) both;
}
.tv-step:not(.is-lit) .tv-step-shaft {
  background:
    linear-gradient(
      180deg,
      transparent 8%,
      color-mix(in srgb, var(--bone) 8%, transparent) 70%,
      color-mix(in srgb, var(--bone) 13%, transparent));
}
@keyframes tv-step-shaft {
  from {
    opacity: 0;
    transform: scaleY(.4);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-step.is-p1.is-filled .tv-step-face::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 0 3px var(--win, var(--sun)), inset 0 0 60px color-mix(in srgb, var(--win, var(--sun)) 50%, transparent);
  opacity: 0;
  animation: tv-step-flash 1s ease-out calc(var(--tl) + var(--beat) + 120ms) both;
}
@keyframes tv-step-flash {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
.tv-step-who {
  position: absolute;
  z-index: 3;
  left: 22px;
  right: 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 14px;
  animation: tv-who-drop .52s var(--ease-land) calc(var(--tl) + var(--beat)) both;
}
.tv-step.is-p1 .tv-step-who {
  animation: tv-who-slam .64s var(--ease-land) calc(var(--tl) + var(--beat)) both;
}
@keyframes tv-who-drop {
  0% {
    opacity: 0;
    transform: translateY(-90px);
  }
  55% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-who-slam {
  0% {
    opacity: 0;
    transform: translateY(-40px) scale(1.35);
  }
  50% {
    opacity: 1;
    transform: scale(.97);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
.tv-step-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  min-width: 0;
  max-width: 100%;
}
.tv-step-faces {
  display: grid;
  gap: 14px;
  justify-content: center;
}
.tv-step-face-chip {
  display: block;
  border-radius: 50%;
  line-height: 0;
  box-shadow: 0 14px 18px -8px color-mix(in srgb, var(--ink0) 85%, transparent);
}
.tv-step-name {
  line-height: 1.12;
  color: var(--bone);
  text-align: center;
  white-space: nowrap;
  text-shadow: var(--keyline);
}
@media (prefers-reduced-motion: reduce) {
  .tv-podium-title,
  .tv-step,
  .tv-step-glow,
  .tv-step-num,
  .tv-step-amount,
  .tv-step-pool,
  .tv-step-shaft,
  .tv-step-who,
  .tv-step.is-p1 .tv-step-who {
    animation: none;
  }
  .tv-step-sweep,
  .tv-step.is-p1.is-filled .tv-step-face::before {
    animation: none;
    opacity: 0;
  }
}
.tv-rail-slot {
  position: relative;
}
.tv-rail {
  position: absolute;
  left: var(--tv-edge);
  right: var(--tv-edge);
  bottom: var(--tv-safe-y);
  height: 84px;
  display: flex;
  align-items: center;
  padding: 0 var(--rail-pad);
  border-radius: 18px;
  overflow: hidden;
  overflow: clip;
  background:
    var(--lg-bands),
    var(--lg-fall),
    color-mix(in srgb, var(--ink0) 82%, var(--bg));
  box-shadow:
    var(--lg-lip),
    var(--lg-fringe),
    var(--shadow-2);
  animation: tv-rail-in .5s var(--ease-out) calc(var(--tl) + var(--rail-at)) both;
}
@keyframes tv-rail-in {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-rail-tag {
  flex-shrink: 0;
}
.tv-rail-total {
  flex-shrink: 0;
  font: 800 56px/1.1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--green);
  animation: tv-step-stamp .34s var(--ease-land) calc(var(--tl) + var(--rail-at) + 160ms) both;
}
.tv-rail-total {
  display: flex;
  align-items: center;
  gap: 2px;
}
.tv-rail-total .fd-reel {
  font-size: .8em;
}
.tv-rail-cells {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--rail-gap);
}
.tv-rail-cell {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  animation: tv-rail-cell .4s var(--ease-out) calc(var(--tl) + var(--rail-at) + 260ms + var(--i) * 70ms) both;
}
@keyframes tv-rail-cell {
  from {
    opacity: 0;
    transform: translateX(-24px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-rail-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.tv-rail-name {
  font: 800 28px/1.15 var(--fd-display);
  letter-spacing: .01em;
  color: var(--bone);
  white-space: nowrap;
}
.tv-rail-paid {
  font: 800 32px/1.1 var(--fd-display);
  font-variant-numeric: tabular-nums;
  color: var(--green);
  white-space: nowrap;
}
.tv-rail.is-bare .tv-rail-cell {
  flex-direction: column;
  gap: 2px;
}
.tv-rail.is-bare .tv-rail-paid {
  font-size: 24px;
}
.tv-rail-more {
  justify-content: center;
  font: 800 32px/1 var(--fd-display);
  color: var(--muted2);
}
@media (prefers-reduced-motion: reduce) {
  .tv-rail,
  .tv-rail-total,
  .tv-rail-cell {
    animation: none;
  }
}

/* src/features/gags/gags.css */
.tv-canvas[data-moment~=gag] > .tv-main {
  animation: tv-gag-under var(--gag-ms, 4000ms) linear var(--gag-tl, 0ms) both;
}
@keyframes tv-gag-under {
  0% {
    opacity: 1;
  }
  6% {
    opacity: 0;
  }
  89% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
.tv-gag {
  overflow: hidden;
}
@media (prefers-reduced-motion: reduce) {
  .tv-canvas[data-moment~=gag] > .tv-main {
    opacity: 0;
  }
}

/* src/features/gags/highlights.css */
.tv-pane.tv-highlight-pane {
  align-items: center;
  justify-content: center;
  padding-top: 8px;
  padding-bottom: 12px;
  --ba:none;
  animation: var(--ba);
}
.tv-highlight {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
  padding: 16px 16px 14px;
  --ba:tv-highlight-in 560ms var(--ease-out) calc(var(--tl) + 0ms) both;
  animation: var(--ba);
}
@keyframes tv-highlight-in {
  from {
    opacity: 0;
    transform: translateY(22px) scale(.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-highlight-screen {
  position: relative;
  flex: none;
  border-radius: 10px;
  overflow: hidden;
  background: var(--tv-window);
  box-shadow: var(--tv-cut);
}
.tv-highlight-screen > .bit-stage {
  position: absolute;
  inset: 0;
}
.tv-highlight-foot {
  display: flex;
  align-items: center;
  gap: 28px;
  min-height: 48px;
  padding: 0 10px;
}
.tv-highlight-foot .tv-status {
  font-size: 30px;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.tv-highlight-event {
  min-width: 0;
  font: 800 36px/1.15 var(--fd-display);
  letter-spacing: .02em;
  color: var(--bone);
  white-space: nowrap;
}

/* src/features/tv/tv-sound.css */
.tv-sound-chip {
  position: absolute;
  top: 14px;
  right: calc(var(--tv-edge, 64px) + 210px);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 18px;
  height: 76px;
  padding: 0 30px 0 22px;
  border: 3px solid var(--lamp-live);
  border-radius: 99px;
  background: var(--night-deep);
  color: var(--bone);
  font: 600 26px/1 var(--fd-body);
  box-shadow: var(--shadow-3);
  cursor: pointer;
  text-align: left;
  white-space: nowrap;
}
.tv-sound-chip svg {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  color: var(--lamp-live-text);
}
.tv-sound-chip-text {
  display: flex;
  align-items: baseline;
  gap: 16px;
}
.tv-sound-chip-text b {
  font-size: 44px;
  font-weight: 900;
  line-height: 1.15;
  color: var(--bone);
}
.tv-sound-chip-text span {
  font: 600 26px/1.2 var(--fd-body);
  color: var(--muted2);
}
.tv-sound-chip:focus-visible {
  outline: 3px solid var(--bone);
  outline-offset: 3px;
}
.tv-early {
  position: fixed;
  z-index: 75;
  bottom: calc(8px + env(safe-area-inset-bottom));
  left: 12px;
  display: flex;
  align-items: center;
  gap: 2px;
  min-height: 44px;
  padding: 0 4px 0 14px;
  border-radius: 10px;
  background: var(--paper);
  color: var(--ink);
  border: 1.5px solid var(--ghost-line);
  font: 700 15px/1 var(--fd-body);
  letter-spacing: .04em;
  transition: opacity .3s;
}
.tv-early.is-idle:not(:focus-within) {
  opacity: 0;
  pointer-events: none;
}
.tv-early > span {
  margin-right: 6px;
  white-space: nowrap;
}
.tv-early output {
  font-variant-numeric: tabular-nums;
}
.tv-early button {
  min-width: 44px;
  min-height: 40px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  font: 700 20px/1 var(--fd-body);
  cursor: pointer;
}
.tv-early button:disabled {
  color: var(--disabled);
  cursor: default;
}
.tv-early button:focus-visible {
  outline: 2px solid var(--bone);
  outline-offset: 1px;
}

/* src/features/tv/tv-showdown.css */
.tv-showdown {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 64px 64px 54px;
  animation: tv-take-out var(--motion-lift, 500ms) var(--ease-exit) calc(var(--tl) + var(--out)) forwards;
}
.tv-showdown-glass {
  position: absolute;
  inset: 0;
  background: var(--night-deep);
  animation: tv-take-dim 700ms var(--ease-out) calc(var(--tl) + 0ms) both;
}
.tv-showdown-chase {
  --chase:var(--lamp-live);
  animation: tv-take-in 200ms linear calc(var(--tl) + 820ms) both;
}
.tv-showdown-title {
  position: relative;
  --lamp:var(--lamp-live);
  color: var(--bone);
  font-size: 76px;
  line-height: 1.15;
  text-shadow: 0 0 1px var(--lamp-live), 0 0 26px color-mix(in srgb, var(--lamp-live) 55%, transparent);
  animation: tv-take-in 420ms var(--ease-out) calc(var(--tl) + 120ms) both, tv-showdown-under 900ms steps(1, end) calc(var(--tl) + var(--fire));
}
.tv-showdown-ring {
  animation: tv-showdown-under 900ms steps(1, end) calc(var(--tl) + var(--fire));
}
@keyframes tv-showdown-under {
  0%, 34% {
    visibility: hidden;
  }
  35%, 100% {
    visibility: visible;
  }
}
.tv-showdown-ring {
  position: relative;
  width: 100%;
  margin: auto 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: start;
  gap: 40px;
}
.tv-showdown-side {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  text-align: center;
}
.tv-showdown-side.is-left {
  animation: tv-showdown-left 420ms cubic-bezier(.2, .9, .3, 1) calc(var(--tl) + 200ms) both;
}
.tv-showdown-side.is-right {
  animation: tv-showdown-right 420ms cubic-bezier(.2, .9, .3, 1) calc(var(--tl) + 420ms) both;
}
@keyframes tv-showdown-left {
  from {
    opacity: 0;
    transform: translateX(-900px) skewX(12deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-showdown-right {
  from {
    opacity: 0;
    transform: translateX(900px) skewX(-12deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-showdown-chip {
  position: relative;
  line-height: 0;
  transition: opacity .6s var(--ease-out);
}
.tv-showdown-side.is-lost .tv-showdown-chip {
  opacity: .6;
}
.tv-showdown-name {
  max-width: 100%;
  color: var(--bone);
  line-height: 1.2;
  white-space: nowrap;
}
.tv-showdown-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 132px;
}
.tv-showdown-take {
  margin-top: -6px;
  color: var(--sun);
  font: 800 56px/1.15 var(--fd-display);
  font-variant-numeric: tabular-nums;
  animation: tv-take-in 360ms var(--ease-out) both;
}
.tv-showdown-lamp {
  --lamp:var(--lamp-live);
  width: 40px;
  height: 40px;
}
.tv-showdown-time {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  padding: 12px 20px 10px;
  border-radius: 14px;
  background: var(--tv-window, color-mix(in srgb, var(--ink0) 88%, transparent));
  box-shadow: var(--window-bezel);
  color: var(--bone);
  font: 800 72px/1 var(--fd-display);
  animation: tv-take-in 300ms var(--ease-out) calc(var(--tr) + 250ms) both;
}
.tv-showdown-time.is-won {
  font-size: 96px;
}
.tv-showdown-time small {
  color: var(--muted2);
  font: 800 32px/1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
}
.tv-showdown-foul {
  color: var(--clay-text);
  font-size: 88px;
  line-height: 1.2;
  animation: tv-take-in 300ms var(--ease-out) both;
}
.tv-showdown-stamp {
  position: absolute;
  left: 50%;
  top: 10px;
  z-index: 2;
  padding: 8px 22px 6px;
  border: 6px solid var(--sun);
  border-radius: 14px;
  background: color-mix(in srgb, var(--ink0) 72%, transparent);
  color: var(--sun);
  font-size: 88px;
  line-height: 1;
  letter-spacing: .04em;
  white-space: nowrap;
  transform: translate(-50%, -50%) rotate(-8deg);
  animation: tv-showdown-stamp 380ms var(--ease-land) calc(var(--tr) + 1250ms) both;
}
@keyframes tv-showdown-stamp {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) rotate(-8deg) scale(2.2);
  }
  70% {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-8deg) scale(.94);
  }
}
.tv-showdown-tie {
  position: relative;
  margin-top: 24px;
  padding: 8px 26px 6px;
  border: 6px solid var(--bone);
  border-radius: 14px;
  color: var(--bone);
  font-size: 88px;
  line-height: 1;
  transform: rotate(-6deg);
  animation: tv-take-in 380ms var(--ease-land) both;
}
.tv-showdown-mid {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 56px;
  padding-top: 40px;
}
.tv-showdown-antes {
  display: flex;
  align-items: flex-end;
  gap: 22px;
  min-height: 230px;
  animation: tv-showdown-antes 360ms var(--ease-land) calc(var(--tl) + 820ms) both;
}
@keyframes tv-showdown-antes {
  from {
    opacity: 0;
    transform: translateY(-60px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-showdown-ante {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.tv-showdown-ante small {
  color: var(--sun);
  font: 800 40px/1.15 var(--fd-display);
  font-variant-numeric: tabular-nums;
}
.tv-showdown-antes.is-to-left .tv-showdown-ante,
.tv-showdown-antes.is-to-right .tv-showdown-ante {
  opacity: 0;
  animation: tv-showdown-take-left 650ms var(--ease-exit) var(--slide-at, 0ms) both;
}
.tv-showdown-antes.is-to-right .tv-showdown-ante {
  animation-name: tv-showdown-take-right;
}
@keyframes tv-showdown-take-left {
  from {
    opacity: 1;
    transform: none;
  }
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translate(-470px, -120px) scale(.5);
  }
}
@keyframes tv-showdown-take-right {
  from {
    opacity: 1;
    transform: none;
  }
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translate(470px, -120px) scale(.5);
  }
}
.tv-showdown-lamps {
  display: flex;
  gap: 44px;
}
.tv-showdown-count {
  --lamp:var(--lamp-live);
  width: 60px;
  height: 60px;
  box-shadow: var(--lens-rim), 0 0 36px 6px color-mix(in srgb, var(--lamp-on) 55%, transparent);
  animation: tv-showdown-lamp 90ms steps(1, start) both, tv-showdown-spent 1ms steps(1, start) calc(var(--tl) + var(--fire)) forwards;
}
@keyframes tv-showdown-spent {
  to {
    background: var(--lens-spent);
    box-shadow: var(--lens-rim);
  }
}
@keyframes tv-showdown-lamp {
  from {
    background: var(--lens-off);
    box-shadow: var(--lens-rim);
  }
  to {
    background: var(--lens-lit);
  }
}
.tv-showdown-flash {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  background: var(--lamp-live);
  opacity: 0;
  animation: tv-showdown-flash 900ms var(--ease-out) calc(var(--tl) + var(--fire)) forwards;
}
.tv-showdown-flash span {
  color: var(--ink0);
  font-size: 300px;
  line-height: 1.15;
}
@keyframes tv-showdown-flash {
  0%, 35% {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tv-showdown,
  .tv-showdown *,
  .tv-showdown-glass {
    animation: none !important;
  }
}

/* src/features/tv/tv-geo.css */
.tv-geo {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 600px;
  gap: 32px;
  padding: 16px 64px 20px;
}
.tv-geo-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  border-radius: 18px;
  overflow: hidden;
  background: var(--night-deep);
  border: 1px solid var(--ghost-line);
}
.tv-geo-photo {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  animation: si-fade .6s ease-out both;
}
.tv-geo-side {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 26px 28px;
  border-radius: 18px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge);
}
.tv-geo-head {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.tv-geo-count {
  font-size: 56px;
  line-height: 1;
  color: var(--bone);
}
.tv-geo-clock {
  font-size: 200px;
  line-height: .9;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.tv-geo-clock.is-low {
  color: var(--live2);
}
.tv-geo-status {
  font: 700 32px/1.2 var(--fd-body);
  color: var(--bone);
}
.tv-geo-roster {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.tv-geo-chip {
  opacity: .3;
  transition: opacity .3s ease;
}
.tv-geo-chip {
  border-radius: 50%;
}
.tv-geo-chip.is-drafting {
  opacity: .6;
}
.tv-geo-chip.is-in {
  opacity: 1;
  box-shadow: 0 0 0 4px var(--bone);
}
.tv-geo-prompt {
  margin-top: auto;
  font: 600 30px/1.3 var(--fd-body);
  color: var(--night-text);
}
.tv-geo-map {
  position: absolute;
  inset: 0;
  height: auto;
  border: 0;
  border-radius: 0;
}
.tv-geo-map .fd-geo-marker {
  width: 60px;
  height: 80px;
}
.tv-geo-map .fd-geo-head {
  width: 54px;
  height: 54px;
  border-width: 4px;
}
.tv-geo-map .fd-geo-head b {
  font-size: 24px;
  line-height: 1;
}
.tv-geo-map .fd-geo-stem {
  width: 4px;
  height: 24px;
}
.tv-geo-map .fd-geo-marker.is-answer {
  width: 70px;
  height: 70px;
}
.tv-geo-map .fd-geo-marker.is-answer .fd-geo-head {
  width: 54px;
  height: 54px;
  border-width: 6px;
}
.tv-geo-map .fd-geo-marker.is-answer .fd-geo-head i {
  width: 16px;
  height: 16px;
}
.tv-geo-answer {
  position: absolute;
  left: 28px;
  top: 28px;
  z-index: 500;
  max-width: 62%;
  display: grid;
  gap: 6px;
  padding: 20px 26px 22px;
  border-radius: 18px;
  background: var(--tv-sheen), var(--tv-glass-deep);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge), var(--shadow-3);
}
.tv-geo-place {
  font-size: 56px;
  line-height: 1.02;
  color: var(--bone);
  overflow-wrap: anywhere;
}
.tv-geo-when {
  font: 800 32px/1.2 var(--fd-display);
  letter-spacing: .03em;
  color: var(--bone);
}
.tv-geo-answer em {
  font: 500 28px/1.3 var(--fd-body);
  color: var(--muted2);
  font-style: normal;
}
.tv-geo-thumb {
  flex-shrink: 1;
  min-height: 0;
  max-height: 260px;
  width: 100%;
  object-fit: cover;
  border-radius: 10px;
  box-shadow: var(--tv-cut);
  animation: si-fade .6s ease-out both;
}
.tv-geo-results {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
.tv-geo-results li {
  display: grid;
  gap: 8px;
  padding: 12px 16px 14px;
  border-radius: 10px;
  background: var(--tv-window);
  box-shadow: var(--tv-cut);
  animation: tv-geo-row .45s cubic-bezier(.2, .8, .2, 1) calc(2.6s + var(--row, 0) * 120ms) both;
}
@keyframes tv-geo-row {
  from {
    opacity: 0;
    transform: translateX(40px);
  }
}
.tv-geo-row {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}
.tv-geo-who {
  flex: 1;
  min-width: 0;
  font: 900 40px/1.1 var(--fd-show);
  color: var(--bone);
  overflow-wrap: anywhere;
}
.tv-geo-points {
  flex-shrink: 0;
  font: 800 48px/1.05 var(--fd-display);
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.tv-geo-split {
  display: grid;
  gap: 4px;
  padding-left: 68px;
}
.tv-geo-split span {
  display: flex;
  align-items: baseline;
  gap: 14px;
  font: 600 26px/1.3 var(--fd-body);
  color: var(--bone);
}
.tv-geo-split i {
  width: 76px;
  flex-shrink: 0;
  font: 800 24px/1.3 var(--fd-display);
  font-style: normal;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted2);
}
.tv-geo-split em {
  margin-left: auto;
  font: 800 28px/1.3 var(--fd-display);
  font-style: normal;
  color: var(--muted2);
  font-variant-numeric: tabular-nums;
}
.tv-geo-results li.is-total {
  padding: 8px 14px;
}
.tv-geo-results li.is-total .tv-geo-split {
  display: none;
}
.tv-geo-results li.is-total .tv-geo-who {
  font-size: 40px;
}
.tv-geo-results li.is-total .tv-geo-points {
  font-size: 40px;
}
.tv-geo-results li.tv-geo-more {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 6px 14px;
}
.tv-geo-more-faces {
  display: flex;
}
.tv-geo-more-faces > * + * {
  margin-left: -8px;
}
.tv-geo-more b {
  font-size: 40px;
  line-height: 1.1;
  color: var(--muted2);
}
.tv-geo-none {
  font: 600 28px/1.2 var(--fd-body);
  color: var(--night-text);
}
.tv-geo.is-final {
  grid-template-columns: 1fr;
}
.tv-geo-final {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 1500px;
  margin: 0 auto;
  width: 100%;
  padding: 24px 28px;
  border-radius: 18px;
  background: var(--tv-glass);
}
.tv-geo-final ol {
  display: grid;
  gap: 10px 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.tv-geo-final ol.is-two {
  grid-auto-flow: column;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.tv-geo-final li {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 8px 20px;
