/* src/features/tv/tv-board.css */
.tv-board {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px var(--tv-edge) 54px;
}
.tv-board-stage {
  position: relative;
  flex-shrink: 0;
}
.tv-board-grid {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  grid-template-rows: var(--head) repeat(var(--rows), minmax(0, 1fr));
  gap: var(--gap);
  border-radius: 16px;
  background: var(--tv-glass-deep);
  box-shadow:
    0 0 0 10px var(--tv-glass-deep),
    0 0 0 11px var(--line),
    var(--shadow-2);
}
.tv-board:not(.is-pick):not(.is-zoom) .tv-board-grid {
  visibility: hidden;
}
.tv-board-head {
  min-width: 0;
  display: grid;
  place-items: center;
  padding: 8px 14px;
  border-radius: 14px;
  text-align: center;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge), var(--shadow-1);
}
.tv-board-head .fd-show {
  display: grid;
  gap: 2px;
  color: var(--bone);
  line-height: 1.12;
  letter-spacing: .01em;
}
.tv-board-cell {
  position: relative;
  min-width: 0;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background:
    var(--tv-sheen),
    radial-gradient(
      110% 95% at 50% 42%,
      color-mix(in srgb, var(--sun) 13%, var(--tv-window)),
      var(--tv-window) 72%);
  box-shadow:
    var(--tv-cut),
    inset 0 0 0 1px color-mix(in srgb, var(--sun) 24%, transparent),
    var(--shadow-1);
}
.tv-board-cell b {
  font-size: 84px;
  line-height: 1;
  color: var(--sun);
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
  text-shadow: 0 3px 0 var(--ink0), 0 0 22px color-mix(in srgb, var(--sun) 48%, transparent);
}
.tv-board-cell.is-played {
  background: var(--tv-sheen), var(--tv-window);
  box-shadow: var(--tv-cut);
}
.tv-board-cell.is-empty {
  visibility: hidden;
}
.tv-board.is-pick .tv-board-cell:not(.is-played) b {
  animation: tv-board-lit .5s var(--ease-out) both;
}
@keyframes tv-board-lit {
  from {
    opacity: .25;
  }
}
.tv-board-panel {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  padding: 24px 36px 28px;
  overflow: hidden;
  transition: border-color .2s ease, box-shadow .2s ease;
}
.tv-board-panel.is-zooming {
  transform-origin: 0 0;
  animation: tv-board-zoom 1200ms cubic-bezier(.32, .72, .2, 1) calc(var(--tl) + 0ms) both;
}
@keyframes tv-board-zoom {
  from {
    transform: translate(var(--zx), var(--zy)) scale(var(--zsx), var(--zsy));
  }
  to {
    transform: none;
  }
}
.tv-board-zoomvalue {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: grid;
  place-items: center;
  pointer-events: none;
  background:
    radial-gradient(
      110% 95% at 50% 42%,
      color-mix(in srgb, var(--sun) 13%, var(--tv-window)),
      var(--tv-window) 72%);
  color: var(--sun);
  font-size: var(--zfont, 420px);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 6px 0 var(--ink0), 0 0 40px color-mix(in srgb, var(--sun) 50%, transparent);
  animation: tv-take-out 380ms ease-in calc(var(--tl) + 1150ms) both;
}
.tv-board-panel-in {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  animation: tv-take-in 420ms var(--ease-out) calc(var(--tl) + 1050ms) both;
}
.tv-board-panel-head {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 28px;
  min-height: 64px;
}
.tv-board-cat {
  color: var(--bone);
  line-height: 1.15;
}
.tv-board-val {
  margin-left: auto;
  flex-shrink: 0;
  font-size: 60px;
  line-height: 1;
  color: var(--sun);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px color-mix(in srgb, var(--sun) 45%, transparent);
}
.tv-board-dd-tag {
  flex-shrink: 0;
  padding: 6px 18px;
  border: 3px solid var(--sun);
  border-radius: 12px;
  color: var(--sun);
  font-size: 36px;
  line-height: 1.15;
  transform: rotate(-3deg);
}
.tv-board-clue-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  text-align: center;
}
.tv-board-text {
  margin: 0;
  max-width: 1640px;
  color: var(--bone);
  line-height: 1.12;
  letter-spacing: .01em;
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.tv-board-text.is-compact {
  max-width: none;
  text-align: left;
  line-height: 1.15;
}
.tv-board-text.is-final {
  text-align: center;
}
.tv-board-panel.is-picture .tv-board-text {
  flex-shrink: 0;
}
.tv-board-photo {
  position: relative;
  flex: 1;
  min-height: 0;
  width: 100%;
  border-radius: 14px;
  overflow: hidden;
  background: var(--night-deep);
  box-shadow: var(--tv-cut);
}
.tv-board-photo img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.tv-board-photo.is-final {
  flex: 0 0 auto;
  height: 170px;
}
.tv-board-answer-top {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 28px;
  min-height: 0;
}
.tv-board-answer-top .tv-board-text {
  flex: 1;
  min-width: 0;
}
.tv-board-photo.is-thumb {
  flex: 0 0 auto;
  width: 340px;
  height: 200px;
}
.tv-board-panel.is-live {
  border-color: var(--lamp-live);
  box-shadow:
    var(--live-bloom),
    var(--glass-edge),
    var(--shadow-2);
}
.tv-board-panel.is-armed .tv-board-text {
  animation: tv-board-arm .5s var(--ease-land) both;
}
.tv-board-panel.is-live::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 6px var(--lamp-live), inset 0 0 60px color-mix(in srgb, var(--lamp-live) 35%, transparent);
  animation: tv-board-flash .7s var(--ease-out) both;
}
@keyframes tv-board-flash {
  from {
    opacity: 1;
  }
  to {
    opacity: .35;
  }
}
@keyframes tv-board-arm {
  from {
    transform: scale(1.025);
  }
}
.tv-board-speaker {
  display: grid;
  place-items: center;
}
.tv-board-speaker svg {
  overflow: visible;
}
.tv-board-cone path {
  fill: color-mix(in srgb, var(--lamp-live) 22%, var(--tv-window));
  stroke: var(--bone);
}
.tv-board-cone circle {
  fill: var(--bone);
}
.tv-board-waves path {
  stroke: var(--muted);
  opacity: .35;
}
.tv-board-speaker.is-live .tv-board-cone {
  transform-box: fill-box;
  transform-origin: center;
  animation: tv-board-pump .42s cubic-bezier(.3, 1.6, .5, 1) infinite alternate;
}
.tv-board-speaker.is-live .tv-board-waves path {
  stroke: var(--lamp-live);
  opacity: 0;
  animation: tv-board-wave 1.1s ease-out calc(var(--i) * .22s) infinite;
}
@keyframes tv-board-pump {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.08) translateX(-4px);
  }
}
@keyframes tv-board-wave {
  0% {
    opacity: 0;
    transform: translateX(-14px);
  }
  30% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateX(18px);
  }
}
.tv-board-order {
  flex-shrink: 0;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 16px 34px;
  margin: 0;
  padding: 18px 0 0;
  list-style: none;
}
.tv-board-order li {
  position: relative;
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 6px;
  animation: tv-board-stamp 380ms var(--ease-land) both;
}
@keyframes tv-board-stamp {
  0% {
    opacity: 0;
    transform: translateY(-40px) scale(1.5);
  }
  70% {
    opacity: 1;
    transform: scale(.95);
  }
}
.tv-board-place {
  position: absolute;
  left: -12px;
  top: -8px;
  z-index: 1;
  min-width: 44px;
