  box-shadow: 0 0 0 5px var(--lamp-info), 0 0 24px color-mix(in srgb, var(--lamp-info) 45%, transparent);
  animation: tv-karaoke-lock .4s var(--ease-land) both;
}
@keyframes tv-karaoke-lock {
