    transform: scale(1.18);
  }
}
.tv-karaoke-seat-name {
  max-width: 100%;
  font: 900 28px/1.1 var(--fd-show);
  letter-spacing: .01em;
  color: var(--muted2);
  text-align: center;
  text-wrap: balance;
  overflow-wrap: anywhere;
  transition: color .35s ease;
}
.tv-karaoke-room.is-voters .tv-karaoke-seat-name {
  font-size: 26px;
}
.tv-karaoke-seat.is-lit .tv-karaoke-seat-name {
  color: var(--bone);
}
.tv-karaoke-count {
  align-self: center;
  font-size: 56px;
  line-height: 1.1;
  letter-spacing: .04em;
  color: var(--bone);
  white-space: nowrap;
}
.tv-karaoke-order {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
}
.tv-karaoke-queue {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.tv-karaoke-queue-row {
  display: flex;
  justify-content: center;
  gap: 24px;
}
.tv-karaoke-ticket {
  width: 208px;
  height: 262px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
