  gap: 40px;
}
.tv-karaoke-vote-tiers .tv-karaoke-hero {
  flex: 0 0 auto;
}
.tv-karaoke-tiers {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.tv-karaoke-tier {
  display: grid;
  place-items: center;
  min-width: 0;
  min-height: 96px;
  padding: 10px 12px;
  border-radius: 14px;
  background: var(--tier-1);
  color: var(--tier-ink);
  box-shadow: inset 0 3px 0 color-mix(in srgb, var(--ink0) 30%, transparent);
  font: 800 30px/1.1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  text-align: center;
  text-wrap: balance;
}
.tv-karaoke-tier.is-2 {
  background: var(--tier-2);
}
.tv-karaoke-tier.is-3 {
  background: var(--tier-3);
}
.tv-karaoke-tier.is-4 {
  background: var(--tier-4);
}
.tv-karaoke-tier.is-5 {
  background: var(--tier-5);
}
.tv-karaoke-tier.is-6 {
  background: var(--tier-6);
  color: var(--tier-6-ink);
}
.tv-karaoke-legendary {
  flex: 1;
  min-height: 0;
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
}
.tv-karaoke-rain {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.tv-karaoke-rain i {
  position: absolute;
  left: var(--x);
  top: -60px;
  width: 40px;
  height: 24px;
  border-radius: 6px;
  background: var(--tier-6);
  box-shadow: inset 0 -4px 0 color-mix(in srgb, var(--ink0) 25%, transparent);
  transform: rotate(var(--r));
  animation-name: tv-karaoke-fall;
  animation-timing-function: linear;
  animation-fill-mode: both;
}
@keyframes tv-karaoke-fall {
  from {
    transform: translateY(0) rotate(var(--r));
  }
  to {
    transform: translateY(940px) rotate(calc(var(--r) + 200deg));
  }
}
.tv-karaoke-legend {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.tv-karaoke-legend-chip {
  display: grid;
  animation: tv-karaoke-land .5s var(--ease-land) calc(var(--tl) + 0ms) both;
}
.tv-karaoke-legend-name {
  font-size: 80px;
  line-height: 1.05;
  color: var(--bone);
}
.tv-karaoke-legend-song {
  font: 600 36px/1.2 var(--fd-body);
  color: var(--muted2);
}
.tv-karaoke-legend-word {
  order: -1;
  margin-bottom: -28px;
  position: relative;
  z-index: 1;
  font-size: 180px;
  line-height: 1;
  color: var(--tier-6);
  text-transform: uppercase;
  letter-spacing: .02em;
  white-space: nowrap;
  transform: rotate(-6deg);
  text-shadow:
    3px 3px 0 var(--ink0),
    -3px 3px 0 var(--ink0),
    3px -3px 0 var(--ink0),
    -3px -3px 0 var(--ink0),
    0 10px 0 var(--ink0);
  animation: tv-karaoke-word .6s var(--ease-land) both;
}
@keyframes tv-karaoke-word {
  0% {
    opacity: 0;
    transform: rotate(-6deg) scale(1.8);
  }
  60% {
    opacity: 1;
    transform: rotate(-6deg) scale(.96);
  }
}
@media (prefers-reduced-motion: reduce) {
  .tv-karaoke-rain i {
    top: var(--y);
  }
}
.tv-karaoke-reveal {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.tv-karaoke-reveal .tv-karaoke-title {
  font-size: 56px;
}
.tv-karaoke-podium,
.tv-karaoke-rest ol {
