}
.tv-karaoke-place {
  flex-shrink: 0;
  width: 52px;
  font-size: 36px;
  line-height: 1;
  text-align: center;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.tv-karaoke-row.is-podium .tv-karaoke-place {
  width: 64px;
  font-size: 52px;
}
.tv-karaoke-row.is-first .tv-karaoke-place {
  width: 64px;
  font-size: 64px;
}
.tv-karaoke-row.is-waiting .tv-karaoke-place {
  color: var(--muted);
}
.tv-karaoke-row-who {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.tv-karaoke-row-name {
  font-size: 28px;
  line-height: 1.2;
  color: var(--bone);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-karaoke-row.is-podium .tv-karaoke-row-name {
  font-size: 40px;
}
.tv-karaoke-row.is-first .tv-karaoke-row-name {
  font-size: 50px;
}
.tv-karaoke-row-song {
  font: 600 24px/1.25 var(--fd-body);
  color: var(--muted2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-karaoke-row.is-podium .tv-karaoke-row-song {
  font-size: 28px;
}
.tv-karaoke-row.is-first .tv-karaoke-row-song {
  font-size: 30px;
}
.tv-karaoke-row .tv-karaoke-tier {
  flex-shrink: 0;
  min-height: 40px;
  padding: 4px 14px;
  border-radius: 10px;
  font-size: 24px;
}
.tv-karaoke-row.is-podium .tv-karaoke-tier,
.tv-karaoke-row.is-first .tv-karaoke-tier {
  min-height: 48px;
  padding: 6px 18px;
  font-size: 28px;
}
.tv-karaoke-score {
  flex-shrink: 0;
  display: inline-flex;
  align-items: flex-end;
  font-size: 40px;
  line-height: 1;
  color: var(--bone);
}
.tv-karaoke-row.is-podium .tv-karaoke-score {
  font-size: 52px;
}
.tv-karaoke-row.is-first .tv-karaoke-score {
  font-size: 60px;
}
.tv-karaoke-score.is-none {
  color: var(--muted2);
}
.tv-karaoke-point {
  align-self: flex-end;
  flex-shrink: 0;
  width: .16em;
  height: .16em;
  margin: 0 .08em .1em;
  border-radius: .02em;
  background: currentColor;
}

/* src/features/photos/tv-photos.css */
@keyframes tv-photo-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.tv-photos {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--night-deep);
  animation: si-fade .5s ease-out;
}
.tv-photo-layer {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: var(--night-deep);
}
.tv-photo-layer.is-shown {
  opacity: 1;
  animation: tv-photo-in var(--motion-story) var(--ease-out) both;
}
.tv-photo-layer.is-under {
  opacity: 1;
}
.tv-photo-layer img {
  display: block;
  width: 100%;
  height: 100%;
}
.tv-photo-layer.is-cover img {
  object-fit: cover;
}
.tv-photo-layer.is-contain img {
  object-fit: contain;
}
.tv-photo-caption {
  position: absolute;
  left: 56px;
  bottom: 28px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 28px 10px 10px;
  border-radius: 99px;
  background: var(--chrome);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-2);
  opacity: 0;
}
.tv-photo-caption.is-shown {
  opacity: 1;
  animation: tv-photo-in var(--motion-story) var(--ease-out) both;
}
.tv-photo-name {
  font: 700 34px/1 var(--fd-display);
  letter-spacing: .01em;
  color: var(--ink);
}

/* src/features/tv/tv-records.css */
.tv-pane.tv-records-pane {
  align-items: center;
  justify-content: flex-end;
  padding-bottom: 80px;
}
.tv-record {
  position: relative;
  max-width: 100%;
  min-height: 580px;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto 1fr;
  justify-items: center;
  align-items: center;
  row-gap: 28px;
  padding: 44px 64px 52px;
  animation: tv-record-in 560ms var(--ease-out) var(--tl, 0ms) both;
}
@keyframes tv-record-in {
  from {
    opacity: 0;
    transform: translateY(22px) scale(.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-record-label {
  align-self: start;
  margin: 0;
  font: 700 32px/1.15 var(--fd-display);
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--muted2);
  white-space: nowrap;
}
.tv-record-people {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  min-width: 0;
}
.tv-record-faces,
.tv-record-names {
  display: flex;
  justify-content: center;
  gap: 28px;
}
.tv-record-faces {
  height: var(--faces-h, auto);
  align-items: center;
}
.tv-record-face {
  width: var(--col);
  flex: none;
  display: flex;
  justify-content: center;
}
.tv-record-name {
  width: var(--col);
  flex: none;
  display: block;
  text-align: center;
  line-height: 1.15;
  color: var(--bone);
  white-space: nowrap;
}
.tv-record-n {
  display: block;
  font-family: var(--fd-display);
  font-weight: 800;
  line-height: 1;
  letter-spacing: .01em;
  font-variant-numeric: tabular-nums;
  color: var(--bone);
  white-space: nowrap;
}
.tv-record-n.is-chip {
  color: var(--sun);
}
.tv-record-n.is-loss {
  color: var(--clay-text);
}
.tv-record-h2h {
  display: grid;
  align-items: start;
  column-gap: 40px;
  width: 100%;
}
.tv-record-score {
  align-self: start;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .16em;
}
.tv-record-score .tv-record-n {
  font-size: 1em;
}
.tv-record-n.is-behind {
  color: var(--muted);
}
.tv-record-to {
  font: 700 40px/1 var(--fd-display);
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted2);
  padding: 0 .4em;
}
.tv-record-people.is-left {
  animation: tv-record-left 620ms var(--ease-out) calc(var(--tl, 0ms) + 140ms) both;
}
.tv-record-people.is-right {
  animation: tv-record-right 620ms var(--ease-out) calc(var(--tl, 0ms) + 140ms) both;
}
@keyframes tv-record-left {
  from {
    opacity: 0;
    transform: translateX(-56px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-record-right {
  from {
    opacity: 0;
    transform: translateX(56px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-record-score .tv-record-n {
  animation: tv-record-stamp 380ms var(--ease-land) calc(var(--tl, 0ms) + 680ms) both;
}
.tv-record-score .tv-record-n.is-second {
  animation-delay: calc(var(--tl, 0ms) + 860ms);
}
.tv-record-to {
  animation: tv-record-fade 300ms var(--ease-out) calc(var(--tl, 0ms) + 780ms) both;
}
.tv-record-solo {
  display: grid;
  justify-content: center;
  align-items: center;
  column-gap: 88px;
  width: 100%;
}
.tv-record-solo > .tv-record-people {
  animation: tv-record-left 620ms var(--ease-out) calc(var(--tl, 0ms) + 140ms) both;
}
.tv-record-figure {
  min-width: 0;
  max-width: var(--figure-max, none);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 28px;
}
.tv-record-line {
  display: flex;
  align-items: baseline;
  gap: 20px;
}
.tv-record-line .tv-record-n {
  animation: tv-record-stamp 380ms var(--ease-land) calc(var(--tl, 0ms) + 600ms) both;
  transform-origin: 0 70%;
}
.tv-record-unit {
  font: 700 64px/1 var(--fd-display);
  letter-spacing: .04em;
  color: var(--muted2);
  animation: tv-record-fade 300ms var(--ease-out) calc(var(--tl, 0ms) + 760ms) both;
}
.tv-record-marks {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  max-width: 100%;
}
.tv-record-mark {
  display: block;
  animation: tv-record-mark 320ms var(--ease-land) calc(var(--tl, 0ms) + 900ms + var(--i, 0) * 70ms) both;
}
.tv-record-cause {
  display: flex;
  align-items: center;
  gap: 24px;
  min-width: 0;
  animation: tv-record-fade 360ms var(--ease-out) calc(var(--tl, 0ms) + 900ms) both;
}
.tv-record-cause-name {
  line-height: 1.15;
  color: var(--muted2);
  white-space: nowrap;
}
@keyframes tv-record-stamp {
  0% {
    opacity: 0;
    transform: scale(1.32);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-record-mark {
  from {
    opacity: 0;
    transform: translateY(14px) scale(.8);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tv-record-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tv-record,
  .tv-record-people,
  .tv-record-n,
  .tv-record-to,
  .tv-record-unit,
  .tv-record-mark,
  .tv-record-cause {
    animation: none;
  }
}

/* src/features/tv/tv-attract.css */
.tv-canvas[data-moment=attract]:not([data-takeover]):not([data-chase]) .tv-frame-lamps {
  display: block;
}

/* src/features/tv/tv-arrivals.css */
.tv-lobby {
  position: absolute;
  left: 0;
  top: calc(-1 * var(--tv-mast-h, 124px));
  width: 1920px;
  height: 1080px;
  pointer-events: none;
  animation: si-fade .5s ease-out;
}
.tv-lobby-pane {
  position: absolute;
  left: 50%;
  top: 150px;
  transform: translateX(-50%);
  width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 40px 40px 22px;
}
.tv-lobby-pane.is-full {
  padding-top: 50px;
}
.tv-lobby-mark {
  display: grid;
  place-items: center;
  width: 400px;
  height: 390px;
  line-height: 0;
}
.tv-lobby-count {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 20px;
  color: var(--bone);
}
.tv-lobby-reel {
  font: 800 112px/1 var(--fd-display);
  letter-spacing: .01em;
}
.tv-lobby-of {
  font: 800 52px/1.15 var(--fd-display);
  letter-spacing: .02em;
  color: var(--muted2);
}
.tv-qr-plate {
  flex-shrink: 0;
  padding: 4.5%;
  border-radius: 14px;
  background: var(--bone);
  line-height: 0;
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--lamp-info) 70%, transparent),
    0 0 30px 2px color-mix(in srgb, var(--lamp-info) 32%, transparent),
    var(--shadow-2);
}
.tv-qr-plate svg {
  display: block;
  width: 100%;
  height: 100%;
}
.tv-qr-plate path {
  fill: var(--ink0);
}
.tv-lobby-seats {
  list-style: none;
  margin: 0;
  padding: 0;
}
.tv-lobby-seat {
  position: absolute;
  width: 0;
  height: 0;
}
.tv-lobby-well {
  position: absolute;
  left: -58px;
  top: -58px;
  display: grid;
  place-items: center;
  width: 116px;
  height: 116px;
  border-radius: 50%;
  background: var(--tv-window);
  box-shadow:
    var(--tv-cut),
    0 0 0 1px var(--line),
    var(--shadow-1);
}
.tv-lobby-seat.is-road .tv-lobby-well::before {
  content: "";
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  border: 3px dashed color-mix(in srgb, var(--bone) 34%, transparent);
}
.tv-lobby-seat.is-landed .tv-lobby-well::before {
  border-color: color-mix(in srgb, var(--lamp-info) 80%, transparent);
}
.tv-lobby-chip {
  position: relative;
  display: block;
  line-height: 0;
  border-radius: 50%;
  box-shadow: var(--shadow-1);
}
.tv-lobby-chip::before {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  pointer-events: none;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--bone) 46%, transparent), 0 0 28px 5px color-mix(in srgb, var(--bone) 24%, transparent);
}
.tv-lobby-name {
  position: absolute;
  left: 50%;
  top: 63px;
  transform: translateX(-50%);
  display: block;
  max-width: 184px;
  padding: 3px 10px 4px;
  border-radius: 9px;
  background: var(--tv-window);
  box-shadow: var(--tv-cut);
  font-size: 30px;
  line-height: 1.15;
  color: var(--bone);
  white-space: nowrap;
  text-align: center;
}
.tv-lobby-name > span {
  display: inline-block;
  transform-origin: 50% 50%;
}
.tv-lobby-seat.is-road .tv-lobby-name {
  color: var(--muted2);
}
.tv-lobby-landed {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font: 800 24px/1.15 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--lamp-info);
}
.tv-lobby-landed .fd-insert {
  --lamp:var(--lamp-info);
  width: 16px;
  height: 16px;
}
.tv-lobby-chip.is-dropping {
  animation: tv-lobby-drop 1100ms linear both;
}
.tv-lobby-chip.is-dropping::before {
  animation: tv-lobby-light 1100ms var(--ease-out) both;
  animation-delay: inherit;
}
@keyframes tv-lobby-drop {
  0% {
    transform: translateY(-230px) scale(1.14);
    opacity: 0;
    animation-timing-function: cubic-bezier(.5, 0, .75, .4);
  }
  10% {
    opacity: 1;
  }
  52% {
    transform: translateY(0) scale(1);
    animation-timing-function: cubic-bezier(.2, .8, .2, 1);
  }
  62% {
    transform: translateY(5px) scale(1.07, .9);
    animation-timing-function: cubic-bezier(.3, .7, .35, 1.25);
  }
  80% {
    transform: translateY(-6px) scale(.99, 1.02);
    animation-timing-function: cubic-bezier(.2, .8, .2, 1);
  }
  100% {
    transform: none;
    opacity: 1;
  }
}
@keyframes tv-lobby-light {
  0%, 50% {
    opacity: 0;
  }
  70% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}
.tv-arrive-corner {
  position: absolute;
  z-index: 4;
  right: var(--tv-edge);
  bottom: var(--tv-safe-y);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border-radius: 18px;
  background: var(--tv-sheen), var(--tv-glass);
  border: 1px solid var(--line);
  box-shadow: var(--glass-edge), var(--shadow-2);
  transition: opacity .45s ease, transform .45s ease;
}
.tv-arrive-corner .tv-qr-plate {
  border-radius: 10px;
}
.tv-arrive-corner-faces {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
}
.tv-arrive-corner-face {
  display: block;
  line-height: 0;
  border-radius: 50%;
  filter: grayscale(1);
  opacity: .6;
}
.tv-arrive-corner-more {
  display: grid;
  place-items: center;
  min-width: 40px;
  height: 40px;
  padding: 0 6px;
  border-radius: 99px;
  border: 2px dashed var(--ghost-line);
  font: 800 24px/1 var(--fd-display);
  color: var(--muted2);
}
.tv-canvas:is([data-takeover], [data-moment]) .tv-arrive-corner {
  opacity: 0;
  transform: translateY(60px);
}
.tv-canvas.has-arrive-corner :is(.tv-ticker-glass, .tv-ticker-page) {
  right: calc(var(--tv-edge) + var(--tv-corner-room, 236px));
}
.tv-tower-label.is-road .tv-tower-name,
.tv-tower-label.is-road .tv-tower-pts {
  color: var(--muted);
}
.tv-flat-slot.is-road .tv-flat-stand {
  opacity: .42;
  filter: grayscale(.7);
}
@media (prefers-reduced-motion: reduce) {
  .tv-lobby-chip.is-dropping,
  .tv-lobby-chip.is-dropping::before {
    animation: none;
  }
  .tv-lobby,
  .tv-arrive-corner {
    animation: none;
    transition: none;
  }
}

/* src/features/tv/tvScenes.css */
.tv-bracket-team {
  position: relative;
}
.tv-bracket-line.is-on path {
  stroke-width: 3px;
}
.tv-bracket-team.is-lost .tv-bracket-faces {
  opacity: .45;
  filter: grayscale(1);
}
.tv-bracket-upnow {
  position: absolute;
  z-index: 2;
  border: 3px solid var(--bone);
  border-radius: 14px;
  pointer-events: none;
}
.tv-bracket-upnow-tab {
  position: absolute;
  right: -3px;
  top: -38px;
  display: inline-flex;
  align-items: center;
  padding: 5px 12px 4px;
  border-radius: 8px 8px 0 8px;
  background: var(--bone);
  color: var(--ink0);
  font: 800 24px/1.1 var(--fd-display);
  letter-spacing: .08em;
  text-transform: uppercase;
  white-space: nowrap;
}
.tv-bracket-upnow-tab .fd-beat-dot.tv-beat {
  width: 12px;
  height: 12px;
  margin-right: 8px;
  vertical-align: 0;
}
.tv-br-win {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  background: var(--bone);
  color: var(--ink0);
  animation: tv-br-wipe 240ms var(--ease-out) calc(var(--tl) + 0ms) both, tv-br-unfill 500ms ease-in-out calc(var(--tl) + 2700ms) both;
}
.tv-bracket-team .tv-br-win .tv-bracket-name {
  color: var(--ink0);
}
.tv-br-stamp {
  flex-shrink: 0;
  font: 800 28px/1 var(--fd-display);
  letter-spacing: .06em;
  text-transform: uppercase;
  animation: tv-br-stamp var(--motion-stamp) var(--ease-land) calc(var(--tl) + 120ms) both;
}
.tv-bracket.is-full .tv-br-stamp {
  font-size: 34px;
}
@keyframes tv-br-wipe {
  from {
    clip-path: inset(0 100% 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}
@keyframes tv-br-unfill {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes tv-br-stamp {
  from {
    opacity: 0;
    transform: scale(1.6) rotate(-8deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tv-bracket-team.is-lose-moment .tv-bracket-name {
  animation: tv-br-lose-name 300ms ease-out calc(var(--tl) + 250ms) both;
}
.tv-bracket-team.is-lose-moment .tv-bracket-faces {
  animation: tv-br-lose-faces 300ms ease-out calc(var(--tl) + 250ms) both;
}
@keyframes tv-br-lose-name {
  from {
    color: var(--bone);
  }
  to {
    color: var(--muted);
  }
}
@keyframes tv-br-lose-faces {
  from {
    opacity: 1;
    filter: none;
  }
  to {
    opacity: .45;
    filter: grayscale(1);
  }
}
.tv-br-rail {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  overflow: visible;
  pointer-events: none;
}
.tv-br-rail path {
  fill: none;
  stroke: var(--bone);
  stroke-width: 3px;
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
  animation: tv-br-draw 800ms cubic-bezier(.65, 0, .35, 1) calc(var(--tl) + 760ms) both;
}
@keyframes tv-br-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.tv-br-token {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 3;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px;
  border-radius: 99px;
  background: var(--paper);
  border: 3px solid var(--bone);
  box-shadow: var(--shadow-2);
  opacity: 0;
  pointer-events: none;
  will-change: transform;
}
.tv-bracket-team.is-arriving > :not(.tv-br-was) {
  animation: tv-br-arrive 160ms ease-out calc(var(--tl) + 1540ms) both;
}
.tv-br-was {
  position: absolute;
  left: 14px;
  top: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  animation: tv-br-leave 120ms ease-out calc(var(--tl) + 1540ms) both;
}
.tv-br-was .tv-bracket-name {
  color: var(--muted);
}
@keyframes tv-br-arrive {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes tv-br-leave {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
.tv-bracket-match.is-landing {
  animation: tv-br-land 320ms var(--ease-out) calc(var(--tl) + 1540ms) forwards;
}
@keyframes tv-br-land {
  0% {
    transform: none;
    border-color: var(--bone);
  }
  40% {
    transform: translateY(5px);
    border-color: var(--bone);
  }
  100% {
    transform: none;
    border-color: var(--line);
  }
}
.tv-contest-slot {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.tv-advance.is-slot {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
  padding: 16px 32px;
  text-align: left;
  border: 1px solid var(--ghost-line);
  border-radius: 18px;
}
.tv-advance-who {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
}
.tv-advance-line {
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: 0;
  max-width: 100%;
}
.tv-advance.is-slot .tv-advance-name {
  font-size: 56px;
  min-width: 0;
}
.tv-advance.is-slot .tv-advance-stamp {
  font-size: 96px;
}
.tv-advance.is-slot .tv-advance-detail {
  font-size: 30px;
}
.tv-advance.is-slot .tv-settle {
  margin-top: 0;
  flex-shrink: 0;
}
.tv-advance-call {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}
.tv-advance.is-slot.has-settle {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 22px;
  padding: 22px 36px;
  overflow: hidden;
}
.tv-advance.is-slot.has-settle .tv-advance-who {
  flex: 0 0 auto;
  gap: 6px;
}
.tv-advance.is-slot.has-settle .tv-advance-name {
  font-size: 56px;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tv-advance.is-slot.has-settle .tv-advance-call {
  flex-direction: row;
  align-items: center;
  column-gap: 36px;
  max-width: 100%;
}
.tv-advance.is-slot.has-settle .tv-advance-stamp {
  font-size: 84px;
  flex-shrink: 0;
}
.tv-advance.is-slot.has-settle .tv-advance-detail {
  min-width: 0;
  row-gap: 2px;
  column-gap: 28px;
  white-space: nowrap;
}
.tv-advance.is-slot.has-settle .tv-settle {
  justify-content: flex-start;
  gap: 24px;
  max-width: 100%;
}
.tv-advance.is-slot.has-settle .tv-settle-zone {
  min-width: 0;
  padding: 12px 22px;
}
.tv-advance.is-slot.has-settle .tv-settle-head {
  font-size: 44px;
}
.tv-canvas:has(.tv-crown) .tv-mast {
  z-index: 2;
}
.tv-mast-title,
.tv-mast-edition,
.tv-status {
  transition: color .3s;
}
.tv-canvas:has(.tv-crown.is-flooded.is-ink-dark) :is(.tv-mast-title, .tv-mast-edition, .tv-status) {
  color: var(--ink0);
}
.tv-canvas:has(.tv-crown.is-flooded.is-ink-bone) :is(.tv-mast-title, .tv-mast-edition, .tv-status) {
  color: var(--bone);
}
.tv-crown {
  position: absolute;
  inset: 0;
}
.tv-crown-flood {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(-1 * var(--tv-mast-h, 118px));
  bottom: 0;
  z-index: 2;
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--ink0) 55%, transparent), inset 0 0 96px color-mix(in srgb, var(--ink0) 24%, transparent);
  background:
    var(--lg-bands),
    radial-gradient(
      64% 78% at 66% 48%,
      transparent 46%,
      color-mix(in srgb, var(--ink0) 34%, transparent) 100%),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--bone) 12%, transparent),
      transparent 26%),
    var(--champ-color);
}
.tv-crown-flood::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 46%;
  height: 52%;
  pointer-events: none;
  background:
    radial-gradient(
      circle,
      color-mix(in srgb, var(--ink0) 16%, transparent) 0 1.6px,
      transparent 2.4px) 0 0 / 10px 10px;
  -webkit-mask-image:
    linear-gradient(
      to top left,
      var(--ink0),
      transparent 70%);
  mask-image:
    linear-gradient(
      to top left,
      var(--ink0),
      transparent 70%);
}
.tv-crown:not(.is-playing) .tv-crown-coin-spin {
  animation: tv-coin-show 9s ease-in-out infinite;
}
@keyframes tv-coin-show {
  0%, 100% {
    transform: rotateY(-16deg) rotateX(4deg);
  }
  50% {
    transform: rotateY(16deg) rotateX(-3deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .tv-crown:not(.is-playing) .tv-crown-coin-spin {
    animation: none;
  }
}
.tv-crown .tv-champ {
  position: absolute;
  z-index: 3;
  inset: 0;
  margin: 0;
  padding: 16px 64px 54px;
  gap: 56px;
  background: transparent;
  border: 0;
  border-radius: 0;
  color: var(--champ-ink, var(--bone));
}
.tv-crown .tv-champ.is-bleed {
  grid-template-columns: 744px minmax(0, 1fr);
  padding-left: 56px;
}
.tv-champ.is-bleed .tv-champ-body {
  padding: 0 0 0 8px;
}
.tv-champ.is-bleed .tv-champ-prize {
  position: static;
}
.tv-champ.is-bleed .tv-champ-sky {
  position: absolute;
  left: 0;
  top: calc(-1 * var(--tv-mast-h, 96px));
  width: 800px;
  height: 1080px;
  border: 0;
  border-radius: 0;
}
.tv-champ.is-bleed .tv-champ-sky svg {
  display: block;
}
.tv-champ.is-bleed .tv-champ-trophy {
  bottom: 56px;
}
.tv-champ.is-bleed .tv-champ-body {
  justify-content: center;
  gap: 44px;
}
.tv-crown.is-playing .tv-champ.is-bleed .tv-champ-sky {
  left: -24px;
}
.tv-crown.is-playing .tv-champ.is-bleed {
  padding-left: 56px;
}
.tv-canvas:has(.tv-crown) :is(.tv-ticker, .tv-horizon) {
  visibility: hidden;
}
.tv-crown.is-tied .tv-champ {
  inset: 0 64px 54px;
  padding: 28px 48px;
  background: var(--night2);
  border: 1px solid var(--ghost-line);
  border-radius: 18px;
}
.tv-crown .tv-champ-faces {
  align-items: center;
  gap: 24px;
}
.tv-crown-coin {
  display: inline-block;
  flex-shrink: 0;
  perspective: 1400px;
}
.tv-crown-coin-spin {
  display: block;
  transform-style: preserve-3d;
}
.tv-crown-word {
